/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160627-8","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"建設委員会","time":"午前１０時００分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"第６１号議案、品川区営住宅条例の一部を改正する条例","agenda":"第６１号議案、品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"新たに建替えなのでということで、こうした利便性が上がるために利用料も上がっていくと。２の(2)減額措置の内容というところで、５年間にわたって急激な上昇を防ぐ、区独自で決められないものなのかを伺いたいと思います。","respondent":"今井住宅課長","answer":"こちら、条例の引用にもありますけれども、公営住宅法の第４３条および公営住宅法施行令の第１１条に基づきまして、６分の５、６分の４という形で、このような減額措置が決まっているところで、ここは法律によって定められているものです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"法律で決まっているということですけれども、それをもうちょっと年数を広げるとか、もうちょっと上げる幅を狭めていくとか、そういうことは区独自ではできないということか尋ねました。","respondent":"今井住宅課長","answer":"こちらにありますとおり、５年間の使用料の減額というのを法律または施行令で定めておりますので、この年数自体は変えられるものではございません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"意見","question":"先ほども言いましたけれども、やはり建替えに応じて値上げがされるということ自体は、なぜかなとずっと思っているところですけれども、減免は必要な措置だというところで、この条例には賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"第６２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第６２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この地区計画の変更ということで、都市計画審議会で可決されて今回この条例が出されていると思うのですけれども、そもそも、資料にも改正理由というのが書かれているのですけれども、この地域がこういうふうに変更されるという大もとをもうちょっと具体的に聞かせていただけないか尋ねました。","respondent":"寺嶋木密整備推進課長","answer":"火災危険度、建物倒壊危険度が高いということで、いわゆる木密地域不燃化１０年プロジェクトの不燃化特区という地区に指定されているエリアです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"意見","question":"それで、高さ制限がついているということで、この高さというのは、まちの環境を見て決められる、決まった何かがあって変えられるのか、そこがよくわからないのですけれども、お願いしますとの意見を述べました。","respondent":"寺嶋木密整備推進課長、鈴木建築課長","answer":"重点的に建替えを促進したいということで、まず２項道路でセットバックしていただいた上に、残った敷地の中でさらに道路から５０cm離して建てると。３階建て、４階建てで切りましょうということで設けた高さ制限なので… 今の補足の説明ですが、木密整備推進課長がご説明したとおりなのですけれども、建替えを促進していきましょうという内容です。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"確認","question":"地域の方々がどうかというのが一番心配されるところですけれども、この地区計画のここのところでも高くて３階ですよね。そんなに高過ぎるものではないというのが確認できたので、もうされているのでしょうか、これからなのか尋ねました。","respondent":"寺嶋木密整備推進課長","answer":"平成１９年度から、地域での検討会、１０年近い中での地元の人との意見交換をやってきたという経緯があります。２回という説明会のところ、地区を分割して９回に分けての素案説明会、これも３回実施してきたという。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この地域、不燃化に向けた木密ということで、こういう制限がかかったということだと思うのですが、この考え方というのは、ほかの地域に及んでいく可能性というのはどうなのか尋ねました。","respondent":"寺嶋木密整備推進課長","answer":"当然ですけれども、地元の方には一定程度ご負担が何かしらかかってくるという前提があるので、ここは慎重に区としては対応していくということです。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば２つに分ければ建売屋が入って、中途半端な数字というか、次が使いにくい面積の土地というのがあるではないですか。１２０m2を超えていれば６０m2ずつできるけれども、その辺は当然考慮した上でこの地域の方も了解しているということでよろしいのですよね。","respondent":"寺嶋木密整備推進課長","answer":"ただいま委員からご指摘いただいた内容が、実際に説明会で一番多く出たご質問であることは記憶しております。４割は空地ですから、その辺の防災性の必要性も含めてご説明してきた上で、計画化したと。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"公的に今後においても地元とうまく説明をしていただいて、ご理解いただけるような形をとっていただきたいと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"６０m2という一つの線で空地をそれだけつくっていこうという狙いなのだということで、６０m2という敷地の区画というのですか、の方々がどれぐらいいらっしゃるのかというのを説明するよう求めました。","respondent":"寺嶋木密整備推進課長","answer":"検討会当時から事業導入に向けてした調査での数値なので、８割程度の建物は６０m2を超えていたという、そういった数値があります。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"建替えの促進策というのですか、すごく長いスパンで考えることになるので、それをより促進していくための方策というのは何か考えているのか。中に建物を新しく建てようとしても６０m2にまとめていかなければいけないというところも出てくるのかと思うのですけれども、今現在何かありますか。","respondent":"寺嶋木密整備推進課長","answer":"説明が詳細までできずに申し訳ございません。それから不燃構造化支援という形で、よりスピーディーな対応に努める、こういった形の支援策となっております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"そうすると、その人たちに対してのアプローチというのをどういうふうにしていくのか。そこだけでも整備しようかというところがあれば、そこも推進できるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"寺嶋木密整備推進課長","answer":"そこまで逆に大規模な合意が得られてというのは、なかなか事業としてやろうとした場合、大変難しい。周りに影響を与えるような建物でないような数字ということでの検討が一定程度されて出した数字ということなので、区としては心配はしていないです。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"こういう方法もあるということをお願いしたいと思うのですが、情報提供をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-03","title":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"しながわ環境ミュージカルなのですけれども、これは何で補正に加わってきたのかということと、あと、７０周年記念事業に組み込んだ経緯を聞かせてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"平成２７年度は３月３０日、年度末に行いまして、補正を組ませていただきました。区制７０周年記念事業の中でシティプロモーション事業を実際に行いますけれども、区制７０周年にふさわしいというものが考えられましたので。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"意見","question":"大好評だったということで、そうすると、プレス発表にも７０周年記念事業が出ていまして、いろいろなことをやられるのだなとは思ったのですが、しながわ環境ミュージカル自体はいつ頃やると書いてありましたかとの意見を述べました。","respondent":"三ツ橋環境課長","answer":"こちらの日にちにつきましては、平成２９年１月２２日の日曜日です。プレス発表につきましても、日付等が記載されていなかったかもしれませんが、こちらは１月２２日ということになっております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、３０、３１ページの、立会川雨水放流管建設関連整備、ここはどういったことなのか、基本計画というのは何なのかを伺いたいと思います。","respondent":"和田河川下水道課長","answer":"月見橋の家を再建しまして、今、仮設で運営しているものを本設として戻っていっていただく予定になっております。この基本計画策定委託といいますのは、戻ってくる月見橋の家の建築の計画を行うものです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"月見橋のデイサービスだったと思うのですけれども、そこに総務部分室もあったと思うのですが、それも変わらずといいますか、元のままに戻ってくるという形か尋ねました。","respondent":"和田河川下水道課長","answer":"おっしゃるとおり、総務部分室も同様に戻ってまいります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちも何度も総務部分室がどういったものなのかというのを見せていただこうといろいろしてきたのですけれども、なかなか実態がわからなくて、それで、やはり全てをデイサービスとして広げて、こちらに戻ってくるときには使っていただきたいという要望を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから、西五反田二丁目・三丁目付近の工事が２年に延長になってしまうということで、延長になった理由をもう少し詳しくお伺いしたいと思います。実態調査というのはどういったことをされるということで９５０万円なのかということ、実態調査の内容について詳しくご説明ほしいと求めました。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"第１回目よりも増額しております。こちらの理由といたしましては、区制７０周年にふさわしいものとなるようバージョンアップをしたためです。 監視カメラを設置しまして、それからマナーのパンフレットの作成、それらの周知などです。来年度の桜の時期を目指して、何か対策ができないかということを検討するために、この委託の計上に至ったです。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"どのようなところでさらに前回と比べて力を入れて、変化があるのかというところで、もうちょっと具体的にお伺いしたいと思います。船の運航上の守らなければいけない法律というのはあると思うのですけれども、そういうものに抵触する類いの話になるのかという、そこをお伺いしたい。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"昨年は募集が小学生まででございましたのを、高校生まで広げて練習を一気にやっていきますので、練習量が大分増える。環境に配慮したことをもっと広く取り組んでいくことを思いまして、そちらが一番バージョンアップの点です。これには２年か３年ぐらいかかるということで、これについては今回の委託で設置した監視カメラのデータなどを我々が提供していくというようなことで。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。今のところ、ぜひ来年の桜の時期に向けて万全な対策会議等が行われるということなので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私も近くで結構見ているのですけれども、スピードを出して危ないなというのを結構見かけますので、ぜひよろしくお願いします。河川費の中で２つあるのですけれども、津波・高潮対策事業、これの中身をもう少し説明していただけますか尋ねました。","respondent":"和田河川下水道課長","answer":"この目黒川避難勧告等発令基準運用検討委託というものですけれども、明日の建設委員会で、これについてのご報告をする予定になっております。実効性を持たせるか、この辺の検討をすることを目的としたものが、補正予算に計上いたしました検討委託ということになってあります。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中身については、明日、確認をしますが、それが一点気になりました。自民党からもずっと要望していた件なので、具体的にどのような形になるか、少し具体的なことを教えていただけますか。","respondent":"和田河川下水道課長","answer":"それから階段とかスロープを設けまして、陸まで上がれるような桟橋とスロープ、これらを建設する費用を計上したものです。１０月からもともと舟運の社会実験をやるということは昨年から決まっていたものですので、活用しようということも考えているところです。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私どももずっと要望して、本会議でも質問ありましたけれども、ぜひお願いしたいと思います。その辺、それは専門の方がやるのでしょうから、そういうときに対しても十分対応できるようにお願いしたいということを要望します。","respondent":"和田河川下水道課長","answer":"今、建設局と協議中ですので、決定事項ではございませんけれども、脇に橋梁用の敷地が現在空き地としています。この辺を整備できないかということを、今、建設局と協議をしています。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、聞いて思い出しましたけれども、大田区の海老取川、そこの船着き場を一回使わせてもらったのですけれども、たしかあそこに待合所をつくって、トイレなんかも整備していたので、その辺も十分検討してほしいと求めましたので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"目黒川監視カメラ設置工事についてなのですけれども、監視カメラ設置の具体的な場所とか、幾つぐらいつけるのかをお聞きします。","respondent":"和田河川下水道課長","answer":"この委託の中で、どの場所につければ実効性を持った監視カメラの設置ができるかということも含めて検討していきたいというふうに考えています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"まだ検討段階ということですね。結構運河から目黒川に入ってくるパターンが多いかと思うのですけれども、将来的に運河周りに監視カメラを設置するというご予定はあるのか尋ねました。","respondent":"和田河川下水道課長","answer":"実は先ほど説明しました東品川清掃作業所前のところにつけると、運河を見られるようにというものも計上しています。これはまだ検討の段階ですので、今、この委託に関しては目黒川のみを監視するものということで計上しているものです。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"財源を確認したいのです。その辺の財源とこの事業をするにあたっての理由を聞きたいと思うのですが。","respondent":"和田河川下水道課長","answer":"３１ページに限って申しますと、上の４目受託事業費に係る費用については、区からの持ち出しはございません。それから、６款土木費３項以下につきましては、これは品川区の単費ということになってあります。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"東京都のほうからの受託ですから、それは迅速に対応していく必要があると考えていますし、その一環なのだろうというふうに考えております。補正でやるよりも、当初予算の中に入れることはできなかったのかというところだけお伺いしたいのですけれども。","respondent":"和田河川下水道課長","answer":"目黒川について、この３月、４月の桜の時期に起こった問題、苦情、これに対応することですので、本予算には計上できなかったです。最後に津波・高潮対策の検討委託ですけれども、これが５月に庁内で決定をいたしましたので、これも本予算には計上できなかったというものです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"であるならば、１年間やっているのだったら、１年前倒しでこういう予算が計上されていかなければいけないものなのではないかと思うのです。それが、例えば去年の予算の中にあって、今回のものはまた別に何かをするためにここで計上しなくてはということなのか、それだけお願いします。","respondent":"和田河川下水道課長","answer":"ここまで避難情報を的確に区民の皆様へ情報伝達する方法というものが必要だというところまでの認識がなかったです。かつ検討委託の期間なのですけれども、これは明日詳しく説明しますけれども、この説明と議案の説明が前後してしまったところなのですが。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"要は、１年間いろいろと試行錯誤して、いろいろ検討されていた部分があって明日発表されると思うのですが、今回、補正がかかったこの予算については、また別なことをするという意味なのか尋ねました。","respondent":"和田河川下水道課長","answer":"報告が前後して説明が難しいのですが、こういうときになったら避難指示を発令しますという基準を決めたというところまで明日報告するというものです。伝達方法の仕組みも整えた上で、これを避難基準を策定した後にやっていくということですので、一連の流れの中でというものです。","id":"exchange-031"},{"speaker":"木村副委員長","kind":"質問","question":"今の伝達方法の検討委託、基準は明日発表ですけれども、それは危険な地域の住民の方々で何か連絡を欲しいということを申請したところにはもちろんですけれども、それ以外にはどのようにして避難をさせるのか尋ねました。","respondent":"和田河川下水道課長","answer":"今、想定の範囲内で答えしますけれども、何かあったときにその電話番号に危険を知らせる連絡は来るというようなことを想定しているものです。ですから、区民の方々から申請を受けてやっていくということを想定しています。","id":"exchange-032"}]},{"id":"topic-04","title":"の区営住宅入居者募集","agenda":"の区営住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、ご説明の中で、私、そもそものところを伺いたいと思うのですけれども、１月と７月に募集をするということですよね。そうすると、前回が１月だったということなのですが、そのときは大体空きはどれくらいあったのかを説明するよう求めました。","respondent":"今井住宅課長","answer":"１月の募集につきましては、８戸です。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"この募集について本当に待ちわびているという状況なのです。やはり今回１７戸ということで、大体、前回１月は８戸に対してどれぐらいの募集があったかを伺いたいと思います。","respondent":"今井住宅課長","answer":"申し訳ありません、それぞれの月ごとの応募件数は手元にないのですけれども、事務事業概要にありますとおり、平成２７年度中につきましては、１月が８戸、前年の平成２７年７月が３戸で、募集数１１戸に対しまして、空き室の応募件数は５６６件でございました。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"入りたくても入れない状況ですので、今回、７月の１７戸についてもたくさんの応募がされるのだろうと思います。ぜひ増設を進めていくことを求めたいと思いますけれども、その点はいかがか尋ねました。","respondent":"今井住宅課長","answer":"これまでも予特・決特でご説明していますとおり、今後は長寿命化の対策の中で、建替えに伴っては従前の戸数を維持しながら運営していく考えです。高齢者世帯については、高齢者地域支援課の民間住宅の融資あっせん等も含めまして、区全体で対策をとっていくものです。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、住宅の問題は本当に私たちもたくさん相談を受ける状況ですので、安心して住めるというところでは区営住宅は本当に求められていると思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-05","title":"空き家対策に伴う行政代執行","agenda":"空き家対策に伴う行政代執行","exchanges":[{"speaker":"高橋（伸）委員","kind":"意見","question":"二、三台ということで、了解いたしました。例えば職員の方がつくとか、警備員の方がつくとか、その辺の状況もあわせてお願いしますとの意見を述べました。","respondent":"今井住宅課長","answer":"両方とも面しているところが私道ですので、私道の出入り口３カ所に職員を配置いたしまして、交通の誘導をしようというふうに考えております。文教大学付属幼稚園がありますので、そちらのほうの時間帯にはパッカー車の通行等が行かないように、今、検討を進めているところです。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ幼稚園の園児さんとかもいるので、安全には十二分に配慮していただき、代執行を行ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"コスト的にはどのぐらいのコストがかかろうとしているのかというところ、それを本人に請求するのかということで、それはどう考えられているのですか。それからご本人、この方は、いろいろな区の働きかけによってどういう対応をしていたのか尋ねました。","respondent":"今井住宅課長","answer":"ご自分の堆積物については、私道上のものにつきましても、ごみではないというふうな認識でいらっしゃったと聞いております。なかなかご自分では撤去できないというふうに考えまして、廃棄物等適正管理審議会の答申を受けて、決定いたしました。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"それを今後どういうやり方をしていくのかということ。協力体制をとって、また繰り返さないようにという対策も同時にとっていく必要があると思うのですが、いかがか尋ねました。","respondent":"今井住宅課長","answer":"今回はこの建物に住んでいる方への対応になりますので、所管を配置いたしまして、対応していくというふうな考えです。区として、全庁的に連携をして、対応していく案件だと認識しております。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"区内２件目の行政代執行の予定ということですけれども、基本的には１階のほう、どの辺までが代執行の対象になるのかというのを教えてほしいと求めました。","respondent":"今井住宅課長","answer":"Ｌ字溝が設置されているということも確認しておりますので、２項道路に広く分散しておりますので、そのままにせざるを得ないかと。ただし、Ｌ字溝からこちら、私道といいますか、２項道路の部分については、私ども確認をいたしまして、撤去します。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"ぴたっとこういうふうには取り除けないと思うので、その辺は現場対応ということになるのですかね。なるべくならやっていただければありがたいのではないかと思いますけれども。","respondent":"今井住宅課長","answer":"軽貨物がどのように設置されているかというところなどを確認しているのですけれども、そこの部分は一切動かさないことになるかと思います。またシートを被せするような形で、今後、それがまた風によって飛び去らないような対応もしていきたいというふうに思っております。","id":"exchange-042"}]},{"id":"topic-06","title":"中央新幹線北品川非常口及び変電施設新設に係る工事説明会の開催","agenda":"中央新幹線北品川非常口及び変電施設新設に係る工事説明会の開催","exchanges":[{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、そもそもこの非常口と変電施設は何のために必要なのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"先ほどもお話しさせていただきました非常口というところで、リニア中央新幹線がこの位置を通るというところで、それに合わせてつくられるものです。変電施設も同じ、リニア新幹線の整備に係るものです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"この工事、４ページとか３ページとかを見ても、かなり大規模なものになると思います。品川学園の近くで、東海旅客鉄道株式会社のほうにも伝えていただければいいかなと思っていますけれども、今のご認識としてはどうお考えか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"区のほうも以前の議会などでも取り上げられておりますので、きちんと説明をするようにということで、東海旅客鉄道のほうにはお話をしています。６月６日、品川学園へ行きまして、説明をさせていただきましたという報告を受けてあります。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"もっと詳しくされると思うのですけれども、実際にこの工事で地域に影響が、どんなことがあるというふうに考えたらいいのでしょうか。トラックの交通だったり、騒音・振動等々、相当ある感じなのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"これに対しましては、ピーク時で１日１６０台ぐらいということで、今、聞いているところです。やはりそういった影響を、地域の交通の安全に気をつけていただきたいというところを、私どものほうからも申し入れをしています。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ影響は小さいほうがいいのですけれども、こうした振動だとか騒音というのがあったとき、住民は区に言えばいいのでしょうか。そうした区民の思いに対しては、区はどのように対応していく予定か尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"ここがわからないという場合につきましては、私ども区のほうへ連絡いただければ、つないでいきたいと考えています。そういったところを注視しながら、いろいろな問題も出ているということを把握しながら、見ていきたいと考えています。","id":"exchange-046"},{"speaker":"西本委員","kind":"確認","question":"工事中に交通誘導員２名、７時半から８時半とあったのですが、これは学校のほう等々に確認をされているのでしょうか。通勤の時間帯というのはいろいろ変わっている部分があるので、そこの確認をした上での時間を書かれているのかどうか、どうなっているのか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"当然、通勤の方々にも配慮しというところで、この時間帯を設定しているということで聞いてあります。通学・通勤時間帯、一般的な時間帯、７時半から８時半というところでの設定をしているというふうに聞いてあります。","id":"exchange-047"},{"speaker":"西本委員","kind":"確認","question":"一般的というよりは、品川学園の校長先生等々と話をして、この時間帯で大丈夫でしょうかという確認は必要なのではないかと思うのです。学校のほうが、この時間だったら大丈夫ですというふうに確認をとるととらないとでは大きな違いが出てくると思うので、その辺はいかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"先ほどもお話しさせていただきました品川学園のほうには事前にご説明をされているというところで、こちらの時間についても確認をとられているというふうに理解しております。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":35556,"voices":149}},{"id":"h28-20160627-9","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"文教委員会","time":"午前１０時００分～午前１１時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"第５８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第５８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"文言の問題だと思うのですけれども、１点確認させてください。私が追いかけられていないだけで、既に存在するのか尋ねました。","respondent":"熊谷指導課長","answer":"教員ですけれども、義務教育学校の免許というのは現在ございませんで、原則、小学校免許で前期課程、それから中学校免許で後期課程を指導可能ということで、今後、原則として小・中両方の免許を有している事が義務教育学校の教員免許ということになります。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、この文言を新たに加えることによって、新たにこれまでの規定では資格がなかったけれども、義務教育学校を加えたことで、枠が増えるというわけではないという事なのか、それとも、免許というのと「資格を有する」というのは範囲が違うのか尋ねました。","respondent":"高山子ども育成課長","answer":"この文言が追加されたことによって直ちに何か影響があるということではございませんが、将来的なものを見越して、こういったものをこの機会に整備するといったものです。","id":"exchange-002"},{"speaker":"あべ委員","kind":"意見","question":"頭の中を整理すると、厚労省に従って文言を変えるけれども、今のところは対象が広がるわけではないけれども、将来的にそれができたときにも対応できるようにということでよろしいですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"今のところは別に不具合がないということだったので、将来のことを考えると、どんな感じなのか。そこのところをわかる範囲で教えてくれませんか。","respondent":"熊谷指導課長","answer":"義務教育学校は免許がいついつできますということではなくて、両方の免許を持っている者が義務教育学校の教員として配置されるということになります。ただ、当面の間は、先ほどお話ししたように、小学校免許は前期課程、中学校免許は後期課程ということになっております。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、特に今の状況で変わらないし、将来、義務教育学校の両方の免許が必要となっても、小学校、中学校を持っていれば指導員に十分なれるということで、文言が加わっただけという捉え方でよろしいのか尋ねました。","respondent":"高山子ども育成課長","answer":"繰り返しの説明になってしまうのですが、全く同じ要件で従うべき基準ということで同様の記載が必要になってまいりますので、対応できるような形とするです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけ表現がわからなかったのですが、資料のところの(3)の「義務教育学校」の後に「高等学校または中等教育学校」、この「中等教育学校」というのは具体的にどういうところなのか、すみません、説明を求めました。","respondent":"熊谷指導課長","answer":"中等教育学校は、今、都立学校で５校ありますけれども、あとは九段中等教育学校、区立学校が１校ありますが、これはやはり同じように、中学校と高等学校の免許を両免持っている者ということになります。","id":"exchange-006"}]},{"id":"topic-02","title":"正する条例、(3)第６０号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(4)第６３号議…","agenda":"正する条例、(3)第６０号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(4)第６３号議…","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"４点確認させていただきたいのですけれども、これは戸籍上の子どもの数で数えてということでよいのかということが１点です。４点目が、第６０号議案の認定こども園、教えてほしいと求めました。","respondent":"竹田保育課長","answer":"４月１日にさかのぼって適用されるのかということですが、本会議議決後、保護者の方に適宜ご連絡したいと考えております。約７５園程度、それから私立幼稚園が１８園、それから特定地域型保育事業のほうが２３園程度となっております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"確認","question":"すると、第１子には数えられないということでしょうか。認定こども園７５園等の数を教えていただきましたけれども、確認ですが、もう一度お願いいたします。","respondent":"竹田保育課長","answer":"私立の認定こども園は、区内では２園です。大変失礼しました。","id":"exchange-008"},{"speaker":"のだて委員","kind":"確認","question":"私立幼稚園と特定地域保育型施設のほうも、この数で正しいのか、もう一度確認です。","respondent":"竹田保育課長","answer":"区内の私立幼稚園は１８園あるのですが、私立の園は１８園あるのですけれども、実際にはこの制度の直接の対象を受けるのはゼロです。国が要綱を改正するというふうに聞いておりますので、区内の私立幼稚園に通われている方につきましても、同様の処遇を受ける予定です。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"多子軽減が、これまでも我が会派としては戸籍上のということで求めてきて、それが拡大されたことは喜ばしいと考えています。ぜひ撤廃していってほしいと求めましたけれども、伺います。","respondent":"竹田保育課長","answer":"今回の制度改正は、国全体で、国の省令、政令等の改正に伴いまして全国的に行われるものです。金額が高額になりますので、一自治体の裁量で幼児教育全部を無償化していくというのは、なかなか難しいというふうに考えております。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそれも念頭に入れて、子どもはみんな同じ子どもですから、同じ軽減を受けられるように検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、国の制度の変更に伴ってということですが、この制度変更によりまして、品川区の子どもたち、どれくらい恩恵を受けるのか、人数的なところというのがわかりましたら、教えてほしいと求めました。","respondent":"竹田保育課長","answer":"試算ですが、多子軽減を受ける方が約４０人程度、それから、ひとり親世帯が約６０人程度というふうに試算しております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"確認","question":"それとも、調査か何かをかけて、もう一回対象者を見ていくということでしょうか。確認したいと求めました。","respondent":"竹田保育課長","answer":"こちら、現行のシステムのほうで該当者の洗い出しはできますので、速やかな実施ができるように準備は進めているところですので、改めて調査という必要はないと考えております。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"今回新たにというのは、さっき数字を伺いました。それから、それとも、区のほうでシステムを使って対象者に自動的にこの保育料をお知らせする形になるのかを説明するよう求めました。","respondent":"竹田保育課長","answer":"それらを含めまして、約４００万程度、制度改正による予算が必要となるというふうに考えております。それから、手続等は必要かというご質問ですけれども、こちらのほうで通知を差し上げますので、手続きは必要ないと考えております。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"それぞれありがとうございました。その次の質問で伺おうと思っていたのですが、金額の変更を行うということなのか、説明を求めました。","respondent":"竹田保育課長","answer":"認証保育所の助成につきましては要綱で定めておりますので、今回、条例改正が決まりました後に速やかに要綱のほうも改正いたしまして、認証に通われるお子さんも同じ恩恵を受けられるように速やかに手続を進める予定です。","id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"そこまで配慮していただいて、大変ありがたいです。要綱の適用日は４月１日からということでいいかどうかという、その点、確認したいと求めました。","respondent":"竹田保育課長","answer":"手続上の問題ですが、すみません、詳細は把握していないのですが、できるだけ保護者の方にご負担にならないような形を考えております。それから、もう一点のご質問ですが、適用日は、同じ４月１日を考えております。","id":"exchange-016"},{"speaker":"あべ委員","kind":"意見","question":"認証に入られている方の多くは、認可に入れなかった方が多いということを考えると、やはり認証の方も漏れがないように、この制度改正の恩恵に匹敵するものを受けられるようにということで、ご配慮ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを１点教えていただきのと、さっきざっくり教えていただいたのですが、もうちょっと詳しく教えていただきたいのが。できましたら詳しく教えていただきたいと思っているのですが、その辺、どれくらいの金額なのかも教えてほしいと求めました。","respondent":"竹田保育課長","answer":"人数ですが、別表３は半額になる児童の区分ですが、４月に小学３年生までに拡大したところで、半額になる児童数は約１,０００人ほど増えております。それから、別表４のところが……。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今はわからないということで、別表４と５のところの内訳は後でも結構なので、数字を出してほしいと求めました。別表３のところの予算が、別表３の１,０００人と１５０人のところの予算がどう立てられていたのかだけでも説明を求めました。","respondent":"竹田保育課長","answer":"すみません、今、細かい数字は持ち合わせていないのですけれども、それぞれ人数増を、先ほど申し上げましたとおり、第２子が１,０００人、それから、第３子の対象者が１５０人程度増えることを想定しておりましたので、そちらに合わせた予算組みをしています。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に財政がどうなったのかというところも知りたいので、この部分に関しては今年度、平成２８年度の予算が立っているはずですよね。そこの数字は後でも結構ですので、教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今後に関して、年収３６０万円以上の世帯に対しても、多子軽減の年齢撤廃を求めていきたいと思いますので、よろしくお願いします。本案に対しては賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-03","title":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"１つは、過去の宮古市復興支援の取り組みのこれまでの成果はどのようにお考えなのでしょうか。それから、４点目は、現地での対応は主にどなたがされているのか尋ねました。","respondent":"高山子ども育成課長","answer":"過去３年間、こういった同種の事業を実施してきた成果としましては、さまざまな復興支援にかかわります事業。現地の対応につきましては、よりつながりのある、現地の実情を知り得る大変有意義なプログラムだというふうに聞いております。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"非常に意義ある成果が得られた活動だと思うのですが、これは今回なぜ補正で計上されているのか尋ねました。","respondent":"高山子ども育成課長","answer":"何とかこういった事業を同種同規模で実施する方法について、この間、当初の予算に残念ながらのせることはできませんでした。庁内的な検討も進みまして、同種同規模の事業をご提案できる状況まで協議が整いましたので、今回の６月補正にのせさせていただいたところです。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今後の取り組みの経験というか、そのための布石にするというようなことも必要なのではないかと思うのですが、それに関してはどのようにお考えか尋ねました。","respondent":"高山子ども育成課長、齋藤子ども未来部長","answer":"現地とのつながりが確認できるかといった部分を含めまして、職員が現地に赴くということを考えているところです。それによって、事業の成果、評価などもしていければというふうに考えております。 今回、宮古市の市長さんともお会いして、義援金をお渡しすることになっておりますので、私が代表として行きますので、事業の成果についてはまた来年継続できるような形でできればと考えています。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"意見","question":"すばらしい事業なので、ぜひ今後も予算化して積極的な取り組みをお願いしたいと思うのですが、齋藤部長からも後で十分報告を聞かせていただけることを楽しみにしておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"それから、その仕切り分けといったらいいのですか、考え方についてもお伺いしたいと思います。１０組２０人ということですと、応募者多数の場合は抽選とか選考とか、そういうことになるのか尋ねました。","respondent":"高山子ども育成課長","answer":"そういった同種同規模の事業が実施されていたのですが、今回、そういった意味での仕切り直しはさせていただいたというものです。この内容で実施させていただきたいということではあるのですが、その点、ご了解いただければと思います。","id":"exchange-026"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、区の委託事業ということで、委託先はＰＴＡなのですか。それとも、「つなこし」になるのか尋ねました。","respondent":"高山子ども育成課長","answer":"委託先につきましては、「つなこし」という品川区の小学校ＰＴＡ連合会から派生した非営利団体ということで、そちらのほうと委託契約を考えております。","id":"exchange-027"},{"speaker":"のだて委員","kind":"確認","question":"３点目が、親子で１０組２０名ということなのですが、友達の保護者に頼んで連れていってもらうというようなことというのはできないのでしょうか。伺います。","respondent":"高山子ども育成課長","answer":"こちらのほうの事業実施にあたりましては、「つなこし」のメンバー７人が東京から赴きまして、現地でのそういった活動全般にかかわっていただくです。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"３年間やってきたということなのですが、この間の参加人数とか、あと、感想文とかそういったまとめというのはあるのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"それから、平成２７年度は７０名弱ということで伺っております。自分たちが防災を考えるなら現地に行って、今後も事業を実施するにあたっては、このように考えております。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"過去３年間が、３０名、５０名、７０名と参加人数がどんどん増えていって、今回、１０組２０名ということで減ってしまうわけなのですけれども、区がやる最初の年ということで２０名になっているのかもしれませんが、今後、拡大していく予定はあるのか尋ねました。","respondent":"高山子ども育成課長","answer":"今年度実施してみて、あるいは現地での対応、適正な規模については今後検討してまいります。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"現在の八潮南保育園は１０２名だと思うのですけれども、それが維持されるのか、伺いたいと思います。幼稚園の４歳、５歳部分も含めてあるのか、こういうことを教えてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"３点目なのですが、並列型か年齢区分型かというところなのですが、現時点では並列型を予定しています。保育園に関しては０歳から５歳児まで、幼稚園に関しては４歳、５歳の幼児というところで考えております。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"幼保一体施設をこれから何園つくっていくとか、この位置づけとか、体系的な計画というのはあるのでしょうか。３点目が、八潮南保育園の敷地はどういうふうにしていくのか、教えてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"１点目、遊戯室をどうするのかという問題も出てきますので、設計の中できちんとどういう形で持っていくかというのを考えていく予定です。平成２８年２月の文教委員会でもお話ししていますが、他の地区の保育園等の整備の状況等でまた検討する、そういう考えです。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"保育園の基本設計はまだということで、それは申しわけありませんでした。一緒に実施設計をやっていくということで、しかし、やはり考え方としては、同じ規模を維持していきたいということなのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"設計の中で検討するのですが、その時点の近隣地区の保育園の整備状況、定員等も考えて決めたいと考えています。今は白紙状態です。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"時間的に難しいというのはあるのでしょうが、大会後に配るということはなぜなのか、伺いたいと思います。先ほど少しご説明がありましたけれども、どうして補正に入ることになったのか、もう少し詳しく伺いたいと思います。","respondent":"熊谷指導課長","answer":"１点目の、これは補正ではないのですけれども、そのことをお答えしたほうがよろしいでしょうか。補正は、各学校に都から委託ということで、各学校３０万ずつつくものなのですが……。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"八潮についてとマイスクールについてと、それぞれ伺いたいと思います。それと、やはり平成２９年度から工事が始まるということは、どういった形で周知をしていくのかということを説明するよう求めました。","respondent":"佐藤保育施設調整担当課長","answer":"１クラスずつしかありませんので、２年間かけて順繰りに、居ながら工事を行う予定です。文教委員会で別途説明をさせていただいた後、あと、入園申請者のほうにも周知を図ってまいる予定です。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"それから、これは実施設計は１,９００万円となっていますが、工事費用はかなり何億という数字になってくるのでしょうか。ごめんなさい、質問がうまくまとまらないのですけれども、この工事と民営化の議論とのかかわり合いというのを少し説明していただけますか。","respondent":"佐藤保育施設調整担当課長","answer":"３点目、工事の財源なのですけれども、これは公立の施設になりますので、基本的に一般財源になります。民営化の関係は、明日もその辺については、ご報告いたします。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"ありがとうございました。五反田マイスクールの事業内容が何か変わる部分があるのか、コーディネーターが入ることによる効果というのを教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"学校と家庭と、そして、コーディネーターの仕事として少し増やしていければというふうに考えています。やはり家庭との連携をどう図れるかというところで、また、より手厚くできればと考えているところです。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"コーディネーターには例えば、元教員とか、学校現場にいらした方、あるいは心理系の方、どういった方を想定されているのか、あるいはどのように募集、選考をするのかということを説明するよう求めました。","respondent":"村尾教育総合支援センター長","answer":"現在、コーディネーターには、マイスクール八潮の指導員に入っていただいて、やはりキャリアを持っていますので、かかわり方等、とても経験則を持っていますので、そこを充てて進めていこうというふうに考えているところです。","id":"exchange-038"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮地区の幼保一体の整備について、もう少し具体的にお伺いします。４歳と５歳で１部屋ずつ使われているということでしたが、具体的な人数をお伺いしたいのと、そこら辺の周知の仕方を教えてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"定員は基本的に変える予定はございません。２点目の八潮わかば幼稚園が入っている住宅等の住民への説明なのですが、全部で３回ほど予定しておりまして、丁寧に細かく説明をして。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"もう一点、勝島の地域が今、マンションが建っていることもあって、かなり住民が増えております。勝島地域、八潮の子どもの動向の方向性というのをどう捉えているのか、お聞かせほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"２０年前と５年前を比較すると、乳幼児人口に関しては減少傾向にあるというところは、把握しているところです。大体５割から６割程度が八潮地区の方で、４割から５割は他の地区の方というところもありますので、一定考えていくことになると思います。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問・要望","question":"子どもの数が減っていくという動向を読んでいらっしゃるということなのですが、勝島からのこの幼稚園への入園者というのをどう思われているのか。八潮に来るのは不便なので、大井町のほうに通われるというふうに読まれているのか、そこら辺を確認させてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"八潮わかば幼稚園に関しては、橋から八潮に入ってすぐ近くのところにありますので、一定、八潮地区以外の方の通園というのも今後もあるのかというふうに考えているところです。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ成功させていただきたいのですが、１つだけ、ぜひその点についてどのような見通しがあるのかということをお伺いしたいと思います。八潮のほうは、幼保一体施設は区内６つ目ですが、やはりそこの方向にはつくっていかないという認識で進めているのでしょうかというところの確認です。","respondent":"高山子ども育成課長、村尾教育総合支援センター長、佐藤保育施設調整担当課長","answer":"では、私のほうから、宮古市復興支援の事業の継続性の見通しという点についてお答えします。活動状況なども勘案しながら… 平成２８年度当初予算には計上していなかったために、了解をいただいて、また国のほうの予算で払うというような流れになっております。幼保一体施設と認定こども園の今後の展開ということだと思うのですが、私立の認定こども園については今後も支援を進めてまいります。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"マイスクールのほうはわかりました。別の機会に認定こども園について質問させてほしいと求めましたが、どのようにしていくという研究を進めていければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ計画をきちんと示してほしいし、その点が１点と、なぜ急に幼保一体なのか。こっちが急遽先に浮上していることで、納得がいかないという声がいっぱい出ているのですが、この辺はいかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"教育支援センター等の設置促進の中のコーディネーターの配置というのは、国のほうもやはりいろいろ今考えているということで、本区の不登校対策の充実を図っていこうというふうに考えているところです。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"ここ、大きな計画とかなしに、こうやってなし崩し的に進めていくというところの問題点は感じていないのでしょうか。お伺いします。","respondent":"佐藤保育施設調整担当課長","answer":"仮設場所がなかなか計画的に決まらないところがありますので、計画というのをつくるのはなかなか難しいというところが実情としてあります。幼保施設の検証に関しては、今、課内でも行っているところですので、その辺を含めて、今後またご報告できればと考えています。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"意見","question":"幾つかあるのですが、今の八潮の幼保一体のところで、反対をいたします。新しく品川区の方針である民営化の流れの中で出てきている基本設計ということで、この部分は納得できないので、反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ここで２点、民設民営の賃金は低いとは言えないという前回の答弁に対してお伺いしたのですけれども、賃金に遜色がないと。４年間で８人の尊い命が失われたと質問の中でしているわけですけれども、その辺の大もとのところが見えなかったので、お伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"区としてどう受けとめ、どんな対応をするのか、したのか。運営費や開設準備補助金などの再精査といったらいいのでしょうか、明日の事項にも載っていないので、それをするかどうかは正副にお任せいたします。","respondent":"竹田保育課長","answer":"区の仕様に従った契約の履行をしっかり求め、お子さんを安心してお預けいただけるよう、保育の質の担保に全力を尽くしてまいります。なお、今後も区は立ち入り検査を定期的に行うなど、不適切な支出がないよう、指導、検査を強めていく考えです。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":32345,"voices":154}},{"id":"h28-20160627-5","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"総務委員会","time":"午前１０時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"では、(1)の第５４号議案からの審査ではありますが、会議の運営上、順番を入れ替え、審査を行います。 まず、(6)第６６号議案…","agenda":"では、(1)の第５４号議案からの審査ではありますが、会議の運営上、順番を入れ替え、審査を行います。 まず、(6)第６６号議案…","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"先ほど視察のときに、だれでもトイレとかができるというふうに言われたのですけれども、どの辺に、どれぐらいの、一つですか。だれでもトイレのことを教えていただけますか。","respondent":"溝口公園課長","answer":"この中に組み込む形でだれでもトイレを設置する形になっております。トイレ自体はだれでもトイレが一つと、男女が分かれた形でのトイレをつくるという計画をしているものです。","id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"私はいつもこの委員会で同じことを発言させていただいているのですけれども、だれでもトイレの中に最近はベビー用のおむつ交換台は当然設置されているのですけれども、ちょっと大きい成人用といいますか、そういうものは設置されているのかどうか確認したいと思います。","respondent":"溝口公園課長","answer":"基本的にだれでもトイレは誰でも使えるという形を考えておりまして、広さにもよりますけれども、なるべく設置していく方向になっております。今回、区民公園の管理棟につくるのは、おむつ替えのスペースまでを計画しているものです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、この契約金額で確定してしまうと、大人用までは難しいということでしょうか。本庁舎の３階にありますけれども、もちろんベビー用にも使えるわけですし、そういうことが可能かどうか伺いたいと思います。","respondent":"溝口公園課長","answer":"そういったものに対応できるような形、当然だれでもトイレですから、その中での着替えやおむつ替えというのは可能だというふうに考えております。この管理事務所につきましては、管理人が常駐しますので、そういったところで対応していけるというふうに考えてあります。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば公園とかそういう施設は子どもたち用の施設を障害のある方も当然使うようなことは想定していただきたいなというふうに思います。今日、契約金額を決めてしまって、その中で無理ということであれば、それにかわるような、代替のことを検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"こういう建物でも、やはり杭工事というのはするのでしょうか。地盤の高さというのはそういうものにも対応するようにできているように今回建てるのですか、それとも、ちょっとその辺を説明するよう求めました。","respondent":"小林施設整備課長、溝口公園課長","answer":"今回は２階建てなので、地質の調査をしてメーターを決めて、杭のほうの事業というのはあるものと私も認識はしております。資料を今日持っていないので、多分建築基準法にのっとって建物を建設しますので… そういった中での今回の建築を受けてやっていくものです。いざ災害時には、また災害時にも十分対応できるような管理棟をつくっていきたいということで、今回契約案件として上げさせていただいているものです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"仮に３階建てでも杭を打ってしっかりやっていると思うので、気をつけてやっていただきたい、慎重にというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"なくしたということについては、そういう点ではわからなくもないけれども、なぜなくしたのかという理由を１点伺いたいと思っているのです。こういうところをやはりどういうふうに見たらいいのかなというのをちょっと改めて伺っておきたいというふうに思います。","respondent":"溝口公園課長、立川経理課長","answer":"は避難できる、広場面積は今回若干増えるような形の計画をしておりますので、そういったところを踏まえての計画をしているものです。そういったものも整備していく検討をしておりますので… 辞退の理由ですが、企業それぞれ理由がありまして、主なものとしましては、配置技術者の不足であるとか、積算金額の乖離、そういったことが主な理由です。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えばＳ造とかいろいろあるわけではないですか。それは行政側から出したのかどうなのかというのをまずお聞きしたい。","respondent":"溝口公園課長","answer":"さまざま検討していく中で、私どものほう行政から提示して、それで今回契約します。費用対効果、そういったものも含めて検討した中で定めて、今回発注させていただいたという形になります。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"確認","question":"ほとんど平屋で一部２階というぐらいだったら、Ｓ造でも軽量鉄骨に近いＳ造みたいなものでも、確認の同程度の許可を取っているところもあるわけです。そういうものを入れ込むと、そういう選択の検討というか、そういうものというのはあったのかなというのだけ聞きたい。","respondent":"小林施設整備課長","answer":"今回設計の中でもそういう検討はいたしました。工期がまた別だとそこら辺の構造的なものは再検討が必要ですけれども、場所も近くだということで、同じ業種で進めるということで今回考えました。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２棟あわせたのだから、逆に言えば。そういうことも含めて監理監督はしっかりやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"第７３号議案、大森駅水神口自転車等駐車場整備工事請負契約の変更","agenda":"第７３号議案、大森駅水神口自転車等駐車場整備工事請負契約の変更","exchanges":[{"speaker":"南委員","kind":"質問","question":"本当にわずか、大体働いている職人の方々の賃金というのは、それに伴ってどのぐらい上がるというふうに見たらいいのでしょうか。わかる範囲でいいのですけれども、それだけ説明を求めました。","respondent":"立川経理課長","answer":"今回の改定では、全国では平均４.９％の改定です。東京都におきましては、全体平均で２.８％の改定額です。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"そうすると、２.８％差額から掛けて幾らぐらいと。いろいろそういうところも自分で賄うという点で、そういう点で質問しておりますので、よろしくお願いしたいと思います。","respondent":"立川経理課長","answer":"その部分について各工種の、いわゆる旧労務単価と新労務単価と比べまして、上がっていればその分を計算します。下がっていればその分を計算し直す、その結果がこの金額になっております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"課長、見解として、こういうのが当たり前のように区としては考えているのでしょうか。ちょっとなじめないので、その辺、ご答弁いただければありがたい。","respondent":"立川経理課長","answer":"今回のいわゆる改定というのは、国のほうから特例措置として実施してくれという要請に基づき実施しているものです。いわゆる公共工事の現場の労働者の賃金というのは、その辺を踏まえまして、平成２５年からこの特例措置というのが実施されているところです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ。ひ孫請けには、何かちょっと不思議な状況だと思うので、一応国にでもそういうふうに伝えていただければありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"この２２５万円というものが出てきていると私は理解だと思っていたのだけれども、思った以上に労務がかかるという場合があるではないですか。だから、どう予定しているなんていうことはもちろんやっていないと思うけれども、そこら辺のからくりをもう一度よく説明を求めました。","respondent":"立川経理課長","answer":"いわゆる現場の実勢価格をもとに予定価格を定めて発注しているということですけれども、国のほうではこの設計労務単価の調査を毎年実施しております。それで、現場のほうと乖離があったということで、今回２.８％の変更があったというものです。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"確認","question":"行政はそうはできないではないですか。確認だけ。","respondent":"立川経理課長","answer":"委員ご指摘のとおりいわゆる契約約款のところに、工事費につきましてはスライド条項というものを設けておりますので、急激な賃金や物価の変動に対しては、いわゆる契約の後に協議ということになっております。","id":"exchange-016"}]},{"id":"topic-03","title":"第７２号議案、勝島橋補修工事請負契約","agenda":"第７２号議案、勝島橋補修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"１点だけ。それだけですとの意見を述べました。","respondent":"立川経理課長","answer":"補修工事等の場合、現状の状態がどうなのかということを写真等で資料にしたいというふうに考えております。","id":"exchange-017"}]},{"id":"topic-04","title":"第６５号議案、総合庁舎熱源改修工事請負契約","agenda":"第６５号議案、総合庁舎熱源改修工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"確認させてください。老朽化に伴うということなのですが、大体どれくらいたったものなのかということと、その辺のことを説明するよう求めました。","respondent":"立川経理課長","answer":"前回いわゆる熱源機器の改修を行ったのは２４年前です。設備につきましては大体２０年前後で改修したほうがいいというふうになっておりますので、今回はそのタイミングということで実施するものです。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ伺ってもいいですか。ボイラー更新とかで地下をいじるわけだから、そのときににおい対策というのかな、工事はできないものなのか尋ねました。","respondent":"小林施設整備課長","answer":"集じんのところがあるのですけれども、そこでちょっとエコのたい肥をつくっているとか、そこら辺のにおいも混ざっているところがあります。","id":"exchange-019"}]},{"id":"topic-05","title":"第７０号議案、品川図書館空調改修工事請負契約","agenda":"第７０号議案、品川図書館空調改修工事請負契約","exchanges":[{"speaker":"南委員","kind":"確認","question":"１点だけ確認なのですけれども、別々だということはちょっとわかるところなのですけれども、改めて六行会の地下にホールがありますよね。空調は全体かなと、ちょっとそういうのもあるので、その点を確認したいのですが。","respondent":"小林施設整備課長","answer":"そのとおりです。今回の図書館エリアにつきましては、２階から４階までです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"それからもう１点、工事は当然この夏は回避をして工事をされるのだろうと思っているのですけれども、その辺の確認。もし、工期が出ていたら私が見落としているので、わからないので教えていただきたい。","respondent":"小林施設整備課長","answer":"資料の２４ページの３番目の工期、平成２９年１月３１日を目標に工事をいたします。それで、今のところは３フロアありますので、一つのフロアごとに改修工事を施工する予定です。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"終了が１月３１日であって、工期の開始というのは夏の暑い時期を避けてやるのだろうと思うのですけれども、開始時期がいつごろからかなというのがちょっと知りたかったので説明を求めました。","respondent":"小林施設整備課長","answer":"失礼いたしました。冷房運転期間につきましては、９月末までは冷房を効かせまして、その後１０月ごろから停止をして、本格的に工事を進める予定です。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"３階、４階のフロアで２億円ということは、その辺はどういうわけでこうなのだという説明だけお聞かせ願えればと思います。","respondent":"小林施設整備課長","answer":"ここの建物の空調関係が通常の電気屋でやっている小さなものではなくて、パッケージユニットというもので、かなり大きいです。１台入れたりとか、フロアで４台ぐらいそれを入れますので、かなり高額になってくるのは確かだと思います。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"もう１点お話ししたと思うのですが、普通のまちの電気屋ということではなくて、品川区内に電気工事店がたくさんありますよね。こういう工事ならば参入できるのではないかと思ったのですが、そこでやはり制限をかけているというのはどういうわけなのか尋ねました。","respondent":"立川経理課長","answer":"いわゆる予定価格の３０％以上あるということ、それから第２グループでは、かなり幅広く参加ができる。その点でつながりを持てるのであれば、委員ご指摘のとおり小さい企業も入ってこられるのかなというふうに考えております。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"すみません。先ほどと同じような趣旨の質問になるのですけれども、先ほどみたいにどれくらいで更新すべきものとして今回の工事なのか、その辺を説明するよう求めました。","respondent":"小林施設整備課長","answer":"私のほうからちょっとご説明いたします。今回のこの部分については、主管課のほうからは早急な対応が必要ということで、こちらに執行委任が来ているです。","id":"exchange-025"}]},{"id":"topic-06","title":"案、芳水小学校第１期校舎改築その他工事請負契約、(8)第６８号議案、芳水小学校第１期校舎改築その他空気調和設備工事請負契約、および(9)第６９号議案…","agenda":"案、芳水小学校第１期校舎改築その他工事請負契約、(8)第６８号議案、芳水小学校第１期校舎改築その他空気調和設備工事請負契約、および(9)第６９号議案…","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そのあたりのことをどういう検討を行ったのか、改めて耐震との関係で教えてほしいと求めました。あの地域の、あの地域の子どもたちの人口予測との関係をどういうふうに捉えているのかというのを改めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"現在の芳水小学校の校舎が５,０００m2弱ということで、トータルで９,９００m2が予定されますので、約倍近くの大きさになるものです。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"人口予測して２４学級まで可能だというところは、それはそれとして説明として伺ったのですが、ちょっと確認をしたいと思いました。９,９００m2ということで、これがこの間の議論の中で、そのあたりのところを教えてほしいと求めました。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"この建物、校舎関係は、９年前と６年前に２期に分かれて耐震補強を行っております。一斉にやるということで教育委員会は答えを出して、年度を分けてやっていったところです。今後一応最大で今のところ予測されているのは１８クラスではあるのですけれども、今後の再開発等の推移を見ていくと、改築を今回設定しています。","id":"exchange-027"},{"speaker":"南委員","kind":"確認","question":"結局今の状況だと人口増に対応できないからリニューアル、全面改築するのだと、そういうことなのですか。トータルでそういうふうに受けとめたのですけれども、それでいいのかどうか、ちょっとそこを確認したいと思います。","respondent":"篠田学校計画担当課長","answer":"この先人口増等への対応を考えますと、総合的に判断した結果、今回全面改築という形で選択したです。","id":"exchange-028"},{"speaker":"南委員","kind":"確認","question":"今の建物では、９年前と６年前に２回にわたって建築基準法上待ったなしという校舎の状況があったので、こういうことでいいということですかね。確認をしたいと思います。","respondent":"篠田学校計画担当課長","answer":"基本的にはそういった認識で総合的に判断をして、こういった選択をさせていただいたです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"先ほどのご説明だと、多目的室、地域利用エリアが今回話題になっている大崎図書館の代替施設ということはわかりました。そもそもスペース的な広さが今の図書館の床面積といいますか、それと比べでどうなのでしょうか、説明を求めました。","respondent":"篠田学校計画担当課長","answer":"申し訳ございません、正確な数字は持ち合わせていないのですが、２,０００m2を超えるような形の床面積をとっております。今回多目的室として学校側のほうに用意されるスペースの広さとしましては、５００m2を予定しています。","id":"exchange-030"}]},{"id":"topic-07","title":"第７４号議案、浜川雨水排水管建設工事その２請負契約の変更","agenda":"第７４号議案、浜川雨水排水管建設工事その２請負契約の変更","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"説明のところに、施工方法の変更に伴いと書いてあるのですけれども、これはちょっとよくわからなかったので、説明をしてほしいと求めました。施工方法がどういうふうに変わったのかというところを教えてほしいと求めました。","respondent":"和田河川下水道課長","answer":"現場で立坑を掘ってみたところ、別の下水道管が支障となりまして、そのドリルを設計どおりに設置できないことがわかったものです。そのことから、このドリルの角度や位置などを変更したものです。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"それは掘り当てて初めてちょっと変更しなくてはいけないということがわかったのか、あるいはどういう形で、どこまでどんなふうにわかったのかということを説明するよう求めました。","respondent":"和田河川下水道課長","answer":"ドリルを道路の上から施工するのではなくて、一旦立坑を掘って、立坑の中からドリルを施工するというものです。ですから、既設の下水道管があるということがわかりましたので、その立坑を掘った時点から変更の事象が発生したです。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"そういう工事の変更というのは、こういう形での変更というのはよくあり得ることなのですか。結局見えないところですから。","respondent":"和田河川下水道課長","answer":"やはり予想しない管が入っていたり、またそこだと思って掘ったものが違うところにあったりとか、なかったりとかということもあります。通常下水道工事のみならず、開削工事を伴う工事にこういう変更はつきものだというふうに申し上げておきます。","id":"exchange-033"}]},{"id":"topic-08","title":"よび費用弁償に関する条例の一部を改正する条例、(2)第５５号議案、品川区監査委員の給与等に関する条例の一部を改正する条例、および(3)第５６号議案…","agenda":"よび費用弁償に関する条例の一部を改正する条例、(2)第５５号議案、品川区監査委員の給与等に関する条例の一部を改正する条例、および(3)第５６号議案…","exchanges":[{"speaker":"南委員","kind":"質問","question":"第５４号議案の中ほどの３に書いてあるように、例えば出勤できない日にちが１日ではなくて、そういうことになるのか尋ねました。","respondent":"久保田総務課長","answer":"そういった勤務実績があれば、その月の報酬は出しますし、その翌月においても勤務の実績があれば報酬は支給をするという規定です。登庁して会議に出ていただくということだけではなくて、その他、職責を果たす勤務実績があればそれに対して報酬を支払うというものです。","id":"exchange-034"},{"speaker":"南委員","kind":"意見","question":"そうすると、１日から末日まで、この期間という規定だということで、たとえ３０日とか３１日休んだとしても、１日から末日までというところに該当しなければ支給はするよと、そういうことになるということでいいのですねとの意見を述べました。","respondent":"久保田総務課長","answer":"そのような規定になってあります。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"わかりました。どういうことなのか、ちょっと概念的にはわかるけれども、どういう状況のときをこういうふうに該当するよというふうになるのかを説明するよう求めました。","respondent":"久保田総務課長","answer":"そういった形で自分の意思を明確にあらわせない、意思を判断できなかったり、表示できないといった場合はこれに該当するです。","id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"その辺の確認というのが、職責を果たせないという確認というのは、どうなのか尋ねました。","respondent":"久保田総務課長","answer":"きちんと自分の意思の判断として、そういった職責を果たせるというものであれば、それは勤務実績として認めるというものです。ですから、そこはきちんとした事務局の職員等が勤務実績として確認ができるというものが勤務実績になるです。","id":"exchange-037"},{"speaker":"南委員","kind":"意見","question":"状況というのは、お医者さんの診断書が一つあるかなと思うのですけれども、そういうところはどうなのかとの意見を述べました。","respondent":"田村総務部長","answer":"それも個々人によって全く対応が違うので、きちんと私たちが説明していることが理解できるのか、そういう形でご理解いただきたい。個別の話は具体的にこちらでやりとりといっても、千差万別のケースがあるので、その都度判断しないと難しいかなと、そのように考えております。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"すごく理解できるところですから、それはそれとして理解できなくないので、こういう規定を設けるというのは理解できるかなと思っているのです。わからないような感じだったので、では今品川区としてはこの規定を設けるに当たっては個別の判断をしていくと、そういうことになるということですね。","respondent":"久保田総務課長","answer":"部長から答弁がありましたように、個々のケースという話になれば、それは当然ながらその方、各委員の方の症状とか判断の能力等を確認して判断していかなければならないというふうに思ってあります。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"１回１回の会議ごとのものにしなかったというのは、要するに会議だけではない職務が具体的に想定されるからということで理解していいのでしょうか。例えば、日常的にそういうものというのはどれぐらい発生するものなのか、わかる範囲で教えてほしいと求めました。","respondent":"久保田総務課長","answer":"ただ、そういったそれぞれに属する行政委員の分野について精通するためのいろいろな職務を、知識を吸収するような活動もされてあります。学校の周年行事等にもご参加いただいてありますので、原則としては、我々の基本は会議の出席が一番わかりやすい形かなと思ってあります。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"教育委員会と選挙管理委員会は第５４号議案で、教育委員会と選挙管理委員会はちょっと性格が違うのではないかなというふうに思うのです。例えば、片方はたしか出会手当のような形で考えていると思うのですが、何かそういうふうに考えられない理由があれば説明を求めました。","respondent":"久保田総務課長","answer":"それが平成３年のときに、これは地方自治法、そのまま行政委員の中に選挙管理委員と教育委員をそれぞれ入れた形で今日まで来ているということです。あくまでも報酬と費用弁償にかかわる部分の規定ということで、教育委員と選挙管理委員は１本でやっているというものです。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"さっきちょっとお聞きしたつもりだったのですけれども、会議を基本に考えるということは伺いましたが、職務があれば説明を求めました。","respondent":"工藤選挙管理委員会事務局長","answer":"こういったところでの表彰式を行いましたり、審査委員として職責を果たしていただいているというところがあります。２３区で特選連という会議体をつくっておりまして、協議会に出ていただきましたり、さまざまな活動をしています。","id":"exchange-042"}]},{"id":"topic-09","title":"第６４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","agenda":"第６４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"そういう意味ではわかるのですけれども、その上の一般運送契約というのがちょっとよくわからなくて、こちらを読んでもちょっとわからない。申し訳ないのですけれども、説明を求めました。","respondent":"工藤選挙管理委員会事務局長","answer":"人を運送する事業者との契約ということになりますので、いわゆるその他の契約のレンタカーとガソリンと運転手の雇用、これらを合算したようなイメージの契約ということになります。","id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"そうするとカメラマンの費用というのですか、どういう名目なのかよくわからない、カメラマンの費用も入るということでいいですか。これだけの金額になるのだというところは納得したのですけれども、そういうことも含むというデザイン料という意味で、いいですね。","respondent":"工藤選挙管理委員会事務局長","answer":"企画費の件です。先ほどご説明いたしましたように、デザイン料等ですので、そのようなカメラマン等を使っていると、かかる経費等もこちらのほうに含まれるです。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっとお伺いしたいのですが、まず分かれているのかどうかというのをお聞きしたいのと、例えば品川区だけではなくて。それ以外の部分で、項目が我々で言えば増やしてほしい項目があったりするときに、そこら辺の仕組みというものを教えてほしい。","respondent":"工藤選挙管理委員会事務局長","answer":"いわゆる２３区、東京と地方ですけれども、私のほうが情報をとった限りですと、２３区、東京都内はほぼ共通で同じような形で条例を定めているです。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうことというのは、地方自治体からいえるのか、条例で定めないのなら品川区だけやってもいいというわけにはいかないわけではないですか。ここら辺の仕組みをもうちょっと具体的にわかるように説明してほしい。","respondent":"工藤選挙管理委員会事務局長","answer":"どなたでも立候補の機会があると、金額につきましては、この限度額をもってという形で国のほうで基準額を定めているところです。そういった中でこのような公費負担のあり方につきましては、要望事項の中で議論されるものだというふうに思っているものです。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"意見","question":"車を使う方の９割ぐらいの方は多分ウグイスさんがいて、そのうちの８割かそれぐらいの方は多分費用を払ったり、出やすくなるわけ。この議論をするときには、何かおかしいなといつも思っているということだけ言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"もう１回確認したいのですけれども、そこのところは今の話でわかるのだけれども、実際にかかるものと公費負担とはやはり現実的に乖離があるわけです。わかりますか、この質問。","respondent":"工藤選挙管理委員会事務局長","answer":"消費税が５％から３％上がったというところで、そういった絡みの中で額が増えたですので、いわゆる人件費分は上がっていないわけです。そういった意味では、値上がりした額という部分も、これも計算しますと３％前後だですので、私どももそのように捉えているところです。","id":"exchange-048"}]},{"id":"topic-10","title":"平成２８年請願第５号、「社会資本整備総合交付金」の活用など、八潮６９号棟が公的住宅として存続できるよう品川区に施策を求める請願","agenda":"平成２８年請願第５号、「社会資本整備総合交付金」の活用など、八潮６９号棟が公的住宅として存続できるよう品川区に施策を求める請願","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういうことが可能なのかどうか、その内容についてちょっとお知らせをいただきたいと、お願いします。","respondent":"柏原企画調整課長","answer":"簡単に言いますと、以前幾つか分かれていた交付金が平成２２年から統括といいますか、比較的使いやすい交付金にということでまとめられた交付金です。","id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことでトータルにすると品川区はほかの部分も含めて数十億円という規模の交付金が活用されているというふうな状況になっていると思うのです。そういうところで、区のほうにもいろいろな要望をお届けしていると思うのですけれども、そこのところの認識をまずお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"ご質問の部分は、雇用促進住宅の建物が売却という形になったときに、区の考え方というところでよろしいでしょうか。まずは国のほうが基本的なところを考えながら経営に当たる、まず基本的なスタンスといったところでは、そこがまず区としては基本だと考えております。","id":"exchange-050"},{"speaker":"南委員","kind":"意見","question":"どうしようというふうに不安な状況に置かれて、そういう問題について区はどういうふうに認識しているかということを聞いたつもりなので、そこもお願いしますとの意見を述べました。","respondent":"柏原企画調整課長","answer":"一定程度の住宅、先１０年間とかという話も出ている中ですので、区として何ができるのかというのはお話をさせていただいているところです。できること、何ができるかというのを含めて考えていきたい、そういったところです。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"そういう方々も含めて今回は平成３３年に廃止だから、そこまでに出ていってください。１０年間は保証するけれども、やはり廃止は撤回しろという品川区の意思表明をするのと同時に、そういう点についての見解を伺っておきたいと思います。","respondent":"柏原企画調整課長","answer":"区として何ができるのか、どういった形でサポートといいますか、お話を聞いたり何ができるのかというところを我々としても考えているものです。そういった行動をとりながら、区として何ができるのかというのをこれからも考えていくという姿勢でいるものです。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"そこを信頼していっていいのかどうか、そういう考え方で区は見ているのかというところもちょっと伺いたいと思っているのです。やはり居住者にとっては非常に大きなさらなる不安になってくるわけで、区はどういうふうに考えているのか、そこも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"そういったいったところを、例えば機構であったり、お住まいの方々に説明するといったところで対応させていただいているです。１０年間は転売しない、それから賃貸契約の条件も１０年間は変えない、動いていくものなのだろうというふうには想像しています。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"そういうふうにするには、区なりが購入をするという方向がもし確認されたときには、こういう資金を活用してほしいという趣旨だと思うのですよね。やはり先ほどのような答弁に終わってしまうのですかね、もう１回その辺についてしっかり伺っておきたいと思っているのですけれども。","respondent":"柏原企画調整課長","answer":"一般の形で言いますと、通常であれば３年から５年ぐらいの大きな計画を持った形で国に申請するというのがこの交付金の性格であります。ですので、現段階で何か議論というよりは、この入札の動きというのを注視するのができることかと思います。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"１０年間は継続するということが挙げられていて、もしその契約が守られない場合にはどうするというようなことが入っているのか、その辺についてはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"１０年間はそういった形での転売はできない、その条件ということで入札が行われ、事業者は手を挙げてくると思います。ですから、それ以上のことは想像の話になってしまいますので、こういうことは、ちょっとお答えは難しいかなというふうに思ってあります。","id":"exchange-055"},{"speaker":"須貝委員","kind":"質問・要望","question":"これは契約以前に約束ですから、これがちゃんとホームページ等に載っていれば、私はそれが一つの大きな契約条件に基本的になると思います。品川区は今後もやはり機構に対しては住民に誠意ある対応を私は今までどおり要望してほしいということと、そしてこの住宅に住まわれる方々に対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですが、例えばこれが請願項目１の最後のほうに「公的住宅として」と書かれているのですが、ぱっと入れるようなものなのか尋ねました。","respondent":"柏原企画調整課長","answer":"ここには所得の制限があったり、もろもろ入居のためのいろいろな要件、条件があります。この場ではなかなかお答えが難しいのですけれども、ちょっとお答えが難しいですけれども、かなり厳しい要件があるのは事実です。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"もちろん機構が今は当事者なわけですから、でも今現に公的な役割というか、結局は区に対してそれぞれ相談がいくようになるわけですよね。さっきの南委員のご質問にも重なるかと思うのですけれども、その辺についてはどのように考えていらっしゃるのか。","respondent":"柏原企画調整課長","answer":"その対応が不十分だというふうに我々も思っております。今後この話が例えば１０年という期限は一応ありますけれども、どう対応するか、個別の対応をしながらということになってこようかと思います。","id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"確認","question":"そこら辺の確認をしたいのと、常にそこは乗りますよというスタンスでいくというのは、変わりないのだよねということ。これを平成３３年まで見通しといったら、私は１回の入札でもしだめだとしても、どういう流れになるのかなという一般論を説明するよう求めました。","respondent":"柏原企画調整課長","answer":"ということで、国の動きの考えを示して国が決定して、国のやり方で、こういった形で住宅の、今入札になっていますけれども、動きが出た。ただ、もう一度なり何なりで、別のやり方で同じようなことをやる可能性は検討していますというふうに事務レベルでは聞いてあります。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"この請願項目の場合、こちらも何か可能性の請願項目というのはどうなのかなというふうにちょっと私も思ったりして、不調になるかどうかということも。不採択というふうに決めてしまうのがどうなのかなというのもあって、継続という可能性はないのか伺いたいと思いますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"南委員","kind":"質問","question":"ちょっと私が質問したいと思って、今吉田委員のご意見もなるほどなというふうに思ってお伺いしました。ですから、そういう判断になったときにも、財政的な影響はそんなにない。","respondent":"柏原企画調整課長","answer":"１,２００件ぐらいまだ雇用促進住宅はありますので、先ほど資料でご説明しましたように、築３２年です。それから、管理でも使っているところがありますが、未来永劫その交付金が管理費で使えるというものではないというふうに認識しております。","id":"exchange-061"},{"speaker":"南委員","kind":"質問・要望","question":"例えば延長を政府に求めろとかというふうに出ているけれども、そういう意思があるのかどうか、今まで一度足りともしてきたのか。言ってきたのですか、ちょっとそこを確認したいのが一つです。","respondent":"柏原企画調整課長","answer":"国に対しての意見というところであろうと思いますけれども、これも先ほど他の委員ともご議論させていただいたところですけれども、国が目的を持った住宅に対して判断をしたということに対して区がそれに対して何か物を申すべき立場ではないです。","id":"exchange-062"},{"speaker":"南委員","kind":"質問","question":"品川区民の生活そのものがかかっている問題ですから、やはり言うべきことは言う、姿勢を見せるぐらいのことがあってもいいと思うのですよ。その点は言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"つる副委員長","kind":"質問・要望","question":"請願の内容を確認させていただきましたが、そもそも論でもしわかれば教えていただきたいのですが、交渉とかそうした部分もあると思うのです。何か自治会としてそうした交渉事とか、やったことがあるのかどうかとか、わかる範囲で教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"６９号棟の自治会組織がございまして、その自治会の方とも何度か代表の方とお会いさせていただいてあります。そういったところで、話し合いをきちんとしてほしいという旨のお話はされているというところまでは聞いてあります。","id":"exchange-064"},{"speaker":"つる副委員長","kind":"質問","question":"今話し合いということでありましたけれども、何か詳細なこととかというのは、特に自治会のほうからはお聞きしていないのか尋ねました。","respondent":"柏原企画調整課長","answer":"そういったことを住んでいる方に対して機構のほうからきちんと説明をしてください、そういう場を持ってくださいというような申し出をされたです。","id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"いろいろ今お話を伺いましたけれども、今入札も行われているということであります。そういうことも考えるのであれば、私はこの請願については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"つる副委員長","kind":"質問・要望","question":"各委員の皆さんの質疑を確認させていただいて、機構に説明を求めるとか、ちょっとずれがあるのかなという部分もあります。そうした部分では、しっかりと自治会の皆様の趣旨、立ち位置をしっかりと尊重しなければいけないという部分も含めてです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、今回は継続でいきたいというふうに思っています。したがって、採択を主張したかったのですけれども、継続で諮っていただきたい、継続を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"大倉委員","kind":"質問・要望","question":"６９号棟の方々が今厚生労働省と話し合いを求めていたり、１０年間を求めているというところで、そういうことなのかなと感じているところであります。すぐにそこにいる方たちが入れるという形になるかどうかわからないというところでも、ちょっと願意に沿い難いというところで不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"まして、どうやって追い出すのかなというと、あまり住民の方に不安をあおるというのはいかがなものかなというふうに思います。皆さんを守る法律もありますから、その辺はやはり住民の方もよく調べて対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"南委員","kind":"意見","question":"採択か不採択かと言わないと。」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2048#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64003,"voices":339}},{"id":"h28-20160628-6","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"区民委員会","time":"午前１０時００分～午前１１時２０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"──────────────────────────────────────────── (2) 区民斎場なぎさ会館仮設駐車場の一時移設について 次に…","agenda":"──────────────────────────────────────────── (2) 区民斎場なぎさ会館仮設駐車場の一時移設について 次に…","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"人道橋を渡って歩行者通路を通ってこの会館に入っていくのですけれども、これは裏口になるのですか。それはまた現地で移動とかさせるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"あくまでも安全面を最重要視しておりますので、それでご負担をかけるのですけれども、ご協力をお願いしたいと思っているのです。３０ｍぐらいになるのですけれども、それについてご理解、ご協力をお願いしたいところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問","question":"この館内と法面というのかな、どうなっているのかわからないのですけれども、ここの間というのは安全性の確保はできないのですか。イメージがわかないのです、この図。","respondent":"提坂戸籍住民課長","answer":"参列の方というのは２階のほうに移動していただく形になるので、さほど問題にはならないと思うのですが。〔「正面から入れるの」と呼ぶ者あり〕 正面を閉鎖しているところではあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"その案内というのですか、ドライバーさんだけはぐるっとという感じになると思うのですけれども、その案内がどうかというところ。そうすると、夜に暗くなってくると車のすれ違いがどうなのかなと思うのですけれども、その対策がどうなっているのかもご説明ほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"車両の通行帯の幅員は７.５ｍありますので、一般車両はすれ違えるようにはなっております。こちらについてもガードマンが常時おりますので、問題ないと思います。","id":"exchange-003"},{"speaker":"伊藤副委員長","kind":"質問","question":"ですから、１つのアイデアですけれども、脇を通って正面から入れるルートが確保できるわけです。そういうことはご検討されなかったのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"今、なぎさ会館の建物の裏側に駐輪場があるかと思うのですけれども、それを若干左のほうに移設をする予定です。それで、通行の妨げにならないように配慮いたしまして、それで正面玄関から入っていただくことは十分可能です。","id":"exchange-004"},{"speaker":"伊藤副委員長","kind":"質問","question":"人道橋を渡って、車からおりた方が、もし自転車の駐輪場を移設できれば、脇を通って正面から入ることはできますよね。そういうことを検討されなかったのですかということをお聞きしたい。","respondent":"提坂戸籍住民課長","answer":"河川下水道課のほうでもいろいろ検討は重ねているとは思うのですが、スペースの関係で裏に駐輪場をつくるしかないということで検討に至ったと思います。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"確認ですけれども、通常は１人だったかなと思うのですが、箇所に必要かなと。どのようにガードマンの配置はお考えか尋ねました。","respondent":"提坂戸籍住民課長","answer":"ガードマンについては６名配置する予定です。時間的には、お通夜がある日については８時半から夜の１０時まで、お通夜とかない場合は朝８時半から５時まで配置する予定です。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"十分に配置をくださるということで、葬儀のあるときはわかるのですが、ないときもこの人数という形になるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"日中については車の出入りがあることを想定しております。基本的には６名配置すると聞いてあります。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"通常はこの会館を使われる方のみ、この駐車場を使われるわけですね。ということは、葬儀がないのに出入りがあるというのはどういうあれか尋ねました。","respondent":"提坂戸籍住民課長","answer":"基本的に葬儀社とか、その辺の出入りとかもあるようには聞いておりますけれども、万全の体制を組むようにとは聞いてあります。","id":"exchange-008"}]},{"id":"topic-02","title":"────────────────────────────────────── (3) 品川区観光振興協議会および品川区観光フォーラムについて 次に…","agenda":"────────────────────────────────────── (3) 品川区観光振興協議会および品川区観光フォーラムについて 次に…","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"もう一回教えていただきたいのですけれども、位置づけというのですか、品川区は都市部なので都市型観光を推進していかなければいけない。１つにまとめて、そういうことも必要になってくるといったときに、そういうのはどこでやるのですかというところを説明するよう求めました。","respondent":"鈴木文化観光課長","answer":"それと、先ほど、各観光事業者や関係団体の調整もしながわ観光協会が基本的には担っていただく予定です。各事業者やＮＰＯ、それぞれ組織の特性や事業の展開の中で、観光に携わる具体的な事業を担っていただくというような位置関係で考えているものです。","id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひ、来年の３月末が一つの年度区切りで、それは延々と続くものの中に新たなものをどんどん入れている部分というのがあるわけではないですか。その多様性というのですか、いろいろ案は出てくると思うのですけれども、そういう流れでいいのか尋ねました。","respondent":"鈴木文化観光課長","answer":"継続かですが、こちらの観光振興協議会は区の要綱を設置しまして設立した正式な協議会ですので、必要性がある限り継続です。区の観光ということで継続して取り組んでまいりますので、新たな事業、そういうことも継続してしっかりと続けていくという予定で進めてまいります。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、７月の金曜日のこの時間帯に、どういう方が来てくれるのでしょうか。その辺についてお伺いしたいのと、オリンピック・パラリンピック準備課長にお伺いしたいのですけれども、観光フォーラムについても。","respondent":"鈴木文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"１点目の東京オリンピック・パラリンピックが来る、この観光振興協議会を設置したかですが、そのことは踏まえております。２点目の観光フォーラムですが… 私、こちらの資料の４番のスケジュールにあります都市型観光プラン推進本部の中の事務局ということで、私が参加させていただいているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"特に安全という意味で都市型観光というのは、この観光振興協議会には、生活安全担当課長は観光振興協議会の中に入っているのでしょうか。警視庁とつないでいただきたいという思いがあるのですけれども、その辺においては、安全・安心という意味で、その辺についてはいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"観光で訪れていただくためには品川のまち自体が安全で安心できるというまちでなければならないというのは、区としても認識をしています。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここが中枢だというお話がありましたけれども、区の要綱でつくるということなので、民間の団体というよりも会議体ということになるのでしょうか。組織図というのですか、どういうメンバーなのか、少し補足をしてほしいと求めました。","respondent":"鈴木文化観光課長","answer":"プランで対象としている１０年間に関する観光の区の特徴ですが、これまでのアクションプランのほうでも観光施策、観光振興に取り組んでまいりました。この後、実際に設置します部会のほうでは実務レベルの方にお集まりいただいて、検討するという組織構成になっているものです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"観光プランで人を呼び込むこと、見せることとかはすごく大事だとは思うのですけれども、先ほども安全面の話が出たのですけれども、有害図書とか、そういうことの話し合いというのはこういう観光協会の中でも話されたりするのか尋ねました。","respondent":"鈴木文化観光課長","answer":"安全面とか、対応が必要なものはテーマとして上がってくると思いますので、大きな観光の視点での方向性はこの観光振興協議会や部会で検討いたします。先ほど申し上げました都市型観光プラン推進本部で所管する部に伝えまして連携をするということで考えております。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"確認","question":"何点か確認したいのですけれども、それで、観光振興協議会の中にマスコミ関係の方をなぜ入れなかったのかなという思いが一つあるのです。福井県坂井市にこの間お伺いした際に、たしかソニーだったか、忘れましたけれども。","respondent":"鈴木文化観光課長","answer":"１点目のマスコミ関係が観光振興協議会のメンバーに入っていないですが、直接マスコミということでは今回お声かけをしておりません。","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"みきゃんとか、それからくまモン、全て地域の観光の方々が苦労して展開されてきたわけではないですか。ここからそういうすばらしいヒット作をつくっていただきたいなという切なる願いがあるので、そういうところの方を招聘するなり、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"実は区としてもその辺は一応考えているところでございまして、協議会の運営、そちらのほうでも協力をいただいております。編集者の方、さまざまな品川区の魅力を発信する情報発信についても検討しながら進めていきたいというところで、準備をしています。","id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"それは入っていただきたいのだけれども、品川区はこういうことをやっていくということを宣伝することも観光の一環ですから、ぜひ検討を求めました。","respondent":"鈴木文化観光課長","answer":"マスコミへの情報提供を使ってのＰＲ、ご指摘のとおりです。そして秋の観光フェアも、区の広報と連携をして取材等の対応でのマスコミへの情報発信もしっかりと続けていきたいと考えております。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"入って、もっと創造力を膨らませて、コンビニを入れたっていいわけですよ。１足す１が３になるという観光でないと多分、その辺は本当に幅を広げて取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"次回以降でもそれぞれの問題意識を出し合うことから議論を進めたらいいのかなと思うので、今日は示されただけなので、私もよく深めたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"提案","question":"先ほど話をさせていただいた福井県坂井市で全国シティプロモーションサミットというのが１０月２６日と２７日に開かれます。案として話をするわけであって、これは区民委員会のちょうど調査事項に合致するので、検討してみたらいかがでしょうかという提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"去年、私、総務委員会でシティープロモーションだったので、区民委員会のほうで大丈夫なのかな。ただ、テーマそのものが私の手元にないのであれですけれども、それも踏まえた案なのかなと思いますけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"２人行かれるのか、今聞いてはだめよというならいいのですけれども、両方来てくださるからオールラウンドにと。だって、視察に行ったときに部長の質問とかがあるから、その辺は伺ってしまって、委員長、もしよければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"区としてもたしかプレスのあれの中にも再構築という観点であったかなと思うのと、中小企業支援のいろいろな角度の支援があるではないですか。そんな角度でお願いしたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"提案","question":"提案というかあれですけれども、７月４日までに提出ということなので、次の委員会で具体的にというふうにうまく進めていったらいいのではないかなと。２人参加かなと思いつつも、藤原委員が言ったようにそれを考えなければいけないと思うので、まだ今日どうこうはないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-04","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その理由として第４条、なぜこの条文で自主性の担保となるのかよくわからなかったので、改めて条文に添って説明していただきたいということです。区の自主性は担保されているという説明が第４条と第５条ということで、この関係がよくわからなかったので改めてご説明いただきたいということです。","respondent":"伊崎地域活動課長","answer":"では、ご説明をいたします。第５条で、第１項で「区長は、実施しなければならない。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"この「活動するよう」との規定が、それを第４条と第５条で基本理念の強制性を規制するという組み立てなのか、そこを伺いたいと思います。第３条の「活動するよう」とは参加の協力を求めるという、要するに区民に要望するという意味なのか、「活動をする」ですから私は。","respondent":"伊崎地域活動課長","answer":"ただいまご指摘いただきました第３条ですけれども、第３条の(1)の「活動するよう」というところの文理解釈の問題だと今、承りました。文理解釈上も、条文の文理解釈上は強制ではなく、目指す姿を希望として述べているものです。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこも含めてもう少し伺いたいと思うのですけれども、つまり「活動するよう」とは区民への希望、要するに要望という趣旨だということなのでしょうか。「区民に求めます」というふうにすればよかったのが、要望としたのかよくわからないので、条例ですから。","respondent":"伊崎地域活動課長","answer":"ですので、今、日本語としての助動詞の意味合いについてのご説明をし、そこからこの条例についての意味を述べさせていただいたものです。区民の主体性を尊重し、活動の活性化を行っていくということで貫かれている精神ですので、解釈上もそのようになってあります。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"活動への希望を求めているということなのか、そこを確認したいのと、それは正直に言います。２つ目の質問が、区長の主体的な尊重としたのはなぜなのか、その点も伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日のやりとりでも、やはり文章上の曖昧性を私は感じますし、自主性を損なう余地、解釈によってはありうる余地があるのだと思います。これはとても重いことだと思いますので、自主性をしっかりと活かしていただきたいと、意見だけ述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"いながわ委員","kind":"質問・要望","question":"その根拠としてこういう条例ができるということはある意味、全体を担保された感じになるので、逆に町会の人たちはすごく動きやすくなる。これがしっかりと運用されるように、今後もしっかりとやっていただきたいという意見というか、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認したいのが、町会の自主性や主体性が阻害されたと言ったらいいかな、中塚委員がおっしゃったようなことがあったのでしょうか。私は、いながわ委員がおっしゃったように、これに基づいて町会はより主体的に動きやすくなったと思うのだけれども、その確認だけお願いします。","respondent":"伊崎地域活動課長","answer":"４月以降、その面では加入促進、一部からいただいております。これからどのような活動の支援の、活動の活性化を行っていくかということは、区としても支援をしてまいりたいと考えております。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2756#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26062,"voices":106}},{"id":"h28-20160628-7","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"厚生委員会","time":"午前１０時００分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"はじめに(1)、平成２７年度介護保険制度の運営状況","agenda":"はじめに(1)、平成２７年度介護保険制度の運営状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"認定を受けずにチェックリストで要支援１、２相当ということで判断をされた方なのか、そのことをお聞かせほしいと求めました。まずチェックリストでやって、認定は受けられますという説明は、全ての方にされているのかということについてもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"要支援１、２に相当する方のほか、その事業の対象がふさわしいと判定された方となっております。状態を見ながら、一番ご家族、ご本人にとってふさわしいサービスを提供できるようにケアマネージャーが相談に乗っている状況になっております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要支援１、２相当でなければ受けらないということではなくて、自立の方も含めた方が総合事業対象になるということなのか。通所型、この部分だけが要支援相当でなければ受けられないという考え方になるのか、そこのところを教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"必ず認定を受けなければならないことになりますので、そういう方は要介護・要支援認定を受けていただくことになります。そろそろ弱くなってきたとか、このままの状態でいったら本当に要支援とか要介護になりそうだと思われる方につきましては。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その方は３ページに書かれている介護予防、ケアマネジメントの９７人ということで考えていいのか、教えていただきたい。相談に見えた方全員に説明されているのかどうかについても、先ほどお聞きしたのですけれども、お願いします。","respondent":"永尾高齢者福祉課長","answer":"それから、３ページの９７という数字ですけれども、人数ではなくて９,７００万円のお金がかかっているということになります。制度も変わっておりますので、その内容も含めて、説明を丁寧に行っているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、してほしいと求めましたので、そのことはもう１回お願いしたいと思います。そういう中で、特定施設がどんどん増えていることに対して、区としてはどう考えられているのかについて、お聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"これは一時期急に伸びたときがございましたけれども、直近では同じような傾向の伸びになっているかと認識しております。今度どんどん民間が出てきて、有料老人ホーム等ができておりまして、様々な形態で高齢者の生活を支えることは大事なことだと認識しています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護が必要になったときに介護保険が受けられないというペナルティは、品川区としてはとっていないということなのか、その確認をさせていただきたい。そういう実態がすごく多いですから、そういうところでは他の生活福祉課などと連携をとっているのかについてもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"では、実際に滞納されている方の実態になりますけれども、年金をもらっているのですけれども、金額が少ないという方が一番難しいかと考えています。状況を確認した中では、基準額に入りそうであれば、生活福祉課とも連携しながら行っているところです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"窓口で一番区民の大変な状況をつかめる場所だと思いますので、そういう連携も取りながら、今後ともどうぞよろしくお願いいたします。最後に１１ページで、地域支援事業が５.９％ということですけれども、その考え方も合わせてお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"地域支援事業につきましては、そういう考え方ではなくて、事業を始める前の予防給付の額に高齢者の伸びを掛けたものに変更になりました。移行までの３年間は１０％上乗せしてもいいということになっておりますので、区としては、財源の中でできる最大限の体制になっております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、今回は５.９％になっていますけれども、キャパシティとしてどこら辺まで地域支援事業の中に含めていくのかというあたりを、わかったら説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"これも介護保険財政になってきますので、全体の総金額を見据えながら、どこまでが適正かということを考えていかなければいけないと思っています。それから、また余計にすればいいということもなく、そういうところのバランスをきちんと見ていかなければいけないと感じております。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問","question":"１点だけですけれども、６ページの地域密着型サービスの利用実績の中で、1)、2)の認知症関連のところの予防の件数が非常に少ないということで、2)はずっとゼロなのですけれども、それぞれの事業内容と、なかなか件数が伸びない理由等がわかれば、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"要支援１、要支援２の方は厳しいかもしれませんけれども、要支援１の方の場合だとそこまで進んでいない方が多いと思います。予防の給付は要支援２からと決まっておりますので、要支援１の方は対象にはなりませんので、そういう部分で件数としては少なくなっております。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"1)については、その一歩手前の予防の段階で、もう少しこのあたりが増えていったほうがいいのではないかと思うのです。これがあまり必要なければ、これはどうなのだろうと思いますし、そこら辺がよくわからないので、もう１回、お願いします。","respondent":"永尾高齢者福祉課長","answer":"認知症対応型通所介護の事業ですけれども、実際に一定程度認知症が進んでおりまして、その方のデイというイメージになっております。認知症のまだ軽い方につきましては、一般介護予防事業等を利用することをお勧めしています。","id":"exchange-009"},{"speaker":"安藤副委員長","kind":"質問","question":"第４段階ということで、これは本人の申請によるものなのでしょうか、そこら辺をお伺いしたいと思います。利用者の意見はわかりましたけれども、区としては、特定施設の環境についてどのように考えているのか、お伺いします。","respondent":"永尾高齢者福祉課長","answer":"１３件ということで、制度の説明とか、制度のことでわからないなどということは件数には入っていません。今回の１３件は、事業者のほうの接遇の問題やいろいろな対応の問題、そういうような苦情がほとんどになっております。","id":"exchange-010"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"２９件という数字ですが、多いのではないかというところも含めて、お考えをお伺いしたいと思います。最後に３ページの表示の件ですけれども、私はぜひ、別立てで表示をしてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"事業者のほうのサービスや区の説明の仕方とか、福祉法人等の対応など、そういういろいろな部分で参考になることは多いかと考えています。件数ですけれども、条件が全てそろうということになりますと、やはり限られてくるのではないかと思っています。","id":"exchange-011"}]},{"id":"topic-02","title":"平塚シルバーセンター跡の施設整備","agenda":"平塚シルバーセンター跡の施設整備","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"シルバーセンターと同じような機能をつけてほしいというご要望が出ているということですけれども、１階は、具体的にどんな状況になるのかということ。2)のほっとサロンということで、シルバーセンターと同じような形で使えるようなものはあるのかどうか、一つ教えていただきたい。","respondent":"松山高齢者地域支援課長","answer":"２点目ですけれども、今後、検討したうえで決めていきたいと考えています。もともと平塚シルバーセンターも２階建てでしたので、整備後、近隣への圧迫について考慮すると、３階建ては難しいと考えております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういうものにしていくかということは、地域の方の要望に沿った形で、使えるようにということでお願いしておきたいと思います。これからどういうものに使えるか検討するということですけれども、できる場所だと考えてよいのかだけ、ちょっと説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"住民主体の通所サービスのことですけれども、昨日の大崎ゆうゆう地域ミニデイのモデル事業のモデルを検討して、区内展開を図るという方向ですので、こちらにつきましても、その可能性は探っていきたいと考えています。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"何点か教えてほしいと求めました。当然、交通を遮断するというようなタイミングがあるかと思いますので、その点をお聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"確かに前面道路が４ｍないところや、十分に業者と連携を取りまして、事故のないように十分に配慮してまいりたいと考えています。確かに高齢者や自転車で通る子どもなども含めて、交通に関しても事故のないように十分に配慮し、気をつけてまいりたいと考えております。","id":"exchange-014"}]},{"id":"topic-03","title":"ロタウイルスワクチン任意予防接種費用の一部助成","agenda":"ロタウイルスワクチン任意予防接種費用の一部助成","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"私どもの会派には専門家がいらっしゃって、こだわりの要望だったことに区のほうも応えていただいたということで、大変ありがたく思っています。あるいは同様のものを見たときに、少し交通整理が必要なのではないかと懸念するところですが、その辺の考え方を説明するよう求めました。","respondent":"舟木保健予防課長","answer":"そこは、こちらのほうも契約医療機関のほうにご説明いたしまして、そのような形で進めさせていただきたいと考えています。事業を進めながら、よりわかりやすく、改善していくところはしていきたいと考えています。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問・要望","question":"どうしても口頭ベースの説明は必要なのですが、マニュアルというか、ガイドラインのわかりやすさを求めた展開が必要な気がしました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"もう少し詳しく教えていただきたいのですが、１回約１万５,０００円で、大体半額くらいが助成される。それから、５価のほうがどちらかというと幅広く対応するというイメージを持っているのですけれども、その辺ももう少し教えていただけると助かります。","respondent":"舟木保健予防課長","answer":"大体１万２,０００円か１万８,０００円の間で平均的に１万５,０００円弱くらいかと、こちらのほうの調査の結果で出てまいりました。そこはまたかかりつけ医とご相談していただきながら接種していただければと思います。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"提案","question":"よくわかりました。渡辺委員からもありましたけれども、我々の会派としても提案してきたので、混乱のないようにぜひお願いしたいと要望して終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"接種率を向上させることによって疾病の予防を図るとありましたけれども、接種率がどのくらいになっているのか、わかったら教えていただきたい。渋谷区では８,５００円を２回まで助成しているということはあったのですけれども、２３区の助成の状況がわかったら教えてほしいと求めました。","respondent":"舟木保健予防課長","answer":"ロタワクチンにつきましては、国のほうも、今、検討を進めているところですが、定期化するにあたっては課題が幾つか挙がっております。ワクチンの費用が結構高額なので、費用対効果の評価が引き続き必要だという形で、まだ検討を重ねているという形で聞いております。","id":"exchange-019"},{"speaker":"松永委員","kind":"確認","question":"少し確認でお伺いしたいのですが、先ほどの質問の中にあったように、契約医療機関によって金額が異なるということですけれども、ワクチンは全く一緒のものなのか、それとも扱っている機関によって種類が変わってくるのか、メーカーが違うのか、その辺の確認をお願いしたいと思います。","respondent":"舟木保健予防課長","answer":"ただ、医療機関によっては、どちらかのワクチンしか扱っていないところもありますし、２種類のワクチンとも扱っているところもあります。保険診療ではありませんので、そこの部分で、どうしても接種費用に差が出てしまうことになっております。","id":"exchange-020"}]},{"id":"topic-04","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"たけうち委員","kind":"提案","question":"安倍総理も今年４月に視察に訪れたらしいですが、またそこに住んでまちづくり、また障害のデイサービスなどを含めてやっているところがあります。全対象型というのと、先ほどの長岡市の取り組みを見てみたいと思っており、提案しますとの意見を述べました。","respondent":"渡部委員長","answer":"そしてその就労支援等、条件で始めているという取り組みに非常に興味があったので、私どもも一つの希望として挙げております。福井県のほうで認知症高齢者支援、まちぐるみでやっている温泉病院の取り組み。","id":"exchange-021"},{"speaker":"松永委員","kind":"意見","question":"どういった取り組みをされているのか、それから塩尻市、諏訪市という形になっているのです。委員長、副委員長に任せますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"品川区でいろいろ立ち上げていただくということですけれども、グローの滋賀の施設を、ぜひ視察したいという希望です。今年は障害者権利条約が批准して２年で、所管事務調査の中に入らないのであれば、そこを深めていただくということで検討いただけたらと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":29097,"voices":72}},{"id":"h28-20160628-8","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"建設委員会","time":"午前１０時００分～午前１１時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"補助１８号線に係る土地収用に関する損失補償請求事件","agenda":"補助１８号線に係る土地収用に関する損失補償請求事件","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"もともとの、東京都収用委員会の確定した数字というのは幾らぐらいだったのかというのが、まず１点お聞きしたいと思います。それともう１点、決定したのは平成２２年ですけれども、まずその２点を説明するよう求めました。","respondent":"矢木用地担当課長","answer":"平成３年１１月２８日に事業認可の告示がございまして、原告と交渉をしたのは、平成１０年の１２月から交渉開始しておりました。そして、平成２２年３月に収用認可の採決が出ているものです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問","question":"あまり通らないので、たまにあの辺へ行くと、拡幅したなというのは、何か記憶があるのですけれども。平成１０年から長年にわたって折衝を進めていっていただいて、折衝状況をもうちょっと教えていただければと、お願いいたします。","respondent":"矢木用地担当課長","answer":"そもそもが、こちらの方、立入調査を、この平成１８年に拒まれまして、そのことから、外観調査で区のほうも算定せざるを得なかった。算定した価格と、実際にかかってしまった金額がかなり高額になってしまったというところで、今回の裁判になっているところです。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから、収用委員会のこういう決定というのは、割合とその後、こういう訴訟などになるものなのですか。その辺がどうなのかと。","respondent":"矢木用地担当課長","answer":"３件ぐらい、マックスでも３件程度の収用裁決がありますが、この１件のみです。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。売却を求めていくような形をとってもらいたいと思いますので、これは要望で終わらせます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"都市計画道路事業のための土地収用で、損失補償額の変更を求めるということで訴えられたということなのですけれども、訴えたことで、なぜ品川区が払わなければいけないことになるのかというのがちょっとわからないので、教えていただけますか。","respondent":"矢木用地担当課長、安井土木管理課長","answer":"こちらは、私どももあらゆる主張をしたわけですが、裁判所が客観的事実に基づいて、被告・原告双方の主張に基づいて判断したところ、一部、考え方の違いと申しましょうか、が出て、追加補償という形になったものです。 補足しますけれども、これは、品川区が都市計画道路補助１８号線の整備を進めるということで、区施工の都市計画道路で整備したものですので、品川区が被告として登場したという形になっているものです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"４,５９２万円という、すごく大きいですよね、金額が。こういう金額に結果的になったのだと思うのですけれども、あまりにもこの大きい差があるので、この金額の差はどこから来る差なのか尋ねました。","respondent":"矢木用地担当課長","answer":"ちなみに、判決額は１６１万５,１００円で、品川区の金額に近似してございました。品川区としては、相当の見積額を主張したということで、この金額の乖離が出てあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"意見","question":"もともと、都市計画道路とわかっているわけですよね、この不動産の場合は。なおかつ、こういう裁判をかけるというのは、主張するというのは、どうしてそういうふうになっているのかなと思うのですが、わかる範囲でとの意見を述べました。","respondent":"矢木用地担当課長","answer":"平成３年になりまして、当然のことながら、ここは計画地であるということは認識があったということは確認しています。任意売却をしていただくという対応で、訴訟に至っては、もうこれは初めてのような事例です。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"その条件のもとに住んでいるということになるのですから、それは困るのですけれどもと言われても、困ってしまうわけですよね。公共としてしっかり主張してもいいところなのではないかなと思うのですが、いかがか尋ねました。","respondent":"矢木用地担当課長","answer":"委員ご指摘のとおり、こちら、都市計画道路ということで主張してまいりまして、裁判でも、実質上勝訴ということで、公にも認められているところです。今後も、こちらの主張は従前どおり主張してまいりたいと考えております。","id":"exchange-008"}]},{"id":"topic-02","title":"しながわ区民公園中央ゾーン改修工事等","agenda":"しながわ区民公園中央ゾーン改修工事等","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"３番の今後のスケジュールのところで、大体何月ぐらいなのかを、それぞれ伺いたいのと。キャンプ場は、老朽化した施設を更新するということですけれども、使える形で更新されるのか尋ねました。","respondent":"溝口公園課長","answer":"そのほかの3)、4)、ここについては、９月頃から工事に着手していきたいというふうに考えております。一旦閉鎖させていただいて、今もう既に周知しているところですが、９月の初めから今年度いっぱいは使用中止という形で周知をしています。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたら、ここは９月から閉鎖という形になるのですね。今、そういった、いろいろな方が便利に使いやすいキャンプ場にしていくという考えはあるのか尋ねました。","respondent":"溝口公園課長","answer":"皆さん、ご利用される方がお持ちいただいて利用していただく、そういったことを基本的に考えております。様々な利用者の利便性の向上、または利用してもらえるキャンプ場になるように考えていきたいというふうに考えているものです。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"この、しながわ区民公園ですけれども、多くの障害者の方も利用していると思うのですけれども、園路のところでは、利用者の円滑な通行と、ということで書かれているのですけれども、バリアフリーの面でいうと、トイレだったりとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうですね、どんな配慮がされるのか、あれば、説明を求めました。","respondent":"溝口公園課長","answer":"身障者対応として、そういっただれでもトイレを設置することによって、バリアフリー対応にしていきたいというふうに考えております。今回はアスファルト舗装で、誰もが利用しやすい、歩きやすい環境に整えていきたいというふうに考えるものです。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"９月から１２月まで閉鎖ということで、もしくは増設をするのか、その辺のことを少しお聞きしたいと思います。","respondent":"溝口公園課長","answer":"ちょっと説明が悪くてですね、キャンプ場の閉鎖期間なのですけれども、９月から来年の３月いっぱいまでを予定しているものです。今回、キャンプ場につきましては１５基の釜がありまして、整備後も同じように１５基整備するものです。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"この売店というのは、どういう売店、規模を考えているのでしょうか。どこかに行ってしまったりしたら、それは問題になってしまうので、どういう想定をされたのかということでお願いしたいと思います。","respondent":"溝口公園課長","answer":"しっかり考えた上で、来年の４月には、きちんと皆さんが利用しやすい売店にしていきたいというふうに考えているものです。いろいろトラブルが起きる可能性がありますので、この点についてはしっかり所管のほうに申し入れておきたいというふうに考えているものです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、その反面、危険性も伴ってきますので、それはいろいろ調整を図ってほしいと求めました。ちょっと、食のことを含めて、何かこの辺工夫ができるといいなと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"今回、売店は今の状態でいいとは思っておりませんので、どういう形でのサービスを提供していくのか、それはしっかりと検討していきたいと思います。どういうイベントができるのか、そういったものも合わせてしっかり考えながらやっていきたいというふうに考えているものです。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは品川区内、確か２カ所目というふうに聞いていますが、どういうものかということを１点お聞きするのと。今回、ここにプレイパークをつくるということになった、これまでの経緯も、ちょっと簡単にご説明ほしいと求めました。","respondent":"溝口公園課長","answer":"基本的には何も物を置かないような形で、自由な発想で遊んでいただける、そういった広場となるものです。プレイパークの設置について、そこを有効に活用する形で、プレイパークの設置をしていくということを考えているものです。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"そういう、いわゆるリーダーがいるということがプレイパークということと、ただの原っぱとの違いなのか。立地的なことで、今回ここにということになった理由を、もうちょっと詳しくお願いします。","respondent":"松代防災まちづくり部長","answer":"本来なら所管課長が答えるべきなのですけれども、私も公園事業関係を４０年近くやっていまして、思いがありまして、ちょっとお話しします。子供たちとプレイリーダーと一緒に考えながら、さらに積み上げていけると、そんな公園にしたいという思いでつくるものです。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"そういう目的に沿った形での整備ということで、お願いしたいと思います。つくってみたら足りなかったみたいなことになると心配だと思ったので、その辺はどのような検討がされているかだけ最後にお聞きしたいと思います。","respondent":"溝口公園課長","answer":"基本的に駐車場自体をすぐ拡幅するというのは、こういった公園として利用している部分もありますので、難しいと思います。は迷惑をかける、また安全上必要なものであれば、そこはしっかり見極めながら整備していきたいというふうに考えているものです。","id":"exchange-018"}]},{"id":"topic-03","title":"目黒川氾濫および津波発生時の避難基準","agenda":"目黒川氾濫および津波発生時の避難基準","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"避難の対象者への避難情報の伝達方法については今後検討ということなのですけれども、避難対象者というのは、どれぐらいいるのか尋ねました。","respondent":"和田河川下水道課長","answer":"まだ机上の概算ではありますけれども、今回の目黒川の避難対象、それから津波の避難対象と合わせて、１万世帯ぐらいだというふうに考えております。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"伝達方法については今後検討ということですけれども、やはり伝達していないと意味がない対策だし、今回の基準になってきてしまうと思うので。１軒１軒回ってというようなお話もありましたけれども、今のところどういったところをお考えなのか、説明を求めました。","respondent":"和田河川下水道課長","answer":"この補正予算で、来年の雨季までにやるには１年ぐらいかかるかと思うのですけれども、昨日１軒１軒回るというのを説明させていただきました。各個人に、区役所から直接避難情報を伝達できる方法、システムを構築するというものです。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"この津波に対する避難対象地域の、青いところ、さらに緑色のこの部分は、これはどういった意味なのでしょうか。ちょっとこの２点をお伺いいたします。","respondent":"和田河川下水道課長","answer":"先ほど私が説明した、この青色の枠の中にちょこちょこっと見えます緑色の範囲、これが浸水の想定されるエリアになってあります。区役所としましては、安全側に、この青色の範囲の方々に避難を呼びかけるということを想定しているものです。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"では、この津波に対する避難対象地域の赤線も町丁目ということでよろしいのでしょうか。このオレンジ色の太い線は、津波注意報、海抜２ｍ以下の地域ということを表わしているという理解でよろしいのか尋ねました。","respondent":"和田河川下水道課長","answer":"津波注意報で、海抜２ｍ以下の津波が発生した場合に、避難指示を呼びかける。先ほど、資料の２ページ目の下の、津波注意報の場合の、避難指示を呼びかける施設名と書いてある、その施設の位置を表わしたものです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"意見","question":"目黒川の氾濫に対する避難対象地域（案）が出ていますが、これは五反田の地域になりますが、これより下流部はどういうふうに考えたらいいのか。それはどういうふうに考えているのかとの意見を述べました。","respondent":"和田河川下水道課長","answer":"それから深さに関しては、０.５ｍ以下と、そのようなレベルでおさまるだろうと。０.５ｍ以下でも、下流側へも避難勧告、避難指示は判断していきたいというふうには考えてあります。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大体わかったのですが、場所として、居木橋あたりからずっと下流あたりは、あの辺は高いから、そういう点では大丈夫だろうと判断するということでよろしいか尋ねました。","respondent":"和田河川下水道課長","answer":"そのとおりです。","id":"exchange-024"}]},{"id":"topic-04","title":"多摩川の洪水浸水想定区域の指定・公表","agenda":"多摩川の洪水浸水想定区域の指定・公表","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この１の(1)のところで、２日間に５８８mmの降雨があったときに多摩川が氾濫するということなのでしょうか。それ以下なら氾濫はしないということなのか尋ねました。","respondent":"古巻防災課長","answer":"最大規模２日間に５８８mmで、氾濫するしないという判断は、ちょっとこの場ではお答えが難しいというふうに思っております。５８８mmという設定をして、その場合、多摩川がどういった状況になるのかといった観点からのシミュレーションを行ったというふうになっております。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"意見","question":"先ほど説明もあったとおり、氾濫した場合に、南大井等の地域で１ｍ浸水というところでは、大変な水位だなというふうに思ったので、どれぐらいが最大なのかなというふうに思ったのですけれども、はい、わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"塚本委員","kind":"確認","question":"最初にちょっと確認したいのですけれども、決壊をしたということが前提で、これは考えられているわけですか。ちょっとお聞きしたいので、ご答弁をお願いします。","respondent":"和田河川下水道課長","answer":"５８８mmという雨ですけれども、最大降雨として調布付近に５８８mmを降らせた場合に起こり得るシミュレーションということになってあります。ぐっとレベルを上げたもので解析をし、その結果、決壊をするかもしれないというシミュレーションになっているものです。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"決壊しないようにここをまず補強するという対策も、１つは考えられるのかなと思うので、そこはどうなっているのかということと。どういう状況で避難指示を出していくのかというのを、ちょっと教えていただきたいのですが。","respondent":"和田河川下水道課長","answer":"決壊点が１点のように資料では見えますけれども、どこが決壊したらどんな浸水が起こるかというのが、全て見られるようになっています。先ほど目黒川で説明したものと同様に、氾濫危険水位のときに避難勧告、基本的には決壊する前に避難指示は出されるというものです。","id":"exchange-028"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"その辺がどうかなというのが、１点、調査できないかと思っています。日程的にも、委員会等ありますので、あとは正副にお任せする形で、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"筒井委員","kind":"意見","question":"恐らく相当やられていると思いますので、都市型震災対策としては、そうした町とかがいいかなと思いますけれども。参考までにとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"道路推進や整備、全体に反対なわけではないですけれども、否定するものではないですけれども、私たちこの間、一般質問等々でも示させていただいているところですので、道路大会には参加はしないということで、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4174#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":26740,"voices":107}},{"id":"h28-20160628-9","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件整理しています。","topics":[{"id":"topic-01","title":"小・中学生の生活状況調査の実施","agenda":"小・中学生の生活状況調査の実施","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、国の子供の貧困に対する大綱が平成２６年８月に決まったということで、今回、この調査が約２年たってしまった経緯を教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"対応につきましては、生活福祉課でありますとか子ども家庭支援課でありますとか、各所管について対応をしていたところです。より連携を深めないと、連携を深めるためにということで検討委員会を立ち上げまして、対応することになった次第です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、これまでもそれぞれの所管でやってきたのを、今回、さらに連携をしていかなければ子どもの貧困対策というものが進んでいかないということで、今回の連絡会議でそうなったという理解でいいか、ちょっと確認です。","respondent":"廣田子ども家庭支援課長","answer":"今までも連携はしていたのですが、品川区の子どもたちに対する施策を強化するということで、連携をさらに深めるということになった次第です。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"この調査対象が２年生と９年生になっている理由を教えてほしいと求めました。調査内容で、世帯の基本情報とあるのですけれども、この基本情報というのは何が含まれているのか教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"７月の調査になりますので、小学校１年生に調査をいたしますと、小学校生活を１年以上過ごしたという２年生にいたしました。主に質問項目の基本情報としましては、世帯の人数と生計をともにしている人、あとは世帯の収入についてもお聞きする予定です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"９年生のところは、進学についても聞いていきたいということで、国のほうでも奨学金等を検討しているみたいなのですけれども、区としても、やはりそういったところをつかみたいというところもあって、この９年生のアンケート調査をやっていくということなのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"奨学金とか、個別具体的なことではなくて、親御さんが子どもの進学をどこまで考えているかというところを実態としてつかみたいというところで考えてあります。","id":"exchange-004"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１回、客観的なデータで調査しようという品川区の対応ということで、僕は非常によいことだと思うのです。そのデータをどうやってまとめて、どのような形で施策に活かすとか、その辺のことはどういうふうにお考えなのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"ニーズと施策の実態が合っているかという検証を行いまして、夏までにフレームをある程度設けることを目標としていまして、年度末を目途に報告書を作成するという予定です。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どのような形で報告書を作成して、それを受けるほうはどうなのでしょうか。例えばホームページでするのか、文教委員会でするのか。","respondent":"廣田子ども家庭支援課長","answer":"新規の事業と拡充事業をやるとかが出ましたら、予算等に反映させなければならないので、そちらでお諮りさせていただこうと考えています。区民への周知等につきましては、検証の内容によって、区民に周知する必要性でありますとか、やってみる……。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"どういう形でやるのですか。区民への周知を聞いているわけではなく、どういう形で、どういう対象にやるのですかということをお聞きしている。","respondent":"廣田子ども家庭支援課長","answer":"施策の検証ですので、まず議会に報告するということを考えてあります。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"どのくらいの人数で、あと、例えば外部の専門家がいらっしゃるかどうか。ありていに言えば、検討委員会の概要と目的とスケジュールを説明するよう求めました。","respondent":"廣田子ども家庭支援課長","answer":"検討委員会自体は、本年度は４回程度を予定しておりますが、実務者との調整。４回の検討委員会に向けて、調整部会、作業部会が動いていくということを考えています。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"スケジュール的には、例えば何年間でこの調査の何をするとか、そういったことは決まっているのですか。それとも、調査をした後で、また考えていって、いつごろまでに何をするという、その先というのは特に考えていらっしゃらないのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"目標といたしましては、平成２９年度の予算編成までに拡充すべき事業について検証しようと考えています。予算取りもしていない状況で、平成２８年度の検討委員会の検証を行った上で、平成２９年度以降の見込みについては考えていこうと考えています。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"ひとり親とか虐待の実態ですとか、どこからかの段階では専門家の助言も入ったほうがいいのではないかと思いますが、いかがでしょうか。今は即答できないかもしれないのですけれども。","respondent":"廣田子ども家庭支援課長","answer":"現在、どこまでのデータが出るかというところで、今まで出なかったデータも洗い出している状態で、データを出し切った段階で、必要性を感じたところで検討をしたいと思います。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"義務教育学校の在籍者を対象にということなのですけれども、例えば７年生以上、中学生の３割は区立学校ではない学校に通っているわけです。調査が難しい面もあるかもしれないですけれども、ここを最初から落とすのはぜひやめていただきたいと思うのですが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"生活保護というのが３点セットで、１回、また検討させていただこうかと考えております。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"それは、次の段階では、何らか補足することを考えていらっしゃるということですか。それとも、実際にはやらないかもしれないということなのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"今回は、小学生、中学生で２,５００人、１,６００人で、マクロが４,１００人程度を予定しておりまして、サンプル数的には不足はないと思います。状況をこれで検証させていただき、また新たなる課題に向かうときに、方法等については検討させていただこうと考えています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"意見","question":"けれども、一定の属性を持った人たちがすっぽり抜けてしまうというのは、サンプルの質としてどうかと思います。これでやっていただければいいと思うのですけれども、これだけの結果をもって区内の小・中学生の実態であるということは、私は間違いだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"それとの兼ね合いも少し教えていただきたいのと、内容が違うのか、その点も確認をさせてほしいと求めました。何かアンケートをいただくということがもし可能であれば、調査内容も教えていただければと思うのですが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"１点目が、学校で回収したほうが回収率が高いということは認識していますが、学校に収入について知られるのではないかと。小・中学生に実施する調査票についてですが、集計を行った段階で、中間報告も含めて委員会でご報告できようかと思います。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、区としてこういうことを考えているというようなものがありましたら、少し教えてほしいと求めました。そういうところへの補助とか、何か区としてできるイメージがありましたら、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"現在、公に申し上げられるものはないのですけれども、検討をしながら、結果が出るまで動かないというわけではありません。検討も並行して行っておりますので、しかるべき時期に来ましたら、ご報告をさせていただこうと思っています。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つは、本来はどうなのかというところを調査しようと、教えてほしいと求めました。なかなか２年生は大変かもしれませんけれども、このプロジェクトに入っていると思うのですが、その辺もお願いしたいのです。","respondent":"廣田子ども家庭支援課長、有馬学務課長","answer":"共働き家庭やひとり親でなくても一定の課題があるのではないかというところで、設問を考えているところです。どう取り組んでいるかというところを聞いて、実際に経済的な面も含めまして、施策に反映させたいと考えているところです。そういう意味からしても、最初の配付のときに、しっかりその意図が伝わるようにするということはとても大事だと思っています。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さっき伺った、生まれる前からかもしれませんが、ずっとつなげて調査をしていただきたいと思うのが１点です。大綱を受けての検討委員会なのですけれども、ほかの自治体でも、全てこういうふうな立ち上げをして調査を行っているのかどうかを示すよう求めました。","respondent":"廣田子ども家庭支援課長","answer":"当面は３点の就学援助、ひとり親を取り巻くところから少しずつ、コアから広げていくという意味合いです。３月の調査で十数区だったと思うのですが、他区が行った調査では、何らかの形で立ち上げているところがあると認識しています。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"今回は調査なのですけれども、お伺いする、聞き取るだけではなくて、困ったときの相談体制などが結構あちこちあります。そういうものの発信をあわせて、簡単なものでもいいので、この中でできないかと思っているのですけれども、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"何らかの形で相談体制は処置することは大切だと思いますので、考えたいと思います。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"回収率について、どのように考えていらっしゃいますでしょうか。それについてどのようにお考えなのか説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"郵送にしたので、今のところの見込みとしては、６割は回収してほしいと考えています。４,１００人の６割なので、回収して６割が返ってくると２,４００人ほどになるので、サンプル数だけで言えばいいと考えています。","id":"exchange-019"}]},{"id":"topic-02","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今は計画段階で、変わるかもしれないということだったのですけれども、できれば、各施設の年齢別の定員を教えていただけたらと思うのですが、。","respondent":"大澤待機児童対策担当課長","answer":"このえ中延保育園、ゼロ歳児が６名、１歳児が１０名、２歳児が１２名、３、４、５歳は１４名ずつとなります。北品川一丁目保育施設につきましては、１歳児が６名、２歳児が９名、３歳以上は１５名ずつとなります。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"会派としては公営でやっていただきたいと思って、公営でやっていくという検討などはされたのか、伺いたいと思います。今、計画中だと思いますが、幾らぐらいになるのか教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"それが難しい場合は公設と考えておりますので、今のところ、公設公営という考えはございません。それと、北品川一丁目保育施設につきましては、今後の文教委員会で詳細をご報告しますので、今、金額等の資料は持ち合わせてございません。","id":"exchange-021"},{"speaker":"のだて委員","kind":"意見","question":"先ほど、今後も開設の予定はあるということで、今回も４園設置されるということで、今、保育士不足が言われておりますけれども、保育士の確保等はしっかりできて、４月のところから、まだ１年近くありますが、見通しはどうなっていますかとの意見を述べました。","respondent":"大澤待機児童対策担当課長","answer":"まなびの森保育園西大井につきましては、もう先々週から説明会を開いて、保育士確保に向けて取り組んでいると聞いております。見込みで保育士の募集を始めていまして、こちらも大田区に２園持ってありますので、品川区のほうできっちりやっていくと聞いております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、４月の開園で人員が整えられるように、区のほうとしても整備をしていって、待機児童が出ないようにやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、北品川一丁目保育施設は、暫定ということでしょうか。それから、ゼロ歳児園と１歳児園があるのですけれども、どういうところでゼロ歳にして、どういうところで１歳にという、何か切り分けがあるのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"北品川一丁目保育施設につきましては、５年の暫定期間を考えておりますので、そういった意味で１歳児になっております。えがおの森保育園・かつしまにつきまして１歳児というのは、事業者の考え方にもよりますので、保育園の考え方にもよると考えています。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問・要望","question":"常に区がきちんと運営を見られる状況にしておいていただきたいし、そのためには、まずは詳細な契約が必要であると考えています。それについて、ぜひ、抜かりのないようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところを聞かせていただきたいのと、どういう経過を経て、この発表に至っているのかを教えていただきたい。特に土地の問題、土地を探すのにかなりご苦労があると思うのですが、どのような経過なのかを説明するよう求めました。","respondent":"大澤待機児童対策担当課長","answer":"特に４月、５月は、各事業者からご提案をいただきまして、計画承認に向けて、区と調整をするという形になっております。そちらは大変よい保育園だということで、東京都競馬から、ぜひ千趣会にとお話しされたと私どもは伺っております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まだ現地を見にいっていないので、どういう状況なのかというのを教えてください。お金はどのくらい差があるのか、どんな状況なのか、教えていただきたい。","respondent":"大澤待機児童対策担当課長","answer":"仮囲いをつくりまして、その中で土壌改良工事をしておりますので、その後に、８月から保育園の設置工事を始める予定になっております。えがおの森保育園・かつしまにつきましては、８月から工事を始めまして、１月の中旬にはでき上がる予定です。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"平成２８年度の予算はこれでいいのかと思って、１,９００万円計上されているのと、園舎の借り上げとかはもう具体的になっているのですか。この表の見方がよくわからないのですが、いつ段階だったら、実際にかかる費用がわかるのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"今、１,９００万円というお話で、平成２８年度の予算はそのとおりです。リース期間は前後１カ月ずつ、準備と解体等の準備が入って６２カ月で、３億７,２００万円です。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問","question":"今回は、そういう中で、定員の規模が６０人ということで、これは園庭をつくろうということで、こういう規模になるのか。どういうところからこの定員が出てきたのか、考え方を説明するよう求めました。","respondent":"佐藤保育施設調整担当課長","answer":"５年間限定と総合的に考えまして、この他４０名は、臨機応変にその辺はやっていきたいと考えております。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"今の定員は６０人とありますけれども、途中で拡大の可能性があるということは、施設的には少し余裕を持ってつくられるという理解でよろしいか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"委員がおっしゃるとおりです。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"ほかの委員の方から質問があって、あのような状況を過去に１度やられたというようなことは、なかなか把握し切れないものなのでしょうか。その点について、これから運営事業者等を決めていかれるということがあるので、そこをお尋ねしたいのです。","respondent":"大澤待機児童対策担当課長","answer":"プロポーザルで事業者を決定することになりますが、財務状況の確認等は公認会計士に頼んで、お願いしているところです。私ども、そこまで調べることがなかなかできていませんので、不測の事態ということはできるだけないように努力するとは思っております。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その点をぜひご留意いただきたいということと、仕様書の中でやっているので、さほど例の兵庫県みたいなことは起きにくいと。民民の形でやった中ではそういうことだと思うのですけれども、民民のチェックもきちんとしていただきたいのです。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園につきましては、東京都の認可ですので、基本的には東京都が指導検査ということになりますが、区の指導検査の担当も、必ず東京都が検査に入るときには一緒に立ち会って検査に入っておりますので、その辺は十分気をつけて対応していきたいと考えています。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"つかむ姿勢をぜひ持ってほしいと求めました。人件費比率とか離職率とか、保育の質の向上を図っていただきたいのですが、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"継続して勤めていただくことが大事だと認識していらっしゃいますので、研修制度、研修計画もきちんとつくっています。このえ中延保育園につきましては、パートの方も産休、育休をとれるということで… 今、担当課長から初任給の話をさせていただきましたが、改めまして、どの金額で、どのような処遇、年収があるかというのは事業者ごとの事業費に基本的になりますので、その取り扱いについてはご承知おきをお願い申し上げます。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公表するかどうかは別として、妥当な処遇、待遇になっているのかどうかというところをぜひしっかり把握をしていただきたい。所管のところもすごく大変かと思いますけれども、ぜひ、きちんとした仕事をしていただくためのチェックをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-03","title":"保育園の民営化と大規模改修計画等","agenda":"保育園の民営化と大規模改修計画等","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"幾つか確認なのですけれども、それぞれで中核にしていくということなのか、確認させてほしいと求めました。もう少し詳しく、どういった表現を考えて判断していくのか、説明をしてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"その辺を見きわめながら検討を続けていくというところで、幼稚園と保育園はそれぞれ別として、中核を担っていただきたいです。民営化の対象園の検討状況ですが、改築や大規模改修を実施するタイミングで併設施設でないところを一定の条件として考えているところです。","id":"exchange-035"},{"speaker":"のだて委員","kind":"確認","question":"今後は、そうすると幼保一体も考えつつ、中核にしていくということなのかという確認です。ほかにも特別保育の実施状況とかがあるのですが、この辺はどういった考えで判断されていくのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"幼保一体施設の関係に関しては、検討を進めながら両にらみで推進していくです。その辺の実施状況、やっているというだけではなくて、必要性も見ながら総合的に判断することも必要だです。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"民間活力の活用というところで、区内ではどういった特色ある保育等が行われているのか、教えてほしいと求めました。この特別な配慮を要する児童というのは、どういった方を対象にしているのか、具体的に教えてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"１点目の特色ある保育ですが、一時保育等と、そういったものを総合的に特色ある保育と考えているところです。２点目の特別な配慮を要する児童というのは、今、特別支援という事業をやっておりまして、そういった関係を想定しています。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"今回、人件費を削減していくということにもつながっていくのではないかという危惧があるのですが、このお考えはどうなっているでしょうか。改修してから民営化していくということですけれども、この改修費、昨日の話でもありましたが、これは区が出していくのか、伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"国と都から３,０００万円ぐらいの負担金が入りますので、その負担金等を見込んでいるのが１点と、区の負担は減ると考えているところです。改修、改築経費に関しては、当然、公設になりますので、公設に関しては区の予算で改築、改修をするところです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、民営化していくために公費で改修を行って、民営、委託していくということになるわけで、税金を民営化のために、企業のもうけのためにやっていくと見えるのですけれども、どう考えていらっしゃるのか、伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"改築経費の区の負担の考え方ですけれども、民営化するために無理やり改築、改修するわけではございませんで、施設的にもう老朽化がかなり進んでいて、改築が必要なところに、どうせやらなければならないことですので、改築と改修を行うです。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"もともと老朽化していて、改修していかなければいけないということですけれども、それは当然、必要なことだと思います。区民に説明できる形、納得できるようなご説明をいただければと思うのですが、いかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"私立保育園がもう区内にも３８園ありまして、民間でできることは民間に委ねるという基本方針に基づいて、まず民営化を進めるというのが１点あります。その辺は少しでも減らしたいというところで考えているところです。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"この７ブロックというのはどういう地域でまとまっているのか、これはどういう形でやっていらっしゃるのか、伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"南ということで７ブロックで、地域で連携して、いろいろな事業とかＰＴ等を行っている区分であるです。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"３点、確認します。同じ地域内にありますので、改修がされる方向なのか、確認したいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"三ツ木保育園の保護者の方への説明会を７月８日金曜日５時半から三ツ木保育園で行う予定です。八潮南保育園は、またその翌日、７月２８日に八潮南保育園で６時から保護者の方への説明会を行う予定です。","id":"exchange-042"},{"speaker":"新妻委員","kind":"質問","question":"この周知ですけれども、地域の町会、自治会にはどのようになっていますか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"７月１９日は夜間、３回に分けて、丁寧に説明をしたいと考えております。それ以外に関しても、三ツ木保育園の関係とか戸越公園の近隣、また、八潮地域センター全体の町会長会議等で工事の内容等をお知らせする予定です。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"八潮地区としてのキャパシティーを減らすべき時期なのかというと、私、そこはご心配されないのでしょうか。今、八潮地区でキャパシティーを減らす時期ではないのではないかと思うのですが、そのお考えを伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"考え方ですが、さまざまな特色ある保育を実施して、民間でできることは民間に委ねるというのが基本姿勢です。詳細については今後検討しますが、公であったり、専門機関との連携等は区のほうで多くを担ったほうがいいと考えているところです。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"どういう形で出していただけるかわかるといいのですが、教えてほしいと求めましたが、未定であれば未定ということで構いません。は八潮南保育園というのが一連の工事の後でどうなっていくかというのも含めて、ぜひ、区民に違和感のない方針をとってほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"運営費の比較を出す時点ですが、集計してみて、またお知らせしたいと思います。八潮南保育園の定員に関しては、繰り返しになりますけれども、直前と今後の推移等を見て、総合的にまた考えていきたいと思います。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出していただいた資料に沿ってお伺いしますけれども、１の(1)のところ、相当数は区立のままとすると。公立でやることの意味をどう考えているのかというところをお聞かせほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"２点目の特色ある保育等の区の考え方ということなのですが、区の保育に対する考え方やビジョンを変えるということはありませんので、教育を行って。公の専門機関等への連携等、さまざまな要因で区立の保育園もより強化をしていきたいです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここは本当に何回伺っても納得できない。保育力を活用していきますと言っても、結果的には賃金のところの問題点が大きく響くと思うのですが、その辺の考えはいかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"小１プロブレムのない保育にするのが、これから私たち、保育行政に携わっている者についても大きな課題なのではないかと考えております。したがって、私立園ではなく公立園の優位性というのは、少しずつ、もっと理解をしていただかなければいけないとは考えております。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"経験にふさわしい賃金になっているかどうかというところが、公立は８割が人件費で、人件費の割合が５７.２％なのです。ここはすごく大事な民営化のところで、ここを外しては議論にならないと思うのですが、その点はいかがか尋ねました。","respondent":"竹田保育課長","answer":"公立保育園の職員人件費が５７.２％というお話がありましたが、職員構成を見ますと、保育士の４割が２０代という状況です。新規採用を毎年５０人程度増やしているという中で、全体的に、同じ人数を確保していても人件費が下がっていくという傾向があろうかと思います。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"民営化はやめてほしいと思うのは、これから検証していくと書いてあります。ぜひ、踏みとどまって、考え直してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"客観的なデータの集積という意味で、公立と民間を比較したような、例えばアンケートとか調査とかのデータはあるのか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"区立保育園と私立保育園を比較しているデータなのですが、平成２８年４月入園申込者の方々の第１希望の数字があります。区立を第１希望に書いてある方は１,７４９名、私立を第１希望に書いてある方は１,３１５名と、ほぼ同程度という数字が出ています。","id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"客観的なデータをもとにして議論をすべきだと思うので、一部の極端に偏った集団の意見だけが出てきたりすることもないことはないかもしれない。そういう客観的なデータというのを１回、ぜひ集めて開示していただきたいと思うのですが、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"委員がおっしゃるとおりでございまして、客観的な事実、ファクトで私どもは説明させていただいているところです。データに基づかないご主張をされてしまうと、引き続き、区民の皆様にご意見をいただけるように努力をさせていただきたいと考えています。","id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"だから、子どもがいい保育園というのは、親がいい保育園と全く１００％一致しているかどうかというのはわからない。本当に子どもの幸せをもとにした親御さんの立場はどうなのかというようなことを、ぜひアプローチできるようなものが欲しいと私たちは要望します。","respondent":"あくつ委員長","answer":"正副で検討させていただきまして、正しい評価を持ったデータというところで、検討をさせていただきたいと思います。","id":"exchange-052"},{"speaker":"あべ委員","kind":"意見","question":"そういった意味では、私立に強く偏差するというのは当然のことであります。そういったことからも、資料を選んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-04","title":"平塚シルバーセンター跡の施設整備","agenda":"平塚シルバーセンター跡の施設整備","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"多世代交流施設とは違うということなのでしょうか。延べ床面積だと５００平米あるということで、解消に向けて検討はされたのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"施設の性格づけにつきましては、今後、検討していきたいと考えております。検討しました結果、在宅支援の観点からも重要というふうに考えて、在宅支援施設のほうを選択したものです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"ご説明があった私立園でも４００平米ぐらいでやっているところがありますけれども、これは上下に分かれているから無理だということなのでしょうか。伺いたいと思います。","respondent":"竹田保育課長","answer":"１階は高齢者、２階は子育て支援施設ということなので、それぞれの世代が定期的に交流するような機会も設けていきたいと考えております。仮に２階に小規模のものを入れるということも、そちらに移転して、施設の魅力を増していきたいと考えているところです。","id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"確認","question":"もう一回、確認したいのですけれども、さっきの保育課長のご説明だと、荏原保健センターの和室ルームが移転するとおっしゃったのですが、保健センターのオアシスルームが移転するのか尋ねました。","respondent":"竹田保育課長","answer":"荏原保健センター内にあるポップンルームを移設しまして、もう少し広い面積でポップンルームとオアシスルームの両方を持った施設にしたいと思います。ポップンルームであいたスペースをオアシスルームにしまして、定員を拡大していきたいと考えております。","id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これは要するに、子育てしているご両親はいなくて、お子さんをオアシスルームのスタッフが預かるという形になるのですか。お母さん、それからお子さんが来て、そこでスタッフと自由に遊ばせるという形態ということで理解してよろしいか尋ねました。","respondent":"竹田保育課長","answer":"委員ご指摘のとおりです。オアシスルームは１時間単位でお預かりして、保護者同士の交流等を通して、地域交流に役立てていきたいという施設です。","id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"意見","question":"こういう形で、在宅の子育てしているご両親を支援する。こういう施設を開設するということが非常に大切なことだと思うので、これに関しては非常に高く評価していますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問・要望","question":"オアシスルームは非常に要望が強いもので、今回は増設ということになると思いますので、関連したいと思います。それから、荏原保健センターではどのくらい定員を増やす予定なのかということをまず説明を求めました。","respondent":"竹田保育課長","answer":"まだ基本設計等が始まっていない段階なので、確実なことは申し上げられないのですが、新設のこちらの施設については、定員１２名を考えております。それから、荏原保健センター内も定員は１０人ですので、２人増員して、１２人ということで考えております。","id":"exchange-059"},{"speaker":"あべ委員","kind":"確認","question":"週に何回だったという気もするのですけれども、確認をさせてください。その辺のイメージを教えてほしいと求めました。","respondent":"竹田保育課長","answer":"小さなイベント等、あるいは講習会等を企画しまして、地域の方にご参加いただくという２つの側面があろうかと思います。それから、ポップンルームの開催ですが、基本的にお休みを除く毎日です。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"この平塚２丁目の場所が家庭あんしんセンターと非常に隣接していたと思います。それはそれとして、子どもが利用できる新しい施設と平塚の家庭あんしんセンターが何らか意見するなり協力するなりということはあるのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"家庭あんしんセンターの利用なのですけれども、ＤＶとかの関係もある関係で、あまり場所を広くＰＲしていないというところがあろうかと思います。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"在宅支援でとても求められているということで、２カ所に増えて、とても喜ばしいことだと思います。申し込んでもなかなかあきがないという声も聞いているので、その辺をお聞かせいただきたいのと、ポップンルームは区内に何カ所あるのか尋ねました。","respondent":"竹田保育課長","answer":"平塚シルバーセンター跡地を入れれば１０カ所という形になります。先ほど申し上げた７月１日の北品川第二保育園で１カ所できますので、そこを１カ所と、荏原保健センター内にあるもので２カ所という形になります。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子育ての要望、どういう支援が必要かとか、いろいろ意見を聞かれる場所にしていただけたらと思います。その点だけ心配だったのです。","respondent":"竹田保育課長","answer":"まだ基本設計前の段階ですので、明確には申し上げられませんが、そういうことも踏まえて考えていきたいと考えています。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"児童センターなどは、結構、お母さんがお子さんを連れて、荷物を持って、上まで階段を上がるのが大変ということで、妊婦もいらっしゃるので、ぜひエレベーターをきちんとつけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-05","title":"平成２９年度新入学者の取扱い","agenda":"平成２９年度新入学者の取扱い","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"小山小学校は前回と同じ９６名となると、９０名だった場合は、３クラスにしたりとかということはあるのか尋ねました。","respondent":"有馬学務課長","answer":"その結果として、平成２８年４月では、城南小学校は３クラス、小山小学校は３クラスという結果になりました。区域外の児童数がこの人数を超えた場合はしっかりと対応して、受け入れをしていきたいというふうになっております。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、そういった対応で、狭いスペースで勉学に励むということがないようにしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今日の議論の中でもいろいろ出されましたけれども、ぜひ、意見を聞いて、わかりやすい資料を出してほしいと求めました。","respondent":"あくつ委員長","answer":"午前中も申し述べさせていただきましたとおり、本日はご意見として賜りましたので、今後、実施していくにあたり、必要に応じて正副委員長または理事者と協議をしてまいります。","id":"exchange-067"},{"speaker":"あべ委員","kind":"意見","question":"もし、今の気持ちが伝われば、何か余裕があれば、修正案など出してほしいと求めました。お任せしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"調査項目が決まってから探そうと思っていたので、本日は案を持ってきていません。いつも一生懸命探して提案しても、ここに入らなくて、すぐ没になったりして、今日は持ち寄っていないので、お時間をほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"意見","question":"先進的な在宅子育て支援をしているような施設とかシステムを見たいです。それと、あとは保育園のあり方というので、いろいろな形態の保育園とかをもしも視察に入れていいのだったら、その見学もしたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"あべ委員","kind":"意見","question":"片道１時間ぐらいのところは、そこは何とかならないかと１０年間、なかなか何とかならない。そういった近隣都市の実情を見にいく仕組みもあわせて機会がとれればとは思っておりますとの意見を述べました。","respondent":"あくつ委員長","answer":"私ども、正副委員長でも、そのようなことは今、検討しているところではあります。今回は行政視察ということで、委員会の中でもご意見が出ていたと思うのです。","id":"exchange-071"},{"speaker":"あべ委員","kind":"質問・要望","question":"所管事務調査の項目にしっかり沿ってというのも理屈に合いますし、そうでないものも１つぐらい入っていいのではないかという考え方もあると思います。自殺予防で言えば、例えば名古屋市なども、前回のときには書かせていただきましたので、もし可能であれば名古屋市を入れてほしいと求めました。","respondent":"あくつ委員長","answer":"先方の受け入れ状況にもよりますし、全て所管事務調査の項目に沿ってやらなければいけないということではありませんので、なるべく検討して、考えたいと思います。","id":"exchange-072"},{"speaker":"新妻委員","kind":"提案","question":"具体的に、山口県光市のコミュニティ・スクール、あさなえネットの取り組みが非常にいいということで、どうかというところを提案します。発達障害というところで、今、進めている愛媛県四国中央市の発達支援センターもどうかと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問","question":"行政とここが組んだのは初めてだと伺っています。これもまた北九州市、政令市が多いのですけれども、早期特別支援教育などはそこを見にいきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"意見","question":"去年、行った視察が山口県下関市のコミュニティ・スクールと、それから北九州市と、あと保育士募集の佐賀市だったので、去年行ったメンバーが何人かいるので、できたら新しいところで勉強したいという希望がありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"あべ委員","kind":"意見","question":"１つのまち、品川区の視察が３カ所も、あれはどうかと思います。横の調整も、若干とっていただけるといいとは思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"}]},{"id":"topic-08","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"事実の把握をしっかりしてほしいということで、調査委員会の設置を求めましたが、その辺の評価をお伺いしたいのが１点です。質問の中では、地域を挙げて取り組むことを求めます」という設問だったのですが、今後について。","respondent":"竹田保育課長、熊谷指導課長、村尾教育総合支援センター長","answer":"３万円から５万円に上がったこと、それから２３区内の認可保育園での賃金状況では遜色がないとのご答弁に対する根拠についてご説明いたします。… 警察からも事件性はないとの報告を受けております。保護者もそれを求めておりませんので、調査委員会等を設けるなど… 教職員についてですけれども、これも先日ご説明いたしましたとおり、ゲートキーパー研修を先日、生活指導主任を対象に行いました。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問","question":"こういう手が打たれたけれども、お伺いをしたいと思います。受けとめて、何とか消化しようという体制では、子どもたちの育ちにマイナスの状況が生まれてしまうと思うのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"東京都が今回実施したキャリアアップ補助金は、その辺の補助金の趣旨は十分、各施設にお伝えしています。民営化については、今後も着実に検証し、進めていきたいと考えております。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問","question":"学校と地域がつながってほしいと思っているので、同じご答弁をいただいても、そこでとまってはまずいのではないかと思っています。順調に育つのではなくて、そういう……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは誰も否定できないことであると私は思うのです。つながりを深めていっていただきたいと思うのですが、それは学校が中心になっていただきたいと考えていますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"例えば、原因究明の委員会でもつくったときに、教育委員会でそういうことは可能ですか。そんなことができるものか尋ねました。","respondent":"熊谷指導課長","answer":"今、副委員長のお話のとおり、ご遺族のご意向というのが一番大事な部分でありますので、それなしで調査委員会を設けるということは不可能です。","id":"exchange-081"},{"speaker":"沢田副委員長","kind":"質問","question":"そういう人たちはそれでいいのですかということなのです。それだけはしっかりきちんと考えていただかないといけないのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"意見","question":"「遺族が、また予防につながる調査であることを共通認識にしてほしい」という言葉で背景調査の意義をおっしゃっているのです。私は、静かにさわらないでおくことが解決であるとは思っていないので、この点はお話ししておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２回、２回とも非常に客観的にオーソドックスな、非常にすばらしい講演だったのです。１回、非常にすばらしい試みなのではないかと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からも、２点ほどお伺いしたいと思います。やはり調べてほしいというようなことが、半年後とか１年後とか、そこにしっかりと対応をしてほしいと求めました。","respondent":"竹田保育課長、熊谷指導課長","answer":"具体的な使い道については、しっかり報告を受けまして、現状を把握してまいります。こちらにつきましても、指導検査等の権限の範囲内で現状把握、それから保育の改善に努めてまいりたいと考えております。 今、ご質問がありましたとおり、今後ということで、ご遺族のご意向ですとか、さまざま状況が変わってきたときには、また真剣に配慮しながら、また、子どもたちの心のケアにも努めながらとは考えております。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":53991,"voices":200}},{"id":"h28-20160628-5","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"総務委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと住民基本台帳の追加分ということで９,３４０万５,０００円、そういう中でさらに追加というところは、どうしてなのかを伺いたいと思います。３点目は、幼保一体施設の運営費として１,９００万円ほど補正をかけたのですが、そのあたりのことについて教えてほしいと求めました。","respondent":"秋山財政課長、仁平情報推進課長","answer":"シティプロモーション事業で検討を進めていく中で、平成２８年度中に７０周年事業を実施するということで、今回補正予算を上げさせていただいたです。３番目の区立保育園の民営化につながるものですけれども… 私から、住民基本台帳費の個人番号カードの関係のご質問について、ご説明します。当初、全国的に１,５００万枚ぐらいだろうという見込みで計算しておりましたが、想定より申請数が多く、倍の３,０００万枚ほどになっております。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"この辺はどういうふうに考えたらいいのでしょうか。その辺を伺っておきたいと思います。","respondent":"秋山財政課長","answer":"今回の幼保一体施設の実施設計ですけれども、定員についてというお尋ねだと思います。それが実際に幼保一体施設になったとき、どうなるかというのを、設計の中で検討するというふうに聞いております。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"では、１６０名が入れるような方向で検討するのかどうかというのが、今一つわからなかったので、そこは明確に答えてください。それと住民基本台帳のほうのお答えをお願いしたいと思いますとの意見を述べました。","respondent":"秋山財政課長、仁平情報推進課長","answer":"幼保一体施設の定員については、「設計の中で検討します」というふうに聞いております。そちらのほうの障害だったということで、こちらが解消されまして、今現在は通常どおり動いている状況になってあります。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"事業が単発で行われるのか、今後も継続して考えられているのか、その辺教えてほしいと求めました。今どういう状況になっているのか、この補正の判断をするに当たってもご報告いただきたいと思うのですが、いかがか尋ねました。","respondent":"久保田総務課長、仁平情報推進課長、秋山財政課長","answer":"こちらの補正予算の説明資料には、ラッピングバス運行等ＰＲ経費と書いてあります。それぞれの年代に合わせたものをやっていきたいと考えていますので… こちらは国のほうのシステムですので、今回各自治体のほうに、トラブル回復に要する経費を求められたということはございません。… 宮古市復興支援の親子体験交流事業ですけれども、今回品川区のほうで事業化するということで、補正予算に計上させていただいたです。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"ラッピングの中身、要するに７０周年ということをラッピングして走らせるという趣旨なのでしょうか。その辺の事業の中身がどうなっていくのか説明を求めました。","respondent":"久保田総務課長、秋山財政課長","answer":"ラッピングバスについてですけれども、経費としましては３００万円ほどの見積もりということで、予定しているものです。この議決をいただいた後に、運行経費と合わせた金額が３００万円ということですので… 宮古市の復興支援ですけれども、募集をしたりという実務を進めてきたところがありますので、今回はそちらのほうに引き続き委託という形で進めていくです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"予算で区民の皆さんにもきちっと報告しているわけですが、普通の細かい事業ならあれですが、その辺どうなのでしょうか。その２点について説明を求めました。","respondent":"秋山財政課長","answer":"環境についても考えていただきたいということで、それもあわせて今回７０周年記念事業という形で出させていただきました。環境の考え方を区民の方にわかっていただきたいというミュージカルなので、環境費のほうにつけさせていただいていると、そういう考え方です。","id":"exchange-006"},{"speaker":"大倉委員","kind":"質問・要望","question":"この７０周年に向けて、どういったところでどういうことを考えながらやってきたという、ちょっと教えていただきたいのと。もう既にないものがあるとかという中で、現状どうなっているか、教えてほしいと求めました。","respondent":"久保田総務課長、中元広報広聴課長","answer":"先ほど来、これまで平成２９年度にということで考えていたところですけれども、品川区の歴史というものも知っていただきたいということがあります。７０周年事業というものを大切にして、品川区に対してもう一度考えていただきたい… 広町１の６にあったのですが、あと目黒川の両岸に赤れんが工場というものがあったのですが、そちらもなくなっているというところ。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問","question":"７０周年でポンとやって、６０周年でこんなことをやりましたみたいな、その辺を聞かせてほしいと求めました。今もう６カ所はないということで、その百景の中で表示とかはどうなっているのか、説明を求めました。","respondent":"中元広報広聴課長、久保田総務課長","answer":"写真等多用して、区民の皆様にわかりやすいような形でご紹介をして、気運醸成を図っていきたいと考えているところです。… 先ほどもご説明させていただきましたが、しながわ百景をリニューアルするということが、その一つだと思ってあります。… すみません、答弁漏れがございました。銘板等ですが、なくなった場所につきましては撤去をさせていただいているところです。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"７０周年ということでいろいろな取組みというのが、そういった考え方というのがあるかどうか、最後に。いろいろ質問の中でもあったと思うのですけれど、そういった７０周年だからこそ、その辺の考え方は。","respondent":"久保田総務課長","answer":"やはり品川区全庁挙げて取り組んでいくと考えてございまして、全庁挙げての連携ということで、この間進めてきたきたところです。平成２９年度に向けてといったことも考えられると思いますが、いずれにしましても全庁挙げてこの７０周年の事業に対して取り組んでまいりますので。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"まずやってほしいのは、町会連合会とか、一緒になってやってほしい。それはいろいろな意見を出してくださいというような機会を設けてほしいと思うのですけれど、そこら辺の考え方を教えていただきたいと。","respondent":"久保田総務課長","answer":"７０周年ということで全庁挙げての体制を組んですので、まちの人たちと一緒になって、７０周年へ向けての気運を盛り上げていきたいと考えています。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"５０周年のときは子ども議会とか、お二人は現役で体験されてるかもしれないですけれど、そういうこともあったやに聞いていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ちょっと基本的なことを教えてほしいのですが。今のまさに７０周年記念事業、歳入はまずどこになるのか、ちょっと教えていただきたいのですが。","respondent":"秋山財政課長","answer":"歳入は、２０ページからの歳入で充当事業と書かれてあるものにつきましては、特定財源ということで充当費があります。財源につきましては、多くは２２ページの繰越金、これを財源として、今回補正として出しています。","id":"exchange-012"},{"speaker":"つる副委員長","kind":"確認","question":"先ほど吉田委員からちらっと確認がありましたが、２５ページの７０周年記念事業の補正予算規模なのですが、年度中にというお話があって。当初ずっと６０周年以降の１０年間で、予算規模であるのかどうか、このあたりの感覚を説明するよう求めました。","respondent":"久保田総務課長","answer":"区史を発行するということも、７０周年の一つの節目として考えているところはありますが、そういったことの準備も進めてきたというところです。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問","question":"わかりました。まさにシティプロモーションとの相乗効果と言われている、その相乗効果の部分というのは、どういうふうに考えているのか詳しく説明を求めました。","respondent":"久保田総務課長","answer":"こうした７０周年の機会を契機にとりまして、７０周年は７０周年でやって、「わ！それらを総合的に事業として組み立てて進めていくことで、効果としてさらにプラスアルファで出ていくと思っているところです。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"確認","question":"まさにシティのプロモーションですから、その７０周年も含めて、区内のさまざまなことの発展に寄与させていくかということにつながると思うのです。一定の確認といいますか、その辺の感覚はどういうふうにお持ちか、説明を求めました。","respondent":"久保田総務課長、中元広報広聴課長","answer":"私ども内部の検討ですけれども、パネル展につきましても３月を目標にそれぞれ順番に、年代ごとにやっていくとか。３月１５日に品川区が生まれたということを、皆さんに知っていただくことが… 気運醸成の中で、しながわ百景の募集に関しましてはインターネットの仕組みも使いまして、区外の方も投票できるようなことで計画しております。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"〔「３００万って言ってたじゃない。答弁で」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"３００万円としても、そういうものはもう少し配慮があっていいのではないかと思いますので、意見として申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ７０周年記念事業そのものについては、ちゃんと意義を持って進めるべきだと考えていますし、社会福祉費などもぜひ進めてほしいと求めました。ただ、私たちの政策として、この個人番号カードのことは大変重大なことだと考えていますので、この１点をもって、この補正には反対したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"税金の使い方など今回の問題を教訓にして、やはり真摯に対応していきたいということを、改めて表明しておきたいと思います。それで、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-02","title":"福井県坂井市との連携事業","agenda":"福井県坂井市との連携事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"坂井市のアンテナショップが戸越銀座商店街にということですが、このアンテナショップというのは常設なのですか。シティプロモーションサミットは第４回の開催だというのですが、この間、どのような状況があったのか、過去の状況を説明するよう求めました。","respondent":"柏原企画調整課長、中島企画部副参事","answer":"私のほうから、前段のアンテナショップの関係をお答えします。これから調整と聞いてありますけれども、坂井市のほうから２年間は続けたいというような意向があるというふうには聞いてあります。 その後、平成２６年の相模原市、昨年度は弘前市で開催されました。過去、相模原市で開催されたときは１２３自治体が参加されまして、シティプロモーションに関心が高い自治体が、多く集まるサミットです。","id":"exchange-020"},{"speaker":"南委員","kind":"意見","question":"これを品川区に聞くのも何なんですけれども、地域の繁栄している商店街であることは確かなのですが、どうして品川区なのかというのがちょっと。わかる範囲でいいですけれど、失礼のないような感じで聞きたいと思うのですがとの意見を述べました。","respondent":"柏原企画調整課長","answer":"連携を始めたということで、物販を品川区内で行いたいということで、物販をしたという経緯があります。やはり連携を始めたということで、ぜひこちらでオープンさせていただきたいということで、品川区内での店舗を探したという経緯があるというものです。","id":"exchange-021"}]},{"id":"topic-03","title":"冨士見台中学校外壁改修その他工事請負契約","agenda":"冨士見台中学校外壁改修その他工事請負契約","exchanges":[{"speaker":"南委員","kind":"意見","question":"そうでない部分というのは大丈夫だという認識でこういうふうになっているのかと思うのですけれど、一般的に外壁とか建具は同じような年数がたっているので一緒に工事をするのではないかと思っていたのですけれど、その辺はどうなってこうなっているのかとの意見を述べました。","respondent":"小林施設整備課長","answer":"この工事ですけれども、夏休み期間で進めていくということを聞いているのですけれども、その関係で全面の外壁を一気にやりますと、当然足場を外す時期とか遅くなりますので、計画的に工事を進めるために、範囲を区切ったということだと思います。","id":"exchange-022"},{"speaker":"南委員","kind":"確認","question":"そうすると、当然必要性はあるけれども、そういう工事期間の関係で一部にとどめたということですから、その他の必要な部分はまた計画的にというと、来年の夏になるのかわからないですけれど、そうやってやっていく予定はあると、そういうことで確認していいか尋ねました。","respondent":"小林施設整備課長","answer":"教育委員会のほうで進めているものですけれども、多分そういうものだと考えています。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"これは今までどういうふうになっていて、今それがどういう必要性が出てきて、こういう工事になったかということ。どういうことでこれを新設するのか、基本的なことなのですけれど、この工事の内容について説明を求めました。","respondent":"小林施設整備課長","answer":"私のわかる範囲でお答えしますけれども、太陽光発電を設置するときには、床のスラブにアンカーというものを打ちます。フェンスも、太陽光発電の周りに人が行かないように、覆いをするような形でフェンスをつくるものだと考えられます。","id":"exchange-024"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"私はこの３点を言ったのですけれども、そういうものが必要なのではないかと思っていただけに、そのような発言を聞いて心強く思ったのですけれど。ぜひ、これは取り上げていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"提案","question":"実際に競馬事業というのが２３区の中でどういう位置づけで行われていて、まだまだわからないことも結構あるのだなということを肌で感じました。これは一回、委員会としてもしっかり勉強したほうがいいのではないかと思いまして、提案させていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"大倉委員","kind":"意見","question":"現状、品川区も相当頑張ってやっていると思うのですが、さらに研究したほうがいいと思って挙げさせていただきました。２０２０年のオリンピック・パラリンピックに向けてもしっかりと品川の魅力を発信していく、項目に挙げさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"子ども議会のこともちらっと伺いましたし、１８歳で選挙ができるということではなく、そういうことを考えるのもいいかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと質問いいですか。いろいろな人を呼んで、所管をまたぐようなことをするべきではないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"意見","question":"ぜひ２項目、２テーマというところにコンプリートしないで、いろいろなところを出して研究して行ければいいかと思っているので。お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"恐らく何度説明されてもわかりにくいのではないかと思うので、これ１本だけでほとんど終わる状態なのかなと。大都市問題ですか、さまざまな問題が起きると思うのですが、そういう将来を見据えた議論ができる場があるといいなと思います。","respondent":"松澤委員長","answer":"このいただいた意見をもとにして、正副で再度調整し、次回７月２６日の委員会でお示し、決定していきたいと思いますが、よろしいでしょうか。","id":"exchange-031"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"大倉委員","kind":"意見","question":"さっきも申しましたが、全国シティプロモーションサミット、これを見に行くのも一ついいのかなと思ってはいるのですが。なので、坂井市にとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なおかつ、返礼品でお米を出しているのが、もう７月ごろに足りなくなってしまった。品川区も今はマイナス５億円ではないかと言っているぐらいですから、どういう対策をしているかというのも、すごく参考になるのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"遠方に行って、そこに行けば必ず言われることは、「何で品川区さんが来るんですか」と。だからあまり２泊３日とかこだわらないで、品川区のそばの周りで地域の自治体に、私は勉強に行くべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"私も委員長と一緒に３０年近く、毎年毎年２泊３日で行っていますけれど、そういう体験を通じて、やはりちょっとなと思うところは多々ありましたよね。ですから、２泊３日という日程にこだわらず組んでいったほうがいいのかなと思います。","respondent":"松澤委員長","answer":"行政視察は毎年第３回定例会後に実施しておりますけれども、今回同様にして行きたいと思います。は１０月３１日から１１月２日、いずれかの２泊３日を念頭に、考えております。","id":"exchange-035"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問","question":"どうなのでしょうか、みたいな議論というのは、正副のところでどういうふうに行われたのか。その辺についてどうなのか、経過を説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"南委員","kind":"提案","question":"そういうご意見で、委員長としては視察に行きたいというご提案があったということですけれど、それを決める前に意見を諮っていただきたかったと思うのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":37819,"voices":137}},{"id":"h28-20160628-10","meetingId":"h28-cm06","date":"2016年6月28日","dateIso":"2016-06-28","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時４０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"別に、委員会運営に支障がなければ、こちらは柔軟に対応してもいいのかなというふうに思います。その判断は、委員長が仕切るでしょうから、それに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"リオオリンピック視察・調査への議員派遣の件ですけれども、議会でぜひ再考していただき、中止を求めたいと思います。ぜひ、議運の場というか、議論の場を設けていただいて、ぜひ、中止の再考をしてほしいと求めました。","respondent":"鈴木（真）委員長","answer":"ご意見いただきました。既に派遣が決定し、議決もとっている案件ですので、検討するということで、検討します。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問・要望","question":"私どもの会派も、ぜひ検討して、検討すべきではないかと。区議会が行くというのは、ちょっと何か間違っているのではないかと思いますので、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":3200,"voices":22}},{"id":"h28-20160629-14","meetingId":"h28-cm06","date":"2016年6月29日","dateIso":"2016-06-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ４時１７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件整理しています。","topics":[{"id":"topic-01","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そこで働く労働者の賃金水準や、正規・非正規など、雇用形態はどう反映される数字なのか、お伺いします。単身者の若い人が増えているということなのか、その辺について、ちょっとお伺いします。","respondent":"柏原企画調整課長","answer":"どういう形が一番効果的なのかというふうに、今、検討しています。細かい説明というのが難しい部分がありますけれども、数値として、あくまで数値として出せるというところのものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"その転入の中の２０代、２０歳から２９歳の単身者がかなり多いということではないということなのでしょうかね。売上が伸びて、税金を納めているのが高いとなると、この付加価値額は上がるということをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"４９ページと５１ページの表ですけれども、２０歳から３９歳の単身の世帯の出入りが多いかというのは、ちょっとこれだけでは比較はできないのですが。２０歳代、３０歳代の単身の転入・転出の場合は、推測はできるです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"合わせていかがでしょうか。できないという現実がある中で、何を望んで、何を区に望んでいるのかというのは、ちょっとお伺いしたので、説明するよう求めました。","respondent":"柏原企画調整課長","answer":"区のほうで総合実施計画であったり、ここは施策というのを挙げさせていただいて、それに対しての目標をどうするのだということを挙げしています。７５ページは、理想の子どもの数を実現するのが難しい理由、これもこういった形で、幾つかの理由が出ています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"まさに合致した、必要な充実だと思うのですけれども、その点はいかがでしょうか。これは要望です。","respondent":"柏原企画調整課長","answer":"１４ページのところに、待機児童対策の解消に向けてということで、項目を挙げさせていただいてあります。例えば認可保育園等の開設・運営支援というのは、施策は進めているというものですので、区としては捉えているというものです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"認可保育園を希望しながら入れなかった方が１,０００人近くいたというところで、６１ページですか、随分先ですね。この、年少人口の将来推計値との関係で、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"これは保育園だけではありませんけれども、施設が必要なのではないか。所管のほうでも努力をしていますので、この人口ビジョンとかけ離れた形で施策を行っているものではないというふうに考えてあります。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"その前提に立って、幾つかお考えを伺いたいところです。実際に数字を見ていると、０から４歳ですか、この人口というのはむしろ転出が増えている。","respondent":"柏原企画調整課長","answer":"平成２６年も平成２１年も、特に０から４歳のところは、減っていると。ただ、分析については、やはりもう少し深く入ったところの分析というのは、必要だというのは認識しています。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"それに合わせて、区として公共施設の再配置を見直すという、そういう考え方に立っているということでよろしいのでしょうか。それについて、お考えを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"需要に対する供給の考え方というのは、当然検討しなくてはいけないというふうには思ってありますけれども、そういったところも含めながら。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"松澤委員ともよく話すのですけれども、例えば旧荏原第四中学校であれば、周りに戸越小学校や宮前小学校に大原小学校ですか。しっかり考えるのにいいタイミングなのではないかと思うのですが、例えばその辺、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"土地につきましては、そういった視点も当然踏まえながら、検討しなくてはいけないだろうというふうに思ってあります。これは当然必要だというふうに思ってありますので、そういうトータルなところで考えながら、進めていくことになるというふうに思います。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこからまた使えるわけですから、ハード整備はそのような形も含めてやっていただきたいというのは、思っています。どういうものなのか尋ねました。","respondent":"柏原企画調整課長","answer":"総合実施計画であったり、総合戦略と読みかえても構わないというような言い方も、国はしています。長期基本計画は長期基本計画と別立てで考えて、改訂、見直しというのはかけていきたいというふうに思ってあります。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問・要望","question":"１年間に。その長期基本計画の中でも結構ですから、このようなものでニーズの把握というのはし続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"何点かお伺いしたいのですが。まず、もう１回お話を、説明を受けたい。","respondent":"柏原企画調整課長","answer":"こういった施策を進めることによって、不可能ではない数字であろうということで、定めさせていただいたところです。全体的な底上げを、企業全体として１０％上げたいということでつくったというのが、この目標値になってあります。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"こういうものを押し上げていこうと、支えていこうという、ブレークダウンの言い方が１つあるのかなと思うのです。もう１回持たせていただきたいので、その１０％上げて４兆３,０００億円にするという、どういった内容だったのか尋ねました。","respondent":"柏原企画調整課長","answer":"全体的な活力を上げるとか活性化というところを考えたときに、企業のという、全体の数字に持ち上げたということです。頑張っていただくという支援はするのですけれども、活性化につながるような施策をやることによって、相対として。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"１つは、もう１つの大きな要素として、転入超過ですかね。この、なぜ転出超過になったのかというのは、何か分析は、されていたら説明を求めました。","respondent":"柏原企画調整課長","answer":"地価にそれが影響を与えたというところで、この転出が多くなったという時期が、この時期に当たっていると思ってあります。分析としますと、この時期のその動きというのは、バブル期における経済の影響が大きかったというふうに思ってあります。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"東京２３区も含めて、地価の高騰ということが、品川だけの問題ではなかったはずですよね。他の２３区も、もう少し何かあってもいいのかなという思いで、ちょっともう１回お聞きしたい。","respondent":"柏原企画調整課長","answer":"２３区で出ているのが多いかといいますと、今、最も多いという状況があります。品川区に入っていただけるかというのは、こういったところの分析も踏まえながら、施策としての検討はしなくてはいけないというふうに思ってあります。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"４年という中で、どれですかと聞くと、またたくさんありますということになるかもしれませんけれども。それでまたＰＤＣＡのほうに反映をさせていきますというような考え方はどうなのか尋ねました。","respondent":"柏原企画調整課長","answer":"課題として認識があるところですので、そういった部分については、研究はさらにしなくてはいけないというふうには思ってあります。では効果的なのかという、課題の研究と合わせて、ＰＤＣＡをしながら事業展開を検討していくという流れになってくると思います。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"ちょっと１つ確認をさせていただきたいのですが。この５年間、平成３１年度までのこの目標の中で、どんなものがあるのか尋ねました。","respondent":"柏原企画調整課長","answer":"一言で言うのはなかなか難しい面があります。今後どう考えていくのだというのは、ビジョンというとちょっとあれかもしれませんが、考え方みたいなものをちょっと検討しながら出していくという。","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"このオリ・パラの開催というのが、１つは大きなものになるかと思うのです。皆さんに来ていただきやすいようなまちづくりとか、また交通の便ですとかも、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"１１万人が１４万人ということで、目標３万人ということで、若干増えていくということで。そのうちの外国人は３万人ぐらい増やしていきたいということで、一般の、そのあたりのお考えを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"基本目標３番目のところの、考え方につきましては、来訪していただきたいと。要因とすると、そういうところはありますけれども、考え方としては、委員がおっしゃっていただいたような考え方で、目標は出しているものです。","id":"exchange-018"},{"speaker":"沢田委員","kind":"意見","question":"もうほとんどいっぱい、９割以上の稼働率だという話も、以前もありましたけれども。今、この先、ホテルとかが増えていくという見通しがあるのかというのもあると思うのですけれども、その辺のところのお考えを説明するよう求めました。","respondent":"柏原企画調整課長","answer":"この数値につきましては、そういったところも含めながらというふうに捉えております。こういった人たちがたくさん来訪してもらえるための方策として、各方面に働きかけといいますか、話をしていきたいというふうには思っています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域のほうからも、３度目はやめてほしいという声もありますので、そういったことも検討に含めてやっていっていだきたいと思います。良くなってほしい点でいきましても、２番目に、説明するよう求めました。","respondent":"柏原企画調整課長","answer":"施設についての総合的な検証・検討が必要だというふうに思ってありますので、これからもそういった形で進めていきたいというふうに思ってあります。結果的に、こういうことが出ていますけれども、複数回答というところは、１つ考えなくてはいけないだろうです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"１番と２番のところで来ているものですので、出生率１.４５に上げていくということを考えても、どういった施策。今後、総合的に判断していくことですけれども、その経済的負担の軽減を含めてやっていくという理解でよろしいのか尋ねました。","respondent":"柏原企画調整課長","answer":"それから、こういった施策、こういったご意見があるというのは、重々、このアンケートの結果からも出ているというところは認識をするところです。そういったところを総合的に見ながら、区が、どういった形で施策を打てるかを検討して、施策を打っていくというものです。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"例えば、人口１万人当たりの各公共施設数がどういう状況にあるのかというものが、かなり現状がわかりやすいかなと思ったのです。もし出していただけるといいなと思って、これは委員長、副委員長にお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"区長がその課題についていろいろ質問されたということで、もう一度ちょっと改めて、そこのところだけ確認をさせてほしいと求めました。区長が質問されたことに対しての、国交省側のお答えのほうを確認したいと求めました。","respondent":"三ツ橋環境課長","answer":"７月なのか８月なのかという、はっきりした、本当に明確なことは答えておりません。そちらが実情です。","id":"exchange-023"},{"speaker":"沢田委員","kind":"意見","question":"いまだに環境影響についてはなかなかわからないという、まだ明確な答弁がないということだと思うのですけれども。説明会をちゃんとやってほしい、なかなか判断できる情報が少ないのではないかなと思うのですけれども、そのあたりのお考えを説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"その中では、環境に配慮した方策の方向性という文言で出されておりまして、検討の方向性というものが３つ出されております。落下物につきましても、落下物には、具体的に対応していくということを書いてあります。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長がそこにいたのか、何を求めたのかというのがわからなかったのですけれども、もう少し詳しく説明していただきたいのですが。その辺もちょっとわからない説明だったので、そこをまず教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"こういう意見が区民から来ておりますよということを、区長が伝えたものです。説明会の方法について、また環境に配慮した方策についてなど、具体的にどうなっているのかということを聞いております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"これがどんなものかを見て、この環境影響に配慮した方策の策定というのは、これは新ルート案の決定ということなのではないのですかね。何なのかというのをお伺いしたいのですけれども。","respondent":"三ツ橋環境課長","answer":"今現在、「羽田空港のこれから」というこの書類の中によりますと、具体的な方策の検討の方向性というものはあります。先ほど言いました３点ですけれども、検討の方向性はこういう方向性があるんですよと、国が言っているところでございまして。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"国が計画を、案をとって決定するということの宣言だと思うのですけれども、それはどうなのでしょうか。間違いなのか尋ねました。","respondent":"三ツ橋環境課長","answer":"しかしながら、恐らく委員がおっしゃいましたように、こういうルート案ですよということが出されるのではないかと。そういうふうに想定されるものです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"相当な騒音被害だった、公害だというぐらいに品川区が言っているわけですから、当然、大変なところを飛んでいたと思うのですが。その頻度は１日にどれくらいで、何時ぐらいを飛んでいたのかというのを、ちょっとわかれば教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"書いてはいないのですけれども、旧Ｃの真下あたりに旧Ａがございまして、こちらを離着陸していたものです。ちょっと想定していただける範囲で、旧Ｃと旧Ａと旧Ｂがございまして、そこから離着陸というものです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"提案","question":"この新ルートを提案してきたのに、なぜ今、ちょっとわからない。それよりも、この経済効果というのは大きいメリットだと考えていらっしゃるのか、伺いますとの意見を述べました。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"新Ａと一番下の部分がオレンジ色の部分が旧Ｃになるのですけれども、そのあたりの左側の部分ですので、大田区に近いあたりと想定していただければと思います。幾らの増産が見込めて、そういうメリットの面として発表されているという意図が、非常に明らかであるというふうに考えております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"比べるものではないということで、一般質問の本会議での答弁もありましたけれども、そこは私たちもそうだと思うのですね。だからこそ、区は、踏み込んで、この計画に対しては、正面から撤回を求めるべきだと思うのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"国に、今までも申し上げて、そしてその対応を求めてきたところです。まずはそれを注視するべきという、そういった姿勢は、今までと変わりはございません。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"それも今後、この時間帯に開催できるかどうかということもありますので、品川区にとってはマイナスでしかないのですけれども。出していただきたいということを、ぜひともお願いをしていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"広い範囲で捉えれば７０５万人というものの数字から推計はできるけれども、品川区だとか、これは計測するのが非常に難しいです。国に対しては、品川区としてのメリットというものがどのくらいあるのかというのは、これは求めてまいりたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"この中で、一体どういう議論がなされているのかということは、品川区民にとっても非常に関心のあることだと考えています。国に対して要望されたということなので、国に対して求めていっていただきたいと思うのですけれども、それについて区はどうお考えなのか尋ねました。","respondent":"三ツ橋環境課長","answer":"昭和３５年から、ずっと開催しているもので、この時代というのは情報公開の云々がなかったようなのです。ちょっと調整はしていきたいと思いますので、例えばどのような形で公表するのかどうかも含めて、調整していきたいと思います。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"区長や品川区、しっかりと国に対して、要望を出していただきたいと。しっかりと主張をしていただきたいと考えておりますけれども、その点について、いかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"区が反対というところにつきましては、先ほどの繰り返しになりますけれども、まず、国の対応について注視するです。反対というところではなくて、この夏の環境影響に配慮した方策、これをまず注視する必要があるというふうに考えてあります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"及び品川区民の安全・安心を守るべき自治体としての品川区は、より積極的に、国に対して区民の要望をしっかりと伝えていただきたいと考えております。その点について、いかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"ずっと、品川区に対してデメリットをなるべく少なくするような方策について、可能な限り検討していただきたいということを申し述べてまいりました。まず策定を、継続した上での回答ということになるかと思いますので、それを注視するというふうに考えてあります。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"あまりにも品川区民の生命、安全を害するようなものでしたら、積極的に反対をしていただきたいと考えております。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"あべ委員","kind":"提案","question":"合わせてというか、打診がされていたと、提案がされていたと思いますし。これは、聞いてストレートに出てくるかわかりませんけれども、どのようにお考えか、まず説明を求めました。","respondent":"三ツ橋環境課長","answer":"今回、平成１２年のこの海上ルートを導入したころの記録などを、具体的に、あれば、ちょっと確認はしたいと考えていますけれども。やはりノウハウは、過去の経緯も含めて考えなければいけないとは思っておりますので、可能な限り確認はしてまいりたいと考えています。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"勉強会ですとか、そういったものをきちんと設けて、利害をともにすると言ったらいいのでしょうか。共通の対策を考えていくというやり方もあるのではないかと思いますので、ぜひ検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"２０２０年までにどうなるかはわかりませんけれども、計測値は、そういった状況の中での計測だというふうに認識しております。これは経済波及効果に対するデメリットという考え方だとしますと、生産等の増加が見込まれたとしても… 誠意を持って対応してもらいたいと思いますので。４区で勉強会は実施しておりまして、その勉強会が実施しておりませんので、また連携を図りながら実施していきたいと思います。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"別に、訪日外国人が来たことのデメリットというよりも、その新ルートそのものに対するデメリットを網羅的にまとめてということを求めたいと思います。以上、２点、もう１回ご答弁をお願いします。","respondent":"三ツ橋環境課長","answer":"実施するに当たって、いろいろ検討していかなければいけないものがたくさんあると思いますので、慎重に検討していきたいと考えています。この４区連絡会につきましては、各区と調整しながら進めていきたいと考えています。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"私ども、この２年間、会派としても、何度も国交省の担当の方とお話をさせていただいたり、いろいろな要望を出させていただきましたけれども。国交省の考え方についても求めていきたいと思いますけれども、区のほうでも、さらに進んだ対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"昭和５１年の広報には、航空機公害の被害について、意識調査も行っています。これは、区民の住環境の悪化になると思うのですが、どうか尋ねました。","respondent":"三ツ橋環境課長","answer":"したがいまして、国は、実際に、このような防音対策の地域としては含まれていないというふうに言っております。国が国の責任をもって考えなければならないと考えていますので、この住民への影響という部分につきましては、法律範囲外と考えております。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"住民の影響について、法律外だということなのですけれども。法律がどうこうということではなくて、もう一度、答弁お願いします。","respondent":"三ツ橋環境課長","answer":"十分徹底してもらわなければいけないと考えていますので、全く法律範囲外だからといって、全く騒音影響がないというふうには考えておりません。実際に、どのようにしてもらえばいいのか、防音対策の範囲外であっても、何らかの対策をとってもらいたいと思っているのが実情です。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"何らかの対策をやってもらうということで、ぜひそれは求めていってほしいと求めましたが。撤回を求める声もあったということですけれども、撤回を求めていってほしいと求めましたが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"撤回を求めることにつきましては、また、先ほどの繰り返しになりますけれども、この環境影響に配慮した方策につきまして、国の方策を注視するです。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこの、今、計画段階のところで、一番影響を受ける品川区が、この計画をやめてほしいと、しっかり国に求めていくことが必要だと思います。年間４４万回ということで、計画撤回を求めていってほしいと求めましたが、改めて伺います。","respondent":"中村都市計画課長","answer":"この夏までの国の方策、これは待つということではなくて、その方策の中に、可能な限り、品川区に対してデメリットが少なくなるようなそういった検討をお願いをしていますので、まずはやはりそれを見てからということになるかと思います。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"待つわけではないということで、今回の、夏の環境方策を出されることについても、決定が出されるのではないかと想定されるということでしたので、ぜひ、決まる前から、計画撤回していく立場で、区民の命を守るために、頑張っていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"安藤委員","kind":"提案","question":"こんな計画はほかにあるのですかと質問したのですが、ニューヨークのラガーディア空港、大阪伊丹空港や福岡空港などを挙げておりました。脚下げは高度何メートルぐらいのところ、もっと言えば、着陸手前何メートルぐらいで行うのか、今回のルートではどの辺になるのか、伺いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"ただ、その脚下げの位置についても、これは、国としても、その辺は情報としては明らかにしていきたいとは言っております。現時点では、まだ明らかにされておりません。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"そういうことですから、認識を持つべきだし、本当に許されないことだと言わざるを得ないと思います。だから中止しかないと思うのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"そういった説明にはなりませんけれども、国のほうからは、どうやら違うという結論がおおむね出ているというような説明もございましたけれども。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう今すぐでも明らかにするように、早急に求めてほしいと求めましたけれども、この点が何かありましたらということが１点です。防音工事の対象工事の拡大を求めたという答弁をしていたと思うのですけれども、区長が一体何を求めたのか、お聞かせ願いたいと思います。","respondent":"中村都市計画課長","answer":"航空機が通過する飛行経路下におきまして、建物に対する防音の措置を、国に要望したところです。要求のところでは、全ての建物について、そういった措置をお願いをしています。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"今やるべきことというのは、求めることではないかと思うのですけれども、いかがでしょうかね。条件闘争なのか尋ねました。","respondent":"中村都市計画課長","answer":"具体的に検討するように要望したもので、賛成あるいは容認したということではなくて、方策を出すという前提に基づいて発言したものです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"仮に、それが、区が言うとおり、区長が言うとおり、国がのみますということになって、環境方策が出たら、品川区は、自分たちの要求が通った。その上で、環境影響に配慮した方策が策定されたということで、賛成するということなのか尋ねました。","respondent":"中村都市計画課長","answer":"この環境に配慮した方策は、防音や安全だとか、方針を項目として出て、具体的なものは何一つないです。したがいまして、国から、具体的なものが出たとしますと、そこから、区としてどうするかというのが始まっていくのかなというふうに考えてあります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"提案","question":"今やるべきことは、計画撤回をということを強く求めていくということだと思いますし、そのような立場で臨んでいただきたいというふうに思います。質問したいのは、どうして品川区は、私たちの質問に対して、このような考えが示されていないと言えるのか尋ねました。","respondent":"中村都市計画課長","answer":"国からの説明です。これは、２０２０年以降にそういった要求をするのではなくて、もう既に現在からそういった要求をしていくべきだというふうに考えております。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"ですから、将来の新滑走路プラスさらなる増便ということと直結していることだと、私は思います。今回の新ルートを許せば、さらなる増便の道を開くことになるという認識を持つべきだと思いますが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"国からの説明では、最初の配慮が全く意味をなさないものになってしまうというふうに考えますので、引き続き申し入れてまいりますし。これは、国としてその約束を守るということは当然のことだというふうに考えております。","id":"exchange-051"},{"speaker":"松澤委員","kind":"質問","question":"安藤委員に聞いていいですか。安藤委員が脚下げの位置がどうのこうのと言っていたのですけれども、安藤委員、説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"安藤委員","kind":"意見","question":"より正確に知る上で、とても大切な情報だと、私は思います。それがわかるということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"安藤委員は熱心ですから、あるいは、開いたらこれを航空会社が地元に説明しているとかという答弁を聞いてきたと思うのですね。その結果をちょっと示すよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"安藤委員","kind":"意見","question":"重要なのが、成田です。それは、やはり、危険性を認識しているからだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問・要望","question":"こういう質問をされるのでは、何か審議できないなと思っているのですよ。しっかりと根拠を持った質問をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"あべ委員","kind":"意見","question":"氷だけで１３。そのときの１本１本の状況によって、大体５００メートル程度が目安というのも妥当なラインではないかと、私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"ただそれを、何メートルで下げるのだ、言えないのか、という質問というのは、聞いていて、聞き苦しい。私は、ただ不安をあおっているだけの質問だな、嫌な質問だなと思って聞いていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"請願にもありますけれども、着陸前の８分間が一番危険であるいうことが言われておりますけれども、この８分間というのは、品川区の上空を飛行しているということでいいのか、改めてなのですが、ちょっと確認させてほしいと求めました。","respondent":"中村都市計画課長","answer":"８分あれば、そして着陸するのに８分はかからないと思いますので、この８分以内の中には当然入るというふうに考えてあります。精神状態、引き続きそういったものを行っていっていただきたいということは、継続して申し入れてまいります。","id":"exchange-059"},{"speaker":"のだて委員","kind":"意見","question":"品川区上空が８分のうちに入っているということで、やはり一番墜落事故の危険性も高い時間帯ということで、やはり墜落の危険性も書かれていましたけれども、免れないということになると思いますので、この計画、ぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"これまでの前５本も含めて、継続ということで、同じ扱いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"安藤委員","kind":"意見","question":"会の方から、採択してほしいということで、熱意あふれる手紙も届いております。こういった区民の声に応える必要もあると思いますので、私は、結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"あべ委員","kind":"意見","question":"その上で、今期、このメンバーでの行革委員会が、今回第１回ということもありまして、今回継続をお願いしたいと思います。ただ、これが、国の事業であるということを鑑みますと、議会として、また他にいろいろ何かできることはないかということは考えているところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"意見","question":"我々としては、国土交通省の環境方策がこの夏ということ、迫っているということでもありますし、請願内容も妥当だと考えますので、我々はまず反対という前提を鑑みれば、この場において結論を出すべきと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"渡部委員","kind":"提案","question":"意見書を、やはり会派で必要に感じたところが、やはりその提案をしてきて、当然その案文をお示しいただいて、それについて審議を諮っていくべきもの。ですから、どういうふうにやっていくのかと、なかったことにしましょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"改めてこのタイミングで、議会として意見書を出していくというあべ委員の提案というのは、私は大事な点ではないかと思います。そういった手続きは踏んでいただくにしても、意見書を出すということに関しては、大事なことだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"あべ委員","kind":"提案","question":"ここでいきなり提案して、さあどうだというのは、違う流れのほうがやりやすいかなというふうに考えて。さっきのは提案と受け取らないでいただけるとありがたいのですがとの意見を述べました。","respondent":"鈴木（ひ）委員長","answer":"そうですね。その件に関しては、また、正副でもちょっと検討をさせていただきたいと思います。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858443?Template=document&Id=6010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":76109,"voices":171}},{"id":"h28-20160630-18","meetingId":"h28-cm06","date":"2016年6月30日","dateIso":"2016-06-30","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時５９分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"それから、城南地域での障害者総合スポーツセンターの設置を要望されたいということ。品川だけではなくて、ほかの開催自治体が同じような仕組みをとっていただければなおありがたいと考えていますので、提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"提案","question":"次が、区内開催事業の候補、これも先ほどもありましたが、まだ決まっていない部分もあるのですけれども、提案、育成、支援、スケジュールと。最後が、具体的な文化プログラムの候補についての提案、もしくは文化プログラムに類するものについての提案との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"４４番の「品川の伝統文化、子どもが参加できるようにという思いで、３点載せました。一番最初だけかわりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"本当に多くの国民が喜べるレガシーを残したということで出ていましたので、ぜひそういった観点からオリンピック・パラリンピックの推進をしていきたいと思って、載せましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"いながわ委員","kind":"質問・要望","question":"東京都の視察にお伺いしたときのムービーを見たのですけれども、いろいろな種目、それを考えてやっていただきたいということ。４９番が、活動拠点の確認というのですか、そういったものも含んで書きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"提案","question":"うちは３点挙げさせていただきまして、まず、予算・事業量に見合った人員体制をどういうふうにしていくのかということです。４法人の連携と活用をこれからどういうふうにしていくのかということと、もう一点は、議場で演奏会の開催をしたらどうかと提案したいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"優先というのはどうやって優先するのだろうかという質問をして、そのときはまだ東京都ですか、結構生活に影響が出ることかと思います。あまり分けずに、障害者もそうでない人も一緒に楽しめるような機会を盛り上げていけたらいいかと思って、書きました。","respondent":"渡辺委員長","answer":"そういう方法論などのお考えもおありだと思いますし、競技場については９月以降、中間まとめを用意されていると。今、それぞれご説明いただいて、次回以降、その内容で同種のものを整理して、テーマ別に委員間討議に入りたいと思っています。","id":"exchange-007"}]},{"id":"topic-02","title":"リオデジャネイロオリンピックの視察","agenda":"リオデジャネイロオリンピックの視察","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"視察をして、２０２０年の東京オリンピックにそのことを活用するというのが、私は目的だと思っているのです。その辺のことをしっかり書いていないわけですから、口頭でいいので答弁していただきたいのですけれども、お願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"予定されていることもあって、２０２０年には活かしたいという気持ちがこちらに入っているわけですが、伝え切れなかったと思います。２０２０に向けて、当然、今回の視察を確実に活かしたいという意気込みで、視察団員全員が考えているところです。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"税金を使って行くわけですから、心にとめて行っていただきたい、視察をしてきていただきたい。さっきの各会派の要望でも書いてありますけれども、それをどう活用していくかというのが一番大事だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"品川・生活者ネットワークの３会派で、リオデジャネイロオリンピック視察調査への議員派遣の中止を求める申し入れというのを行ってきたところです。提出をしていただきたいと思っていますけれども、その辺についてどうかということを伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"実際にホッケーとビーチバレーボールの競技場に行く予定でございまして、会場内に入ってからも、当然チケットも今入手予定ですので。それから、３点目の、ブラインドサッカーの開催準備状況ですが、リオでも、ホッケーの後にパラリンピックでブラインドサッカーをやる予定です。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、なぜ契約がまだ整っていないのか、その辺を教えてほしいと求めました。ですから、そういう点で、開催中に行くということが私は理解できないので、それを入れたというのはどういう理由かを説明するよう求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今までの区側の説明が不足だったのではないかですけれども、お認めいただいたということで、理解をしています。今の考え方は最低限使用料は無料、それから、移動費なども区でご負担できるようになればという思いがあります。","id":"exchange-011"},{"speaker":"南委員","kind":"提案","question":"４月６日に区長から議会のほうに議員２名をどうかというご提案があったときに、それ以降の議運で、そういうことを再三主張してきたのです。そのあたりをもう一回伺いたいのと、誘致ですから、限られているわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"私はもう一度そこのところは伺っておきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１点目の、事前キャンプについて、区民の方にいつどのように説明するかですけれども、まだ事前キャンプについての見通しが立ってございません。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"先ほどの繰り返しになるから簡単に言うけれども、９６万円という１人当たりの金額だけでも、通常価格に比べれば相当な金額だと思うのです。何かあったような気もしたのですけれども、また後で質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、それの交渉もこのコーディネートのほうになるのですか。１カ月先の予定までは立てられないと言われているとか、具体的にどの段階なのか、説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"多言語対応のサイン類ですが、それとはまた別の形のサイン類ということも当然考えられるわけですので、きちんと確認していきたいと考えています。ブラジル大使館にも行く予定なのですが、今、ブラインドサッカー協会の関係者なども当たったりしています。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"そこまであって本当にお金が取れるコーディネートというふうに思うのですが、今の交渉状況、ずっと同じということはないと思うのです。その辺、説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"本日お示しいたしました資料の２枚目に、調査・活動内容の予定とありますけれども、接触をしていただいているところです。もう少しお時間がかかるですが、来月の特別委員会には確実に確定したものをお示しできるという見通しです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"大会中のこの日程でというのは、費用対効果を考えてもどうかと考えて、反対というふうに思っております。裏側まで見てきていただかないと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちずっと共産党としては内訳を求めてきていましたので、まず聞きたいのは、最初は２,１００万円と言っていたと。当初約２,１００万円を計上していた、２,１００万円では高いという批判を受けて、改めて見積もり直したということなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"この２,１００万円と、予算としては２,１００万円で議決もされているわけですので、どういうふうになっているのか。丼勘定と言われても仕方がないのではないかというような感じがするのですけれども、そこら辺はどのようにお考えなのか伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"最初のご説明でもお話ししましたとおり、当初予算につきましては、昨年の秋口に見積もりをとったものです。ただ、執行については、確実に最低限のものを執行したいという思いで、きちんと契約に至ったです。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"来てほしいという思いもあるので、その国でしかやられないものですから、そこまで上げていけるものだと思うのです。改めて伺うのですけれども、関係者と会えない、誰とも会えないとなっても、視察はされるのか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"相手への折衝につきましては、今まさにしているところでございまして、区は当然会えるということを見越して、行くものです。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"これから７月中旬に詳しいことが出るということですけれども、これで本当に会えなかったら、競技を観戦しに行くだけになってしまいます。そして、話を聞きたいという、それが視察ですから、ですけれども、それが成り立たなかったときどうするのかというのを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"だけど、会えなかったらどうするのかということを今聞いたので、そこも改めてまたお願いしたいと思います。今回、大分これを上回っている旅費になるのですが、人事委員会との協議はされたのかどうか伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今回の旅費につきましては、全面委託で委託料ですけれども、区として必要な経費だということで判断をして執行するものです。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"では、この条例よりももっと特例だということなのでしょうか。こうした旅費を支給するということが決まったのだろうと私は思うのですけれども、では、今回の決定は何なのかを伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘の旅費の規定につきましては、旅費という科目についての考え方でございまして、今回の視察にかかわる経費につきましては、その旅費の規定には当たらない、委託料です。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこら辺を引き続き改めてはっきりさせていただきたいと思うのと、これからもむしろ東京都といろいろと連携して話を聞いていきたいと思いました。しかも会えるかどうかもわからないのに行って、だけども、こっちで十分できることはまだまだたくさんあるのに……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"ここからここまでどうですか、ここからここはどうですかというふうに、ここにこそこの予算をかけるべきだと思うのです。これだけのお金をかけてというのが、本当にそれ以外にできることはこっちで十分あると感じるのですけれども、そこはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一般質問においても、この派遣についてはさまざまな主張がありましたけれども、今日は１つだけ確認をさせてほしいと求めました。今までオリンピックを各国でやってきて、そのような仕組みになっているのかどうか、その辺についてお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２０２０を契機にさまざま区が発展することを目指して、これまでもいろいろなことを取り組んでまいりました。そうした中で、そういった例えば、都に対する従属的な立場であるとかいうことは、区にとってはとても心外な発言であると受けとめているところです。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、主催者と主体者というところをあえて混同するということはやめてほしいというふうに思いますし、そこのところは峻別をしていただきたい。このように考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"提案","question":"平成１１年度の品川区議会海外調査団の報告の提案が、第三者評価であり、苦情調査委員会に具体的に展開されているわけです。しっかりとした報告書をつくっていただいて、堂々とした実績を持ってお返ししていきたいと思うのですが、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ご指摘のとおり、私たちは物見遊山で行くわけではございません。まずは議会に報告をさせていただき、区民の皆様にも、目に見える形で活かしていきたいと考えております。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"意見","question":"どうしても批判される方々は、そういう批判だけで終わってしまうのです。ぜひオリンピック視察の成果を十二分に反映していただいて、品川区のオリンピック開催に万全な対策を築いていただきますようにお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"６００万円ぐらいお金は減額されたけれども、自治体にとっても、大変なときに伺う。先ほどちょっと申し上げたのですけれども、そこについてさっき伺い損なってしまったので、教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それから、２点目につきまして、旅費でなければ高額な支出でいいのかということを区が言っているわけでは一切ございません。先ほどのご質問で、人事委員会への確認が必要だということについては、そこについては今回は当たりませんというご説明をさせていただいたものです。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"ですから、やはりそういう点で、この３つのホテルについて宣伝を公費でしていることになってしまうのではないかと思うので、それで聞いたのです。その辺を伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"続きまして、２点目、区といたしましては、委託料になればどんな多額の支出でもいいと考えているわけではございません。そういったことで、必要な経費ということで、区として適正と認め、支出をしようとしています。","id":"exchange-031"},{"speaker":"松永委員","kind":"質問","question":"議員派遣について伺いたいのですけれども、この２点で、議員派遣は必要であると考えております。伺いますが、区として議員派遣についてどのようなお考えを持っているのか、その意義とはどう考えているのか伺います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２年前から早々と特別委員会というものを設置し、特に一昨年につきましては、東京都に要望書まで出しているというような実績も上げているところです。","id":"exchange-032"},{"speaker":"松永委員","kind":"質問","question":"最後にまとめさせていただきまして、総合的な安全対策について伺いたいと思います。安全・安心対策、要するに、治安の維持であると考えますが、その点についてお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今後の２０２０にも十分参考になることですので、視察の項目に挙げておりますので、見てきたいと考えているところです。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"その前の質問のときに、改めてもう一度、答弁がなかったのもあって伺いたいと思います。区民の理解、得られると思いますかということです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然、結果報告につきましても、２０２０の大会に活かせるように、万全の報告を、成果を活かせるようにしてまいります。そういった意味で、最後には区民の方全員に理解を得られるように努力してまいります。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/158474?Template=document&Id=6496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":39423,"voices":84}},{"id":"h28-20160706-10","meetingId":"h28-cm07","date":"2016年7月6日","dateIso":"2016-07-06","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"議員派遣の件","agenda":"議員派遣の件","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけ意見を述べさせてほしいと求めました。本会議の議決を経て議員を海外に派遣するわけですから、説明は積極的に行うべきだと思いますので、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"リオデジャネイロオリンピックの視察","agenda":"リオデジャネイロオリンピックの視察","exchanges":[{"speaker":"沢田委員","kind":"確認","question":"今後の取組みにおいて、地元自治体がどのようにかかわっているかを現地において確認することが重要であると考え、視察を決定しました。開催会場がある本区にとって大変重要であり、大会期間中に確認することができるからこそ、非常に有効であると考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"これは成功しないということですから、賛成である、応援したいと言っていることとかなり矛盾があるのではないかと考えております。議会の責任としても行うべきであるということから、５月２６日の議会において議決に賛成をした次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"どちらを指していらっしゃるのかがちょっとこの文章からわからなかったところですから、ちょっとそこをお伺いしたいなと考えています。あるいはオリパラでもう出ていれば教えていただきたいのですけれども、この日程調整はどちらに、電通さんにお願いしているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"区民の税金を使うことについてどうなのかという、この税金の無駄遣い、やはり区民の皆さんに説明をしていく責任があるのではないかなと思っています。なので、本日、リオデジャネイロオリンピックの視察・調査への職員・議員派遣の中止を求める申し入れというものを行う予定であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"やはりこれは都民である以上、区民もいらっしゃるわけですから、私はそこは重く受けとめるべきではないかなと。皆さんそういうことも私は考えるべきではないかなと思いますので、今回の派遣に対しては私は中止をしたいと申し入れます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-03","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"そして２点目は、前回の一般質問の中で非常に怒声のような野次が飛んで、議事の進行を妨害しているような状況がございました。もしくは議長のほうにお伺いをしたいのですが、何か会議規則において定まっているのか、またそれに対して何かできるのかどうか伺いたいと思います。","respondent":"原区議会事務局長","answer":"法的な根拠のほうから、ちょっと私のほうでご説明させていただきたいと思います。第７条の規定を傍聴の券の裏に印刷をし、傍聴規則、それから傍聴券の取扱いということでやっているところです。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"広報番組においても傍聴に来てくださいということで広報しているわけですから、直接民主制ではないのですから、このように考えております。もしご意見がいただけるようであれば、ご意見伺いたいと思います。","respondent":"大沢議長","answer":"私は去年１年間、２年目に入りました。傍聴規則ゆえに、委員のご指摘しっかりと受けとめて、臆することなく毅然と議場の秩序維持に努めてまいりたいと思います。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"ですが、その前に我々議員も皆さんの模範となるべく、やはり野次等慎んで、皆さんにその範を見せるべきではないですか。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"議長の、またその規則ゆえにそのことがさらなる混乱を招かないようにしていきたいという議長のご発言もとても重いと思います。それが直接当たるとなってしまってはどうかなという思いもありますし、ちょっと歯切れが悪く、一言意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"確認","question":"ただおっしゃったように、逆にその場がかえって荒れてしまうという恐れも確かにあるということで、例えば傍聴手続の際に一定確認していただく。それは強制力という意味でなくても、ある程度予防策みたいなものがとれないかなとも考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"意見","question":"仮に自分がお呼びした方の場合などは、以前も何回かありますが、やはり携帯が鳴ってはあれだろうとかあります。ぜひそこは議員もしっかり傍聴の方にもお願いして、徹底してもらうというのが大事だと思いますので、意見として言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701951?Template=document&Id=5190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":20101,"voices":69}},{"id":"h28-20160714-8","meetingId":"h28-cm07","date":"2016年7月14日","dateIso":"2016-07-14","committee":"建設委員会","time":"午前１０時００分～午後 ４時０３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4176#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":1342,"voices":8}},{"id":"h28-20160726-6","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"区民委員会","time":"午後 １時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"わかればでいいのですけれども、実際品川区の景気というのでしょうか浮揚効果というのでしょうか、そういったデータというのは必要だと……。さらに幅広い企業の方々にそういうのを利用していただくというのは非常にありがたいことというのがあるので、その辺はどうお考えかと。","respondent":"山崎商業・ものづくり課長","answer":"ここのところについては、かけた予算に対しての費用対効果ですとか経済波及効果についてなかなか明確に説明できるものは今現在実は持っておりません。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問・要望","question":"施策について教えていただきたいのが１点と、もう一点は、経済効果が何兆円と出てくるではないですか。東京に２０２０年来るわけですから、これはちょっとオリンピック・パラリンピックの担当の課長にお伺いしたいのですけれども、置いてあるのか。","respondent":"立木産業活性化担当課長、山崎商業・ものづくり課長、小川オリンピック・パラリンピック準備課長","answer":"平成２７年度からは国の緊急雇用の補助金が区としては終わりましたので、こちらはインターンシップという形で実施をしているものです。… それからもう一つ、ソフトのほうでは外国人をお招きするためにいろいろなおもてなしの関係で整備をされて多国籍の対応をしたりとか。… 優先度をこちらで考えまして、それから体育館、そういったところを中心にまず今飾りをつけ始めているところです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"あわせて伺いたいのは、いわゆる第３次までの実施計画と４月以降の第４次の実施計画で、そういう事業はどこなのか。そしてそれがどういう内容のものなのか、第４次実施計画も始まりましたので、そこを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"実施計画第３次、そもそもこの実施計画というのは、そこで示されたものをそれぞれ中期の３年間で具体化していくというのが実施計画になっております。そういう意味では、第３次も含めて第４次はより充実した形で就業支援のメニューは多様化し。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"第４次実施計画の中での充実点、強化点という視点で１点伺いたいと思います。この関係というのは、トリクルダウン政策という考え方に基づいているのか、ちょっとそこを伺いたいと思うのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"どちらかに軸足を置くということよりも、品川の産業の発展のためには双方バランスよく行政として支援をしていくことが必要であると認識しています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"こういう関係が起きることを区はどういうふうに教訓化というのでしょうか、政策化というのでしょうか、そこをどう考えていらっしゃるのか。東京都市ならではであるのかなと問題意識もあるのですけれども、そこについてお考えを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"西大井の付近といいますかニコンの大井工場の付近、来年で１００年という歴史があるそうです。ですから、先ほど説明させていただいた販路拡大、営業支援の施策メニューに具体化されているというようなことで頑張っているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"高い技術力を持って下請からの脱却と、区としてはそういうのを進めていくにはどういう支援をしているのかという点を伺いたいと思うのですけれども。そういう新たな支援策というのは、私も議論を深めながら提案できるようにしたいとは思うのですけれども、伺いたいと思いますとの意見を述べました。","respondent":"立木産業活性化担当課長","answer":"そういった形の支援等を行うとともに、やはり受注、事細かくマッチングを行った上での商談会というものも事業として行っております。例えば、そういったようなものとか、そういったようなことも今後しっかりと研究してまいりたいと考えています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"提案","question":"仕事の紹介のときにいろいろ仕組みがあるとは伺っているのですけれども、また人材育成にもつながっていく、産業の発展にもつながっていく。そういう仕組みにつながってくると思うのですけれども、現状の取組みと今後の方向を具体的に伺えたらと思いますとの意見を述べました。","respondent":"立木産業活性化担当課長","answer":"こちらの体験先になります企業も、その中で労働の賃金をどうはかっていただくかというところでは、非常に有効な手段だと考えています。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"産学官のところで、実際にこの品川区内中小企業と就労とかが結びつき、実のところどう把握されているのか伺いたいと思います。１人の学生が何カ所も中小企業を見たりしている、例えば前に産学官で質問したことがあったのは、その辺で現状をわかる範囲で教えていただければ。","respondent":"立木産業活性化担当課長","answer":"そういった中で、区内の学校との連携という形では、今のところ例えば工業系の学校になりますと都立の産業技術高等専門学校があります。そういったところで学生の区内企業への就職等で何か事業ができないかどうかというところを継続してまいりたいと思ってます。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"非常に使いやすい制度という会社もあれば、意識がどうしても経営的なところで資金管理という意識を持たないと、それが基本だろうと。経営意識ですか、その部分というのをやはりこの支援事業にはどんなふうにウエートを占めるのか、その辺を説明するよう求めました。","respondent":"山崎商業・ものづくり課長","answer":"今回の事業承継支援には、筋道を立てて経営者の判断に資するというような専門家のご相談をしっかりまずやろうということにしています。","id":"exchange-009"},{"speaker":"伊藤副委員長","kind":"質問","question":"やはり伺ってきた話は、要は全体像がわからない、企業経営者の方々に。どう言ったらいいのだろう、そういう書をつくって区内企業の方に説明したほうがいいのではないかとすごく思ったのですが、いかがでしょう。","respondent":"山崎商業・ものづくり課長","answer":"国の支援はこういうものがある、それも含めてしっかりＰＲできる、あるいはご理解していただくようなものを検討して考えてみたいなと思ってあります。ありがとうございました。","id":"exchange-010"},{"speaker":"伊藤副委員長","kind":"質問","question":"だから、あのイメージで企業支援の特集を組んでもいいではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2758#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":18243,"voices":34}},{"id":"h28-20160726-7","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"の１、報告事項の(1) 臨時福祉給付金の実施","agenda":"の１、報告事項の(1) 臨時福祉給付金の実施","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"申請書を１回送付しただけでなく、申請しなかった人への働きかけをされたのかについても教えてほしいと求めました。今年が３,０００円となると思うのですが、なぜこの額になったのか、なぜ今年は半額なのかをお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"それの半年分、半分ということで、金額的には６,０００円の半分、３,０００円となっていると国からは回答をされております。これは３年目になりますので、その口座で変更がなければ、その指定された口座に振り込みをするという流れになっているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この制度的な対応というのはどういうものなのかということで、ホームページでの説明では、こういう措置をとるということで書かれているのです。来年の４月から、３,０００円という形で出てくるという方向なのか、そこら辺のところがわかったら教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"委員ご指摘のように、平成２９年４月から軽減税率の制度が開始される予定であることを踏まえというのが前提になっております。この軽減税率の開始までの半年分を支給するというのがこの制度の趣旨になっておりますけれども、残念ながら、正式なお話というのが来ておりません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そもそも６,０００円というものが実際よりも少ないと思うのですけれども、逆進性の税金だという矛盾を認めたからこそ、つくられた制度だと思います。延期ではなく中止すべきですし、８％も元に戻すべきということを主張させていただいて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、１番の申請書発送数と支給数の差が大体２,０００人ぐらいあるということで、その方たちは、今回、２番の2)の支給対象者の３,４００人の中には含まれるということでよろしいのか。","respondent":"大串福祉計画課長","answer":"今年度が対象になってまいりますので、その申請しなかった２,０００人の方にも３,０００円ということで、該当になる方には通知を出する形になります。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"これは１番の３万円と同じ考えなのだけれども、１番でいただいた方は、もうだめということなのか。１番で、また2)の３万円は案内を出す、もしくは対象になっているという考えでいいのか尋ねました。","respondent":"大串福祉計画課長","answer":"つまり、６５歳以上の方で非課税で、なおかつ障害・遺族基礎年金の受給をされている方という条件であれば出する形になります。ただし、春の高齢者向け、障害・遺族基礎年金をもらっていた方であっても除かれるような構造になっているところです。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"２番の2)では、今度は支給対象者が約３,４００人ということで、単純に見ると１,４００人ぐらい増える。その増えた１,４００人ぐらいは、見通しとしては、新たにその対象に加わる方がそれくらいいるという考え方でいいのか尋ねました。","respondent":"大串福祉計画課長","answer":"そうした中で、突合はなかなか難しいところでございまして、今のところ、５月に支給された人数ということで、３,４００人という数字を出しています。３,４００人と２,０００人、その差の１,４００人という関係性が成り立つかどうかというのは難しいと思います。","id":"exchange-006"}]},{"id":"topic-02","title":"品川区行方不明高齢者早期発見の仕組み","agenda":"品川区行方不明高齢者早期発見の仕組み","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２の早期発見のための品川くるみ見守りネットワーク構築というところなのですけれども、それとも、どうなのかもお聞かせほしいと求めました。徘回で見つかっていない行方不明者というのは、品川区で行方不明者がどれくらいいるのがわかっていたら、それも教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"アイロンシールにつきましては、今、枚数を具体的に検討中ですけれども、複数枚、用意をしております。行方不明になったとか、近隣の事業所等に一斉に連絡をしながら、長くても翌日には見つかっているような状況になっております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひご利用くださいという周知をしていただきたいと思うのですけれども、その周知については、どう考えられているのか。この自己負担の毎月かかる料金についても、もうちょっと助成制度があるといいと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"在宅介護支援センターに対しては、ご説明をしていますので、おおむね把握できているのではないかと考えています。新しいものを出していると聞いておりますので、そういうところと比較しながら、より良い方向になるように検討していきたいと考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"認知症になられた方が、どこでどういうふうに情報を得られるかというところで、ホームページとか何かをすごい探しながらやったりしているのです。この冊子というのはその１つだと思うのですけれども、そういう制度があるというお知らせはぜひしていただきたいということで、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問","question":"前に１回、大改造をしたときに、災害情報も自分で登録しなければならないというときがあったと思うのです。何らかの形で、全員にお知らせできるようにするのか、そこら辺の基本的な考え方を説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"現在のところ、しなメールにつきましては、今、協議中ですけれども、一番最初の画面にいきなり出すというのは難しい状況だと聞いております。やはり選択をして、チェックをしていただくことが必要だと聞いているところです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問","question":"多分そうかと思いながら質問させていただきました。どういう努力をしたらいいのかはぴんとこないですけれども、そういうような形で推進をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"それから、(2)も含みますけれども、情報提供先です。個人の名前とか住所とか、個人情報をどの辺まで流すのかというのを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"身長はどのぐらい、どのような髪型、どのような持ち物かということを提供することになっております。この情報提供につきましては、申請のときにきちんと同意書をご家族の方にとってからやる方式をとろうと考えています。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"もう一つは、ケースによって、例えば警察に捜索依頼をされる場合もあると思うのです。どうしても、警察から区に連携されるような仕組みというのはあるのかどうか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"それも公表していいという依頼があれば、きちんと同意をとれれば、公表することを考えております。欲しいという声も出ているところですので、その辺は、これからもう少し調整をしていきたいと考えています。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"質問・要望","question":"もっと言えば、警察から区に問い合わせたときに、そこで連携がうまくいくようなものをぜひ構築してほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"安藤副委員長","kind":"確認","question":"１点、確認です。2)の外出に不安のある６５歳以上の方というのは、どういった方なのか、お伺いします。","respondent":"永尾高齢者福祉課長","answer":"鉄道事業者についてもですけれども、官公署連絡会等で、今後、この制度について周知を図る予定になっております。こちらについては、警察で対応ということで、今、調整をしています。","id":"exchange-015"}]},{"id":"topic-03","title":"の３、行政視察","agenda":"の３、行政視察","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この７自治体で始まって、これからも７自治体でいくのか、その辺の経過も教えてほしいと求めました。国のこういう介護度を改善させていくモデル事業とか、そういう国の方針とのかかわりというのがどうなのかについてお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"厚生労働省はかかわっているかですけれども、この第２回の協議会につきましては、厚生労働省から２名参加する予定になっております。介護報酬を検討している状況の中で、国とともに、より良い方向になるよう検討していきたいと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"別なサービス質の評価先行というのが中身としてあるのか、その辺についても説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"品川区は施設に限定しておりますので、各自治体それぞれ取り組みがばらばらになっています。ただ、そういう例を紹介しながら、どの方法が全国で一律にやる場合にいいかということの検討を国にやってほしいという提言をしようと考えています。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3452#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":19343,"voices":53}},{"id":"h28-20160726-8","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"建設委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"平成２８年８月都営住宅入居者募集","agenda":"平成２８年８月都営住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回は都で１,５９４戸ということで、この間、私どものところにも、住宅相談、また都営住宅に入りたいという要望は絶えないわけです。８番の休日相談窓口が開かれているというところですけれども、ここには大体どれぐらいの方がご相談にいらっしゃっているのかを伺いたいと思います。","respondent":"今井住宅課長","answer":"とても幅が広いものですが、１０件以下です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も先日、ご主人を亡くされたという方から、もう年金もわずかで、家賃が払い切れないので、都営住宅の申込みをしていきたいという相談も受けました。そこについての質問をされたときに、この計画に我関せずではなく当事者として関与してほしいということで、具体的に伺いたいと思うのです。","respondent":"東野まちづくり立体化担当課長","answer":"北品川の都営住宅のところですけれども、現在、品川駅南地域におけますまちづくりビジョンをもとにしまして、重点地区としての再開発計画があります。当事者として、その再開発の勉強会等に参画いただきたいということで、現在も都に働きかけをしています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"東京都に対して強く働きかけていきたいとも言っているのですけれども、要は、あそこの都営住宅を開発でなくしていくということなのでしょうか。地域の皆様から不安の声も大変たくさん出ているところなのですが、これを区も積極的に進めていくということで進んでいるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"裁判にもなろうという状況に、もうあるところもあるということです。ぜひ安心して住み続けられる公営住宅を増やしていくことこそ必要だと思いますので、それだけ主張して終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"塚本委員","kind":"意見","question":"８番の休日相談窓口なのですけれども、先ほどの質疑で１０名以下という相談実績ということですが、どういうことを目的とした相談窓口になっているのかお知らせくださいとの意見を述べました。","respondent":"今井住宅課長","answer":"そういう意味では、土日というところで、そういう書き方も含めてご説明する形になります。どちらかというとなかなか読みづらいこのようなパンフレットの内容を詳しくご説明しながら、書き方をご案内する形になっております。","id":"exchange-005"},{"speaker":"塚本委員","kind":"確認","question":"とにかく都営住宅に入りたくてどうすればいいだろうかといったことは、一定程度、申込みに至るまで面倒を見ていただけると。相談窓口期間に関して言えば２日間だけなので、その辺のところでのご案内というのは、こちらにしていけばいいということでよろしいのか、確認します。","respondent":"今井住宅課長","answer":"例えば都営住宅で来られても、では区営住宅はいつ申し込めるのかとか、例えば年何回やっているのだとか、そういう幅広いご説明をします。土日は開けしていますが、その点を含めまして、通常の窓口でも対応を幅広く行っている状況です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"これは都営住宅なので、東京都全体の申込みという形になると思うのですが、状況によってかなり変わってくるかと思いますが、品川区在住の方が入れる確率は、どういう実態があるのか尋ねました。","respondent":"今井住宅課長","answer":"２月については募集戸数が１件でございまして、応募数が７２件ございましたので、７２倍ということになっております。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"品川区在住だけれども、ほかのところでもいいという方ももちろんいらっしゃると思うのですが、実際、品川区の方々が都営住宅にどのぐらい入られたかというのはわからないのか尋ねました。","respondent":"今井住宅課長","answer":"申し訳ございませんが、この応募倍率は、今ございましたとおり、品川区の中で空きが出ている戸数に対しての応募状況でございまして、どこの区の住宅に申し込んでも構わないことになっておりますので、そういう区民の申込みのデータとしては公表されておりません。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"初めに、震度７が２回起こったということで、過去に前例のないような地震のタイプということが報道されていたと思います。そういうところをどのように今、区の防災課としては見ていらっしゃるのか、何かあればお聞きしたいと思います。","respondent":"古巻防災課長","answer":"震度７の地震が２回起きたということで、今後の検証によりまして、対策を検討していきたいというふうに大枠では考えております。２回も大きな地震、分析を進めているところですので、きちんとした対応を考えていきたい。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"専門家による様々な分析とか検証というのが行われていくのでしょうけれども、見通しというか、どういう形の検証が進んでいくのか。それを地方自治体に、この検証のステップ、進め方はどういうふうな見通しになるのかお聞きします。","respondent":"古巻防災課長","answer":"事前の調査ということで、委託で調査、それから来年度の改定の方向性を定めるという形で事業を進める予定になっております。年度内には一定の、区としても、来年度に向けての具体的な内容がまとめられるのではないかと今は考えているところです。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"例えばこの前の感震ブレーカーをもっと進めるべきだとか、また、来年の地域防災計画の改定に向けた国としての基本的な考え方を出してくるということでよろしいのか尋ねました。","respondent":"古巻防災課長","answer":"今回の初動対応に関するレポートは、この検証チームがある程度、初動対応に関して検証を進めていくという流れになると考えているところです。会議を開催するタイミングで、熊本地震に関しまして、この議題に上がってくるものと考えております。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３の2)の避難所の運営のことについてお伺いしたいのですけれども、これは実際、発災をしてから避難所として機能するということだと思うのです。(3)のボランティアの中の1)支援内容のところの医療の中に、医師と看護師は入っているのですが、その３点をお聞きします。","respondent":"古巻防災課長","answer":"１度つくってしまったものについての改定については、状況に応じた変更を加えていくという形で、働きかけをしていきたいと考えております。具体的な地域内輸送基地にするかどうかというところまでは、今まだ検討が進んでいない状況となっております。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"その辺も含めて、もう一回、実際に発災したときに問題なく機能できるようなマニュアルをつくってほしいと求めました。荏原医師会との連携をとっていただいて、ボランティアの薬剤師についても防災課でもう一回、協議をしてほしいと求めました。","respondent":"古巻防災課長","answer":"避難所運営に関しまして、委員からご指摘いただいた点、十分に防災課としても認識をさせていただきまして、今後てこ入れと申しますか、教育委員会とも連携をとりながら進めてまいりたいと考えておりますので、よろしくお願いします。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"避難所に入るまでもないけれども、ただ物資が不足している人の対応というのはどうお考えなのかということがまず１点。それから海上輸送なのですけれども、運河から目黒川を利用するということもお考えなのかということが３点目の質問です。","respondent":"古巻防災課長、和田河川下水道課長","answer":"マンション等への対応ということも、実態も含めまして、調査それから研究を進めてまいりたいと考えております。水上の輸送に関して、東京都との関係がありますので、連携しながら対応を考えていきたいと考えている段階です。 詳しくは、次回の委員会の所管事務調査で、舟運の災害対策活用についてということでご説明差し上げます。その選定の考え方とか、どのような指揮命令系統によって、その辺については東京都が今後整理をしていくものと考えられます。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"全ての人が避難してきたら受け入れはできないわけですから、避難所の運営としても、家が倒れなければ家での暮らしがそのまま送れるわけですから。木造住宅の耐震化というのを品川区は目標を持って進めてきていたと思うのですが、そこは今、どこら辺まで来ているのかを伺いたいと思います。","respondent":"鈴木建築課長","answer":"木造住宅の耐震化率ですが、概算になりますけれども、今年の１月現在、約７２％です。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"すごくたくさんの方が、そういったいろいろな思いの状況のもとでの避難所になると思うのです。そしてこれだけの耐震化率で、避難所は対応していけるのかということがいつも不安なのですが、そこら辺はどのように考えられているのか尋ねました。","respondent":"古巻防災課長、鈴木建築課長","answer":"地域防災計画が想定しております、東京都の被害想定に基づいた避難者数に対してきちんと対応できるような整備を行っていると考えているところです。十分に避難に関する周知、それから啓発をしていくということも… やはり１軒でも多く、地震に強い建物にしていただいて、在宅避難で対応いただくというのが基本だと思います。安心な建物については、そのまま残っていただくといった総合的なところで対応していきたいです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"住民とすると、自宅が残っている方は在宅避難という区としての呼びかけというのはどれぐらいやられているのか。耐震化率の目標があったかと思うのですが、今、７２％というのはどういうところまでなのかを教えてほしいと求めました。","respondent":"古巻防災課長、鈴木建築課長","answer":"まだ足りない部分につきましては、先ほどもご答弁申し上げましたけれども、避難に関する知識の普及・啓発ということも重要になってくると思います。在宅で避難されている方への情報提供といったところについても… 耐震化率の目標ですが、平成３２年度までに９５％という目標を定めてあります。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"調達物資とありますが、品川区に来るという命令系統は、誰がどういうふうにしてくるのでしょうか。ここに入ってきたものをどういうふうに選別して、どういうふうに、それぞれ何を持っていくのかという視点もあるのか尋ねました。","respondent":"寺嶋木密整備推進課長、古巻防災課長、鈴木建築課長","answer":"の火災は、その範囲内で食いとめるといった考え方に基づいて、防災生活圏事業というのを実施しております。… 実効性云々のところはありますけれども、それが主体的に動けるような、実効性を持たせられるような日頃からの対応を考えていきたいと考えております。… 当然ながら、被災状況によってはこの人数で対応できないというところで、他府県に応援を要請するということになります。","id":"exchange-018"},{"speaker":"西本委員","kind":"提案","question":"委員長に提案をしたいのですが、今回の第２回定例会で例を出させてもらいましたけれども、避難所シミュレーションのゲームみたいなものがあるのです。あれを１度、それを１度、ご提案をしたいと思いますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"全く空輸がないというわけではありませんけれども、小型ヘリぐらいの広さしかありませんので、広さからしても難しいのではないかと。品川区にどれぐらいヘリが来てくれるのかというのも、私はお願いはしますけれども、そこの約束はできないところだとは思います。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"それはそれで特徴の１つとしていろいろ流れをつくっていかないと、それが有効的に、意外と小回りが利くからいいという場合もあると思うのです。今日の説明なのだろうと思うのですけれども、もう初めからそういうことを視野に入れてやっていただきたいという要望をします、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"基本的なところなのですけれども、避難所に入られる方というのは、早い者勝ちになってしまうのですか。あっという間に避難所が埋まってしまう可能性もあるので、そこら辺りの振り分けというか解決方法というのはどうお考えなのかということが２点目。","respondent":"古巻防災課長","answer":"３日間は職場に待機する、そのあたりを周知・啓発を進めていくということと、対策を今は検討しています。実際に要支援の方がどういった形で避難をするのかというところも具体的に、もう少し個別の計画の中で対応を考えていきたいと思っているところです。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"ある程度、客観的に要支援者とかの証明があって、それを避難所運営している方が見て判断するという理解でいいのか尋ねました。","respondent":"古巻防災課長、松代防災まちづくり部長","answer":"特に要支援者の方につきましては、要支援者を支援する、その方が判断できるような形。もしくは、個別の計画運用の中で、どういった形の避難をしていくのかというところがわかるように整備をしていきたいと考えております。しかし、誰が行っても対応できるようなものをまずマニュアルでつくるというのをこれまでずっと進めてきて、一定のマニュアル的なものを用意しました。","id":"exchange-022"},{"speaker":"西本委員","kind":"提案","question":"先ほどもご提案をさせていただきました。それをぜひ検討していただきたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"提案","question":"今後も今みたいな形で、取り上げていきたい内容というのは聞いていただけるのですか。ちょっと今は具体的なものがないのですけれども、今後もこういった形で、こちらから提案ということはとの意見を述べました。","respondent":"若林委員長","answer":"何回とれるかということもあるので、これだけでも議論百出するようなことを想定していますので、その時々に正副で調整させていただきたいと思います。今後について、何かご意見はありますか。","id":"exchange-024"},{"speaker":"塚本委員","kind":"意見","question":"この後、行政視察についてやられると思うのですけれども、今あるこの案を見ていくと、結構、防災対策系のことが出ていますので、所管事務調査を次にやる時期は、おそらくこの行政視察の後ぐらいになるかと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"それに対して、見ることによって何かを期待するという部分もあるかと思うのですけれども、そこら辺はどうなのですか。ああ、そうだの、こうだのだけではちょっと申し訳ないと思っているのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"経路的には、北九州市まではちょっときついかなと。熊本市とか久留米市とか、久留米市というと、どちらかというと福祉関係のところが多いかと思ったのだけれども、その辺のところはお任せしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":25981,"voices":71}},{"id":"h28-20160726-9","meetingId":"h28-cm07","date":"2016年7月26日","dateIso":"2016-07-26","committee":"文教委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"「居住実態が把握できない児童」に関する調査","agenda":"「居住実態が把握できない児童」に関する調査","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"これは件というふうにあるのですけれども、お子さんはお一人なのでしょうか、それともご家族で１件とカウントされているのか。結構長く品川区内に居住されていたかどうかなども、書類上わかるのか尋ねました。","respondent":"高山子ども育成課長","answer":"１世帯でも複数いる場合は２件でカウントさせていただいているところです。入国の状況が確認できましたので、あとは居住の実態の確認と、そういった段階です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そもそものことなのですけれども、居住実態が把握できない児童の調査というのは、実態が把握できずに虐待などで亡くなってしまう児童が出ないための調査ということでいいのか確認させてほしいと求めました。","respondent":"高山子ども育成課長","answer":"そもそもこちらの調査の目的ですが、そういったネグレクトも含めた児童虐待につながるような状態で児童が放置されていないかということを確認する趣旨で、当初よりこの調査が始まったところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"こういった事態がどうして起きるのか、普通に生活している中でどうしてこういったことが起きると考えているのか見解を伺いたいと思います。最後に１件わかっていらっしゃらないところがあるというところで、命の危険がないという認識、判断の根拠もあわせてご説明ほしいと求めました。","respondent":"高山子ども育成課長","answer":"あるいは１歳６カ月児健診、それから３歳児健診など、実際さまざまな手段を講じて実態を確認するです。残る１件に対する認識という点なのですが、そこまでの認識はまだないので、まずは現状。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"すみません、ちょっと行ったり来たりしてしまいますが、目的のところに書いてある安全の確認が必要と判断した児童というのがあるのですけれども、これはどういう判断で安全の確認が必要だということになるのか、ご説明ほしいと求めました。","respondent":"高山子ども育成課長","answer":"実際に親御さんのお話をする中で、お子さんの成長なども見する中で、特段注意すべき事項がなければ安全な状態であるという判断をできるようになるというふうに考えているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"確認","question":"それとあと、安全確認ができたところは必要ないというところで、確認ができないところについて調べていくという考え方でいいのでしょうか。品川区の中でそういった必要と判断する基準みたいなものはあるのか尋ねました。","respondent":"高山子ども育成課長","answer":"例えば学齢期になっても就学が確認できないということも一つそういう居住実態が把握できていない児童ということになってまいりますので、居住実態が確認できるまで調査を進める、そういった進め方になろうかと思います。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"新たに誕生したり、移動したり、そういうことが主なのでしょうか。どのくらいかかって行われているのか、これで大体子どもたちの問題というか、明らかになっていくのかどうかというところをお伺いします。","respondent":"高山子ども育成課長","answer":"７月１日、８月１日ということで、それはその時点でそれがゼロとなるような形で調査を進めていくといったものとなります。おおむねこのぐらいの件数が毎月の１日時点での不明児童というような形になってまいりますので、ゼロに近づけていくといった作業になるものです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"残る１件ということで、まだ平成２６年からですから、あったらご紹介してほしいと求めました。","respondent":"高山子ども育成課長","answer":"フォローについてのお尋ねということなのですが、これを一時的に虐待の中でのネグレクトという形でまず事案として取り扱うこととなります。","id":"exchange-007"}]},{"id":"topic-02","title":"平成２８年４月認可保育園等の入園状況（指数）","agenda":"平成２８年４月認可保育園等の入園状況（指数）","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"資料の確認なのですが、どういう場合をいうのか、ご説明ほしいと求めました。２０番の申込締切日時点で、給与明細等で確認できる勤務実態が３カ月に満たない場合マイナス１点と、このようになっている経緯を説明するよう求めました。","respondent":"竹田保育課長","answer":"推測ですが、社員を集めるに当たって、会社としての魅力を増すために低額な預かり料で運営しているものかと考えております。１０月、３カ月に満たない場合と既にずっとご勤務いただいて３カ月お出しできる方の場合に、３カ月に満たない場合はマイナス１としています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"９番のところで、２万円以下の施設は少数だということでしたけれども、何施設あるのか伺いたいと思います。もう少し積極的に知らせていく必要もあるのかなと思うのですが、ホームページ以外の周知の方法をご検討であれば説明を求めました。","respondent":"竹田保育課長","answer":"それから、指数ですが、先ほど申し上げたとおり本日ご説明した後、近日中にホームページに公開してお知らせしていくものです。窓口等でご希望の方には印刷してお配りしたいと考えております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"窓口でも必要な方にはということでしたけれども、そういった資料があるということはわからないと思うので、ぜひご説明して、要るかどうかを聞いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認させていただきたいのですが、この４月にその園にその年齢で入った方のうち、一番指数が低かった人ということでよろしいのですよね。その確認と、この保育園だったら４０ぐらいないと入りにくいのだなとか、いかがか尋ねました。","respondent":"竹田保育課長","answer":"２次の選考もありますし、必ずしも入園された方全てが４０以上であったかということではございませんので、それ以下で入っているケースもあります。それから、ホームページに掲載するときは、丁寧な説明に努めたいと考えております。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"そうすると、１次の結果をホームページで公表して、また最終的に４月段階でどの指数の方が入るのかというのは、また公表するということなのですか。それとも、１次のものを目安として公表して終わりということなのか、そこを説明するよう求めました。","respondent":"竹田保育課長","answer":"全体の入園数から見ますと、１次の部分で大半が占められておりますので、２次あるいは辞退等の補充部分はごくわずかですので、そちらのほうの公表は考えておりませんので、この１次をもって選んでいただくように考えております。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"ただ、それはどういう性格の数字で、どういう内容が入っていて、その後一部ではあるけれども、それ以下の人が入るという実態もある。何かそこら辺のこともできるだけ詳しく情報としてお伝えほしいと求めましたが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"誤解のないようにできだけ丁寧にご説明はしたいと考えておりますが、適切な分量で説明させていただいて、お電話等でご説明したいと考えております。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"０歳からでないと保育園に入れないから早目に復帰するという現状が極めて強くあるというのは、保育課のほうでも把握されていることだと思います。ぜひ０歳が一番入りやすいという状況というのを解消するような努力をしていただきたいと思うのですが、そこの保育課としてのご意見をお願いします。","respondent":"竹田保育課長","answer":"委員ご指摘のとおり一定程度の方が育休を切り上げて０歳児の４月にお申し込みいただいているという方がいらっしゃることは承知しております。全体から言うと少ない数になるのですが、そちらの制度を使って育休を１年なら１年間フルにとっていただくようにご案内しています。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問・要望","question":"すぐ再就職ができる状況なのかどうかということと、どちらが逸失利益が大きいのかという視点もぜひ入れていただきたいのです。その辺については、保育課としてはどのように受けとめていらっしゃいますか尋ねました。","respondent":"竹田保育課長","answer":"そのような中であっても、皆さんに客観的な指数で、しかもわかりやすいものというところで、今まで検討を重ねてつくってきた制度が現状の制度です。１人でも多くの方にご理解いただけるような制度となるように今後も十分検討して見直しを行っていきたいと考えております。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"より周知に、また力を入れてほしいと求めましたし、この指数が公表されていますというようなものをそこにも載せてほしいと求めました。保育園の保護者会等でもぜひとも言っていただきたいですし、ぜひご案内を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほんとうに慎重にわかりやすく公表していただきたいと思うのが１点ですけれども、あと、またこの点数の数値というのはどうやって決めていったのか。多分経過があると思うのですが、ちょっとそこの基本的なところを説明するよう求めました。","respondent":"竹田保育課長","answer":"こちらの指数については、各自治体の判断で決めているものですので、自治体によって違うという現状です。長年いろいろなご意見を伺いながらいろいろな変遷を経てつくってきたものですので、また今後も見直し等も含めて検討していきたいと考えております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"月２０日以上で、日中８時間以上の２０点の方だと、ちょっとその辺の具体的なことを知りたい。その辺の考え方を聞かせてほしいと求めました。","respondent":"竹田保育課長","answer":"フルタイム勤務のひとり親の方は４６点という高得点になっておりますので、入りやすい状況かと考えております。それから、短時間保育室という制度を設けておりますので、そちらのほうで対応させていただきたいと考えております。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとそこの確認をさせていただきたいのと、就学のところは、実際的に預かってもらっていた子どもがだめになったというケースがあるのですかね。何か学校に行き続けられないというのが１件あったのですけれども、ちょっとそこを聞かせていただきたいのと、これは入園できるのか尋ねました。","respondent":"竹田保育課長","answer":"それから、勤務時間の短い方については、当然短時間保育室等をご説明しております。一方で、説明を尽くすがゆえに窓口でのお一人当たりの対応時間が長くなっているというのが現状です。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"実態的にはどうなっているのか、集団で生活できる子はほんとうに積極的に保育園で受け入れていくべきと思っていますが、実態はどうなっているか説明を求めました。","respondent":"竹田保育課長","answer":"特別支援の必要なお子さんについてですけれども、こちらに書いてあるとおり審査会で十分吟味して決めております。その際の考え方としては、そのお子さんにプラスになるのかどうかといった観点を十分審査しまして、可否のほうを判断するところです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"障害児の受入れ状況というのは、人数的にはどんな様子なのか、ちょっと教えていただきたいのが質問の１点です。いかがか尋ねました。","respondent":"竹田保育課長、大澤待機児童対策担当課長","answer":"特別審査会を実施する前に、入園申請の段階で一定の支援が必要だということを保護者の方からお申し出があった場合には。医療行為が必要というようなお子さんに関しては、お断りせざるを得ないということで… 認可保育園の開設ですが、前回の委員会において４園ご紹介させていただきましたが、そのほかにも今複数の園につきまして協議調整を進めているところですので、今後とも全力で開設に向け努力してまいりたいと思います。","id":"exchange-021"},{"speaker":"沢田副委員長","kind":"確認","question":"指数が同一の場合、区内在住年数の長いものと４番にあるようなのですけれども、これはそもそも誰の区内在住年数なのか。本人、お子さんが区内在住なのか、保護者なのか、その辺の確認したいと求めました。","respondent":"竹田保育課長","answer":"保護者の方の在住年数としています。","id":"exchange-022"},{"speaker":"沢田副委員長","kind":"質問","question":"いろいろなお考えで決められていることだと思うのですが、どういうふうに決められているのか、教えてほしいと求めました。","respondent":"竹田保育課長","answer":"区内の方には３点加点しておりますが、区外から転居予定だという方については、こちらは加点から外して一定程度この４月より差をつけております。委員のご指摘を踏まえて、今後より検討して見直しを進めていきたいと考えております。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"確認","question":"これは私も勉強不足で確認なのですけれども、指数、所得の両方を出してきたということ等の理由を一つ確認したい。先ほども０歳から１歳はなかなかというところがこれを見ると余計にわかってくるのですけれども、方向性を一つ、確認したいと思います。","respondent":"竹田保育課長","answer":"そして相談業務の充実という点から考えまして、階層まで今回お示しする必要があるというふうに考えまして、階層のほうまで明記しています。こちらの数字が一人歩きしないように十分説明を尽くしてご理解いただくように努めてまいりたいと考えております。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、何か先ほども注意されるとお話があったのですけれども、今お話があったように数字が一人歩きするというところが問題になるかと思います。最後に確認なのですが、１５の方が仮にいたとすると入っていないと、同じ４０で入っていないということでよろしいのか尋ねました。","respondent":"竹田保育課長","answer":"こちらはあくまでも１次選考時の数字だけということを十分ご説明して、誤解のないようにしたいと思います。１４で、同数で入れなかった方がいらっしゃった場合は、ほかの園もこの方はご希望されていますので、そういった具体な状況などもご案内しています。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"確認","question":"先ほど説明があったのかもしれないのですけれども、確認したいのですが、定員割れというのはどういう意味なのか尋ねました。","respondent":"竹田保育課長","answer":"こちらはまだ定員に余裕がありますが、お申し込みがなかったですので、仮にお申し込みがあれば、入れる状況ですです。","id":"exchange-026"},{"speaker":"あべ委員","kind":"確認","question":"２歳で終わって、３歳で移らなければいけない中で、結構ぎりぎりのところに３歳は来ているのかなと。認識は確認したのですけれども、あるいは今後どのように考えていかれるのか。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"３歳に限らず、一部の園の一部の年齢に指数の高いところがあります。３歳につきましては４０点前後で各園ともありますので、今逼迫した状況にあるというふうには考えてございません。 もう一つ、調整指数の大まかなものは各２３区同じですが、若干点数の差はあります。この調整指数、必要な定員というものも見ていただくということで議会の皆様からもご意見を頂戴したいと考えていますので、よろしくお願いいたします。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"それで伺いました。どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"関係機関職員というのがあるのですけれども、例えばどういった方になるのか教えてほしいと求めました。学校地域コーディネーターが区の非常勤になるということですけれども、勤務日数というのは、１週間で言うとどのくらいになるのか尋ねました。","respondent":"熊谷指導課長","answer":"どのようなボランティアが必要かということをしっかり理解した上で学校支援地域本部につなぎ、そういった支援が必要な内容。具体的な仕事内容につきましては、これからまた新たな動きというのも出てくることが考えられると思います。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、今のところ、コーディネーターの方の主な仕事というのは、校区教育協働委員会の求めるボランティアを紹介するということでいいのか、ちょっと確認させてほしいと求めました。","respondent":"熊谷指導課長","answer":"最初の一歩ということですので、ただ、それぞれがそれぞれで学校を支援してきたという経緯があります。例えば、学校支援地域本部という組織をつくるための準備をしていくのもコーディネーターの役目だというふうにお伝えできるかと思います。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"この教員というのは一人ひとりの教師の方ということなのか、それとも校長とか副校長という指導する方が異動してしまうということなのか、そこの確認をさせてほしいと求めました。","respondent":"熊谷指導課長","answer":"教員の異動、特に管理職の異動があっても、それを継続してやっていくということができます。その先生がやってきている教育活動、それを継続して引き継いでいけるようにということで、この目的のところで挙げてあります。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"ちょっと繰り返しになってしまうかもしれませんが、その意義といいますか、必要性をもう少し詳しく教えてほしいと求めました。現場の教員の方がやりたいことがちょっと違う方向に行ってしまう可能性がないのかなと危惧してしまうのですが、その辺の担保性を教えていただきたい。","respondent":"熊谷指導課長","answer":"１点目と２点目と重なるところがあると思うのですけれども、校長経営方針、校区教育協働委員会が学校への基本方針を承認しています。それから２点目なのですけれども、反対にさまざまここで練ったこと、反対に地域と学校が一体となって進めていく学校運営が可能であると思います。","id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"どこまでこの地域のコーディネーターがやっていくのかというところを教えていただきたいのですが、そこら辺も教えてほしいと求めました。現状として、どのように町会、自治会との連携がされているのか、どれぐらい理解が進んでいるのかを教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"町会の代表の方が入っていらっしゃいますので、そういったところで具体的な説明をしながら進めていくことも重要だと考えています。そのまま学校支援地域本部に移行していくというような方々、そういった部分も含めてより一層丁寧に説明をしていくことが重要だと思っています。","id":"exchange-033"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後また平成２９年度、平成３０年度においては全校に拡大されてまいりますので、それぞれ地域とのやりとりをしっかり細かくやっていただいて、それぞれがいい方向で進んでいけるようにやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ責任者をそれぞれ探し出していただきたいと、これは要望になりますけれども、コーディネーターをぜひ大切にしてほしいと求めました。その２点がコミュニティ・スクールとして今私の気になるところですので、それぞれご意見を伺えればと思います。","respondent":"熊谷指導課長","answer":"それから２点目なのですけれども、卒業生のということで、４校で大学生が卒業生ということで入ってきています。そういった学生からのつながりで、学校支援地域本部もいろいろなグループが、支援グループができてほしいなと思っています。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問・要望","question":"コーディネーターの相談窓口というのは非常にいいことだと思いますし、卒業生の大学生の方々、ただ、現場で使うだけではなくて、その人たちそれぞれが同級生や先輩、後輩のネットワークを持っていらっしゃるでしょうから、ぜひ存分に活用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうかとわかるような表記を少し考えてほしいと思ったのと、今日２枚目を見ると、関係が以前よりもよくわかってきたかなと思います。そういった状況になっていってほしいなと思うのですけれども、形は備わってきて、ぜひ在校生の位置づけもきちんとしていただきたいなと考えています。","respondent":"熊谷指導課長","answer":"ここでは評価だけではなくて、もっと主体的に学校への基本方針も承認するなど、それから特色ある教育活動を地域とともに一層進めていくために。多く質問があったのは、これまでと何が変わるのかというところが多かったというふうに聞いています。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多分前にもちょっと伺ったかもしれないのですけれども、このメンバーがどのように選ばれてというか、周知したりしているのか。そういった意味で、もっと主体的な仕事ができるところにしていく必要があるのではないかと考えていますが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"これはどういった方法でというのは、それぞれ学校で異なりますので、こういったやり方でというのはお話しすることは難しいと思います。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほども卒業生がメンバーに参加していらっしゃるというのを伺いましたけれども、あと２枚目のところにあるように、負担がいっぱい一部に加わらないようにいろいろ工夫してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"どうなのかなというのがあるので、今回も１５校で既にできるわけですから、そのあたりを伺います。","respondent":"熊谷指導課長","answer":"準備は整っていて、来年やりたいと思っていらっしゃる学校もあれば、ゆっくり時間をかけて保護者や地域に説明していきたいという学校もあります。それから学校の状況ということも考えながら、来年、再来年度で全校展開していきたいと考えているところです。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"確認","question":"一部地域、それとも全体なのかはちょっとあれなのですけれども、地区委員会での説明もあったとお聞きしています。その地域、地区委員会で説明会に出られたということは大変いいことだと聞いているのですが、１３地区全部でやられているのか一つ確認したいのですが。","respondent":"熊谷指導課長、品川庶務課長","answer":"その前に、区政協力委員会で説明をしています。その後で、町会長会議で具体的に説明を１３地区させていただいています。 地区委員会につきましては、一部説明等を行っているところもあるのですが、全地区につきましては、また検討して進めていきたいと考えています。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこが関連する地域は今年度中にできればお話をすると５月のイベントでどうとかできると思うので、ぜひ今年度中に来年の予定を１６校でしょうか。それをうまくネットワークで協力していただけるような仕組みを理解していただくというか、それは有効だと思うのですが、その辺はいかがか尋ねました。","respondent":"熊谷指導課長","answer":"実際にこういうところで困っているのだけれどもというような悩みを共有することで連携していけるようなシステムづくりはそこでしております。さらに学校支援地域本部のグループに卒業生を、また応援してもらえるように教員の情報共有を大事にしていきたいと思っています。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"意見","question":"コーディネーターだけの人脈だと限られてしまうので、できるだけ多くのそういった広がりが持てるといいかなというふうに思っています。ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどＰＴＡ関係をとおっしゃっておられたのですが、１５校の中身は実際にどうなのか教えていただきたいのが一つです。教育内容の介入になってはならないと思うのですが、この意見を聞くというのは、どういった中身を期待しているものなのかという点を説明するよう求めました。","respondent":"熊谷指導課長","answer":"やはり元ＰＴＡの会長と、お一方だけお友達という方もいますけれども、そういったメンバーです。意見なのですが、体力向上をもっともっと進めていきたいというようなときに、または指導助手がというようなことを意見として出していくです。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"１５校はＰＴＡの会長がほとんどということで、きちんと聞いていなくてごめんなさい。区費の固有の教員をこういった意見を聞いて充実させていく、新たに採用していくというところまで考えていることなのかどうか説明を求めました。","respondent":"熊谷指導課長","answer":"なぜそういった先生が必要なのかということをしっかりここで練って、そして承認を得て出していくということになりますので、それを踏まえてご意見を聞いていきたいと考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、コーディネーターの任期というのはあるのか尋ねました。","respondent":"熊谷指導課長","answer":"コーディネーターの任用期間なのですけれども、非常勤職員ですので１年間を単位として任用します。ただ、教育委員会教育長が特に必要と認める場合は、また再度更新することは可能です。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、基本的には１年交代と考えればよろしいのか尋ねました。","respondent":"熊谷指導課長","answer":"基本原則として１年を任期としていますが、先ほどお話ししたように更新していくことは可能です。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"周りは一般の先生方ですので、できるだけ外から来た感がないように先生方の温かいおもてなしといいますか、やはり仕事がしづらいと思うのですね。ですから、そういうところをぜひ配慮していただきたいということと、そこのところを最後にお願いします。","respondent":"熊谷指導課長","answer":"非常勤職員ということで、高橋しんじ委員がおっしゃったとおり職員室に机があります。一緒に考えていくということで、校長、副校長を含めてしっかり理解させるようにしています。","id":"exchange-048"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"すみません、所管事務調査なので、私からも伺わせていただきます。全国で６,８１４校やっているという中で、何かそういうものがあるのかどうか、それについて教えてほしいと求めました。","respondent":"熊谷指導課長、中島教育長","answer":"では、１点目のほうをお答えしたいと思うのですけれども、国のコミュニティ・スクールなのですが、こちらは学校運営協議会を設置します。品川区の特性を考えたときに… 中には、学校支援地域本部というものだけが中心となってコミュニティ・スクールになってきているようなケースもありますし。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":38630,"voices":122}}]);
